// Cyrus Test Flight (R0) types: the typed spec a caller writes, the resolved spec the node-2 runner receives,
// and the report it returns. The runner is services/modbuilder/tools/testflight/runner.js (plain Node on node-2).
// A check passes only if it actually ran; a skipped required check means the flight is NOT a success.
import type { PlaytestPlan } from "../playtest/plan";

export const CHECK_IDS = ["boot_done", "plugins_enabled", "startup_log_clean", "rcon_checks", "playtest", "clean_stop", "no_leaks"] as const;
export type CheckId = (typeof CHECK_IDS)[number];
export type CheckStatus = "pass" | "fail" | "not_run";

/** A regex matched against each log line (JS syntax; flags limited to i/m/s/u). */
export type LogMatcher = { id: string; pattern: string; flags?: string };

/** A small text file in the server directory (e.g. a plugin's config). Path relative to the server root, under plugins/ only. */
export type ServerFile = { path: string; content: string };

export type SeedRef = { from: string; to: string };

export type RconCheck = {
  id?: string;
  /** Written (created or replaced) in the server dir right before this command is sent, e.g. to test a config reload. */
  writeFile?: ServerFile;
  /** Wait this long (ms, max 30000) before sending the command (after writeFile), e.g. for a file watcher. */
  waitMs?: number;
  /** One console command without the leading slash. stop/restart/op/deop/reload are reserved for the runner. */
  command: string;
  /** Every substring must appear in the reply (colour codes stripped). Empty = the command only has to answer. */
  expect?: string[];
  /** None of these may appear. */
  expectNot?: string[];
  /** Default true. An optional check is reported but does not fail the stage. */
  required?: boolean;
};

/** An artifact either on the caller's disk (uploaded by the invoker) or already on node-2 under the Test Flight root. */
export type ArtifactRef = { localPath: string; remotePath?: never; sha256?: string } | { remotePath: string; localPath?: never; sha256?: string };

export type TestFlightSpec = {
  /** Exact registry id, e.g. "26.2" or "1.21.11". The registry supplies the JDK and the pinned Paper server jar. */
  version: string;
  plugins?: ArtifactRef[];
  /** Datapacks go into world/datapacks before first boot; each one adds an automatic `datapack list enabled` check. */
  datapacks?: (ArtifactRef & { name: string })[];
  /** Written to server.properties only. No client connects, so the pack itself is NOT exercised (reported as such). */
  resourcePack?: { url: string; sha1?: string; id?: string; required?: boolean };
  /** Small text files placed before the first boot (max 16, 64 KB each, under plugins/). */
  files?: ServerFile[];
  /**
   * Read-only directories prepared on node-2 under `<root>/seeds/<from>` copied into the server dir before boot
   * (`to` = "libraries" or a path under plugins/). The flight has no internet, so a managed plugin's pinned runtime
   * libraries are seeded this way (runner tf-lite-2).
   */
  seeds?: SeedRef[];
  /** Server-dir files copied out after the stop to `<root>/collect/<runId>/` (a path ending in "/" = a listing). */
  collect?: string[];
  rcon?: RconCheck[];
  /** Replace the runner's default startup-log matchers (omit to use the defaults). */
  logMatchers?: LogMatcher[];
  /** Extra ignore patterns, added to the runner's sandbox ignores. */
  logIgnore?: LogMatcher[];
  timeouts?: { bootSec?: number; rconSec?: number; stopSec?: number; totalSec?: number };
  /** xmxMb max 1024 (node-2 rule). rssCapMb is a watchdog: above it the server is killed and the run fails. */
  memory?: { xmxMb?: number; rssCapMb?: number };
  /** Extra stages to treat as required even if the spec would not make them required. */
  requireStages?: CheckId[];
  /** Keep the server dir on node-2 for debugging (default false). */
  keepDir?: boolean;
  /** World options (runner tf-lite-3): generateStructures turns structure generation on (default off: a tiny flat world). */
  world?: { generateStructures?: boolean };
  /** Playtest (runner tf-lite-4): a scripted Mineflayer player runs these scenarios after the RCON checks. Makes `playtest` required. */
  playtest?: PlaytestPlan;
};

/** What the runner receives: registry pins resolved, artifact paths on node-2. */
export type ResolvedSpec = {
  schema: 1;
  runId: string;
  version: string;
  javaRelease: 21 | 25;
  paper: { build: number; sha256: string };
  plugins: { path: string; sha256?: string }[];
  datapacks: { path: string; name: string }[];
  resourcePack?: TestFlightSpec["resourcePack"];
  files?: ServerFile[];
  seeds?: SeedRef[];
  collect?: string[];
  rcon: RconCheck[];
  logMatchers?: LogMatcher[];
  logIgnore?: LogMatcher[];
  timeouts: { bootSec: number; rconSec: number; stopSec: number; totalSec: number };
  memory: { xmxMb: number; rssCapMb: number };
  keepDir: boolean;
  world?: { generateStructures?: boolean };
  playtest?: PlaytestPlan;
};

export type CheckResult = { id: CheckId; status: CheckStatus; required: boolean; evidence: string[]; durationMs: number };

export type ReportArtifact =
  | { kind: "plugin"; file: string; sha256: string; pluginName: string | null; apiVersion: string | null; descriptor: string | null }
  | { kind: "datapack"; name: string; sha256: string | null; directory: boolean }
  | { kind: "resourcePack"; url: string; sha1: string | null; exercised: false }
  | { kind: "seed"; from: string; to: string; files: number; bytes: number; sha256: string };

/** A collected server file (runner tf-lite-2) or a directory listing. */
export type CollectedItem = { path: string; kind?: "file" | "listing"; bytes?: number; sha256?: string; dest?: string; entries?: number; listing?: string[]; error?: string };

export type EngineMeta = {
  runner: string;
  runnerSha256: string;
  node: string;
  host: string;
  kernel: string;
  jdk: { release: number; version: string | null; dist: string; sha256: string };
  paper: { version: string; build: number; sha256: string; channel: string | null };
  isolation: { netns: string; uid: number; noNewPrivs: boolean; nice: number; activeProcessorCount: number };
  /** Runner tf-lite-4, flights with a playtest: the pinned bot lockfile and the versions it was verified on. */
  bot?: { lockSha256: string; versions: string[] };
};

/** Raw runner output. `status` says whether the runner itself completed; `overall` is its own verdict (recomputed by summarize). */
export type TestFlightReport = {
  schema: 1;
  runId: string | null;
  status: "completed" | "busy" | "error";
  version: string | null;
  javaRelease: number | null;
  startedAt: string;
  finishedAt: string | null;
  checks: CheckResult[];
  timings: Record<string, number>;
  bootMs: number | null;
  doneReportedSec: number | null;
  peakRssKb: number | null;
  artifacts: ReportArtifact[];
  engine: EngineMeta | null;
  notes: string[];
  overall: "passed" | "failed" | "incomplete";
  collected?: CollectedItem[];
  /** Runner tf-lite-4: the playtest bot's result (lib/cyrus/playtest/verdict.ts PlaytestRunResult). */
  playtest?: unknown;
};

export type Overall = "passed" | "failed" | "incomplete" | "busy" | "error";

export type TestFlightSummary = {
  version: string;
  overall: Overall;
  /** true only when overall === "passed". */
  success: boolean;
  passed: CheckId[];
  failed: CheckId[];
  /** Required checks that did not run (or "passed" without evidence): any entry here blocks success. */
  skippedRequired: CheckId[];
  notRunOptional: CheckId[];
  reasons: string[];
  bootMs: number | null;
  peakRssKb: number | null;
  runId: string | null;
};

export type MatrixSummary = { overall: Overall; success: boolean; versions: TestFlightSummary[] };
// Cyrus R5: the TEST FLIGHT GATE (pure half). After a build succeeds and scans clean, the worker boots it once on a
// disposable Paper server for the build's own version (node-2, ./client.ts) with its jar, its data packs and (when the
// Pack Loader jar is available) its pack config, and stores an HONEST per-check result on the build:
//   compile, scan, boot, plugins enabled, commands registered, data pack loaded  (each pass / fail / not_run)
// "not run" is never shown as passed; the verdict only ever feeds a "boot-tested on <version>" label (a boot proves
// the plugin loads and its commands register, never how it behaves in game). Optional: block publishing / installing a
// build whose flight FAILED (CYRUS_TESTFLIGHT_BLOCK_ON_FAIL=1).
// Flags (all OFF): CYRUS_TESTFLIGHT_GATE=1 runs flights; CYRUS_TESTFLIGHT_BLOCK_ON_FAIL=1 blocks on a failed flight.
// Limits: one flight at a time per worker (node-2 runs one anyway; "busy" is retried with backoff), at most
// MAX_FLIGHTS_PER_BUILD real flights per build (per-build cost cap) and MAX_BUSY_RETRIES busy retries.
import { getVersion } from "../versions/registry";
import type { CheckResult, RconCheck, TestFlightReport, TestFlightSpec, TestFlightSummary } from "./types";

export const GATE_FLAG = "CYRUS_TESTFLIGHT_GATE";
export const BLOCK_FLAG = "CYRUS_TESTFLIGHT_BLOCK_ON_FAIL";
export const MAX_FLIGHTS_PER_BUILD = 2;
export const MAX_BUSY_RETRIES = 12;
export const MAX_COMMAND_CHECKS = 8;
export const GATE_VERSION = "tfgate-1";

export const GATE_CHECKS = ["compile", "scan", "boot", "plugins_enabled", "commands_registered", "datapack_loaded"] as const;
export type GateCheckId = (typeof GATE_CHECKS)[number];
export type GateCheck = { id: GateCheckId; status: "pass" | "fail" | "not_run"; detail: string };
export type GateVerdict = "passed" | "failed" | "incomplete" | "not_run";

/** What is stored on ModBuild.cyrus.testFlight (plain JSON, small). */
export type StoredFlight = {
  schema: 1;
  gate: string;
  state: "queued" | "running" | "done" | "not_run" | "gave_up";
  version: string;
  verdict: GateVerdict;
  /** "boot-tested on Paper <version>" only when every required check passed; never about in-game behaviour. */
  label: string | null;
  checks: GateCheck[];
  reason?: string;
  flights: number;
  busyRetries: number;
  nextAt?: string;
  lastError?: string;
  runId?: string | null;
  bootMs?: number | null;
  peakRssKb?: number | null;
  engine?: { runner?: string; paperBuild?: number; jdk?: string | null } | null;
  notes?: string[];
  /** Wiring 2 (CYRUS_PLAYTEST): the playtest bots' verdict from the build's stored ModSpec, kept APART from the boot
   *  verdict (a playtest never changes `verdict` / `label`). Absent = the switch was off. */
  playtest?: { verdict: "passed" | "failed" | "incomplete" | "not_run"; label: string; counts?: { planned: number; ran: number; passed: number; failed: number; notRun: number }; scenarios?: { id: string; status: string; reason: string | null }[]; specRevisionId?: string | null } | null;
  /** R42: the vanilla reference checks of the build's packs (copied from ModBuild.result.assets.vanilla). Never changes
   *  `verdict` / `label`: a pack that overrides vanilla still boots; this is a warning for the owner and the customer. */
  vanilla?: { status: "checked" | "not_run"; version: string; counts: { error: number; warn: number; info: number }; issues: { code: string; severity: string; path: string; message: string }[] } | null;
  at: string;
};

export type GateBuild = {
  id: string; mcVersion: string; pluginName: string | null; jarSha256: string | null;
  /** ModBuild.result: commands + safety are read from it. */
  result: unknown;
};
export type GateArtifacts = {
  jarPath: string;
  datapacks: { name: string; localPath: string }[];
  /** The Pack Loader jar + the packs.json this build's pack would get (when both are available). */
  packLoader?: { localPath: string; sha256: string; config: string } | null;
};

/** Can this version be test-flown at all? (a pinned Paper SERVER build is needed). */
export function flightVersion(v: string): { ok: true } | { ok: false; reason: string } {
  const row = getVersion(v);
  if (!row) return { ok: false, reason: `not run: ${v} is not in the version registry` };
  if (!row.paperBuild || !row.paperServerSha256) return { ok: false, reason: `not run: no test server for ${v} (no pinned Paper server build)` };
  return { ok: true };
}

type Cmd = { usage?: string };
/** Command labels the build says it has (from ModBuild.result.commands usage, e.g. "/alpha give <p>" -> alpha). */
export function commandLabels(result: unknown): string[] {
  const cmds = ((result as { commands?: Cmd[] } | null)?.commands ?? []) as Cmd[];
  const out: string[] = [];
  for (const c of cmds) {
    const m = /^\/([a-z0-9_-]{1,32})(?:\s|$)/i.exec(String(c?.usage ?? "").trim());
    if (m && !out.includes(m[1].toLowerCase())) out.push(m[1].toLowerCase());
  }
  return out.slice(0, MAX_COMMAND_CHECKS);
}

export function scanVerdict(result: unknown): "pass" | "warn" | "block" | null {
  const v = (result as { safety?: { verdict?: string } | null } | null)?.safety?.verdict;
  return v === "pass" || v === "warn" || v === "block" ? v : null;
}

/** The flight spec for one build, or why it is not run. */
export function planGateFlight(b: GateBuild, art: GateArtifacts): { ok: true; spec: TestFlightSpec; commands: string[] } | { ok: false; reason: string } {
  const fv = flightVersion(b.mcVersion);
  if (!fv.ok) return fv;
  if (!b.pluginName) return { ok: false, reason: "not run: the build has no plugin name" };
  const sv = scanVerdict(b.result);
  if (sv === "block") return { ok: false, reason: "not run: the safety scan blocked this build" };
  const commands = commandLabels(b.result);
  const rcon: RconCheck[] = [
    { id: "plugins", command: "plugins", expect: [b.pluginName] },
    // Paper answers `help <label>` with the command's help topic when it is registered, "No help for" otherwise
    ...commands.map((c) => ({ id: `cmd-${c}`, command: `help ${c}`, expectNot: ["No help for"], required: false })),
  ];
  const plugins: TestFlightSpec["plugins"] = [{ localPath: art.jarPath, ...(b.jarSha256 ? { sha256: b.jarSha256 } : {}) }];
  const files: TestFlightSpec["files"] = [];
  if (art.packLoader) {
    plugins.push({ localPath: art.packLoader.localPath, sha256: art.packLoader.sha256 });
    files.push({ path: "plugins/NxeonPackLoader/packs.json", content: art.packLoader.config });
    rcon.push({ id: "packs", command: "nxpacks status", expect: ["config=ok"], required: false });
  }
  return { ok: true, commands, spec: { version: b.mcVersion, plugins, datapacks: art.datapacks.map((d) => ({ name: d.name, localPath: d.localPath })), ...(files.length ? { files } : {}), rcon, timeouts: { bootSec: 180, totalSec: 420 } } };
}

const check = (r: TestFlightReport, id: CheckResult["id"]) => r.checks.find((c) => c.id === id) ?? null;
const ev = (c: CheckResult | null, n = 2) => (c ? c.evidence.slice(0, n).join(" | ").slice(0, 300) : "");

/** Map one flight to the six honest statuses. */
export function gateChecks(b: GateBuild, r: TestFlightReport | null, s: TestFlightSummary | null, o: { commands: string[]; datapacks: number; reason?: string }): GateCheck[] {
  const sv = scanVerdict(b.result);
  const nr = (id: GateCheckId, detail: string): GateCheck => ({ id, status: "not_run", detail });
  const out: GateCheck[] = [
    { id: "compile", status: "pass", detail: "compiled by the build service" },
    sv === null ? nr("scan", "no scan result stored") : { id: "scan", status: sv === "block" ? "fail" : "pass", detail: sv === "warn" ? "passed with warnings" : sv === "block" ? "blocked by the safety scan" : "clean" },
  ];
  if (!r || r.status !== "completed" || !s) {
    const why = o.reason ?? (r?.status === "busy" ? "not run: the test server was busy" : r ? `not run: ${r.status}` : "not run");
    return [...out, nr("boot", why), nr("plugins_enabled", why), nr("commands_registered", why), nr("datapack_loaded", o.datapacks ? why : "no data pack in this build")];
  }
  const boot = check(r, "boot_done"), pe = check(r, "plugins_enabled"), rc = check(r, "rcon_checks");
  const st = (c: CheckResult | null): GateCheck["status"] => (!c ? "not_run" : c.status === "pass" && c.evidence.length ? "pass" : c.status === "fail" ? "fail" : "not_run");
  out.push({ id: "boot", status: st(boot), detail: ev(boot) || "no evidence" });
  out.push({ id: "plugins_enabled", status: st(pe), detail: ev(pe) || "no evidence" });
  // commands: each `cmd-<label>` evidence line says ok / FAILED; none sent = not_run
  const lines = rc?.evidence ?? [];
  const cmdLines = o.commands.map((c) => lines.find((l) => l.startsWith(`cmd-${c} `)) ?? null);
  if (!o.commands.length) out.push(nr("commands_registered", "the build lists no commands"));
  else if (cmdLines.some((l) => l === null)) out.push(nr("commands_registered", `${cmdLines.filter((l) => l === null).length} command check(s) did not run`));
  else out.push({ id: "commands_registered", status: cmdLines.every((l) => /: ok/.test(l!)) ? "pass" : "fail", detail: cmdLines.map((l) => l!.slice(0, 80)).join(" | ").slice(0, 300) });
  if (!o.datapacks) out.push(nr("datapack_loaded", "no data pack in this build"));
  else {
    const dl = lines.find((l) => l.startsWith("datapacks-enabled "));
    out.push(dl ? { id: "datapack_loaded", status: /: ok/.test(dl) ? "pass" : "fail", detail: dl.slice(0, 300) } : nr("datapack_loaded", "the data pack check did not run"));
  }
  return out;
}

/** Verdict + label from the runner summary (the summary already refuses success when a required stage was skipped). */
export function gateVerdict(s: TestFlightSummary | null, checks: GateCheck[]): { verdict: GateVerdict; label: string | null } {
  if (!s) return { verdict: "not_run", label: null };
  if (s.overall === "busy" || s.overall === "error") return { verdict: "not_run", label: null };
  const anyFail = checks.some((c) => c.status === "fail" && c.id !== "commands_registered") || s.overall === "failed";
  if (anyFail) return { verdict: "failed", label: null };
  if (!s.success) return { verdict: "incomplete", label: null };
  return { verdict: "passed", label: `boot-tested on Paper ${s.version}` };
}

/** R42: the build's vanilla check summary (ModBuild.result.assets.vanilla), trimmed for the flight record. null = not run. */
export function vanillaOf(result: unknown): StoredFlight["vanilla"] {
  const v = (result as { assets?: { vanilla?: unknown } } | null)?.assets?.vanilla as NonNullable<StoredFlight["vanilla"]> | undefined;
  if (!v || typeof v !== "object" || (v.status !== "checked" && v.status !== "not_run") || !v.counts) return null;
  return { status: v.status, version: String(v.version), counts: { error: Number(v.counts.error) || 0, warn: Number(v.counts.warn) || 0, info: Number(v.counts.info) || 0 }, issues: (Array.isArray(v.issues) ? v.issues : []).slice(0, 8) };
}
/** One note line for a checked summary with problems, or null. */
export function vanillaNote(v: StoredFlight["vanilla"]): string | null {
  if (!v || v.status !== "checked" || !(v.counts.error + v.counts.warn)) return null;
  return `vanilla check (${v.version}): ${v.counts.error} error(s), ${v.counts.warn} warning(s)${v.issues[0] ? `, e.g. ${v.issues[0].path}: ${v.issues[0].message}` : ""}`.slice(0, 300);
}

export const backoffMs = (busyRetries: number) => Math.min(10 * 60_000, 30_000 * 2 ** Math.max(0, busyRetries));

/** Read a stored result back (tolerant). */
export function readStoredFlight(raw: unknown): StoredFlight | null {
  if (!raw || typeof raw !== "object" || Array.isArray(raw)) return null;
  const r = raw as StoredFlight;
  return r.schema === 1 && typeof r.state === "string" && Array.isArray(r.checks) ? r : null;
}

/** Is this build due a flight now? (pure scheduling) */
export function dueForFlight(stored: StoredFlight | null, now: Date): boolean {
  if (!stored) return true;
  if (stored.state === "queued") return !stored.nextAt || new Date(stored.nextAt).getTime() <= now.getTime();
  if (stored.state === "running") return new Date(stored.at).getTime() < now.getTime() - 30 * 60_000; // a worker died mid-flight
  return false;
}

/** Optional gate on publish / install: only a FAILED flight blocks, and only with the flag on. "Not run" never blocks. */
export function flightBlocks(stored: unknown, env: Record<string, string | undefined> = process.env): { blocked: false } | { blocked: true; reason: string } {
  if (env[BLOCK_FLAG] !== "1") return { blocked: false };
  const f = readStoredFlight(stored);
  if (f?.state === "done" && f.verdict === "failed") {
    const bad = f.checks.filter((c) => c.status === "fail").map((c) => c.id.replace(/_/g, " "));
    return { blocked: true, reason: `This version failed its Test Flight on Paper ${f.version} (${bad.join(", ") || "boot"}). Fix it with a change request before installing or publishing it.` };
  }
  return { blocked: false };
}

/** Customer-facing lines for the NxLabs mod page (honest: not run is never shown as passed). */
export function flightLines(stored: unknown): string[] {
  const f = readStoredFlight(stored);
  if (!f) return [];
  const name: Record<GateCheckId, string> = { compile: "Compiles", scan: "Safety scan", boot: "Server boots", plugins_enabled: "Plugin enables", commands_registered: "Commands register", datapack_loaded: "Data pack loads" };
  const word = { pass: "passed", fail: "FAILED", not_run: "not run" } as const;
  const head = f.label ? `Boot-tested on Paper ${f.version} (a real server started with this version; this does not test gameplay).`
    : f.verdict === "failed" ? `Failed its boot test on Paper ${f.version}.`
    : f.state === "queued" || f.state === "running" ? `Boot test on Paper ${f.version} is queued.`
    : `Not boot-tested${f.reason ? `: ${f.reason.replace(/^not run: /, "")}` : ""}.`;
  return [head, ...f.checks.map((c) => `${name[c.id]}: ${word[c.status]}`)];
}

// Cyrus R5 Test Flight gate, worker half (SERVER ONLY). A sweep picks recent succeeded builds without a stored flight
// (or whose busy retry is due), runs ONE flight per tick through the injectable Test Flight invoker (./client.ts,
// ssh to node-2), and stores the result on ModBuild.cyrus.testFlight (atomic jsonb merge). OFF unless
// CYRUS_TESTFLIGHT_GATE=1: off, the sweep returns before any database read.
// Wiring 2: with CYRUS_PLAYTEST=1 as well, the build's stored ModSpec (CyrusRevision.spec of the revision linked to the
// build) becomes a playtest plan flown in the SAME flight; its verdict is stored apart (StoredFlight.playtest) and never
// changes the boot verdict or the install block. No stored spec = "not run", never a pass.
// Never runs inside a request handler. One flight at a time per process (`inFlight`), node-2 also serialises.
import { mkdtempSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import path from "node:path";
import { GATE_FLAG, GATE_VERSION, MAX_BUSY_RETRIES, MAX_FLIGHTS_PER_BUILD, backoffMs, dueForFlight, gateChecks, gateVerdict, planGateFlight, readStoredFlight, vanillaNote, vanillaOf, type GateArtifacts, type GateBuild, type StoredFlight } from "./gate";
import type { RunResult } from "./client";
import type { TestFlightSpec } from "./types";
import { summarize } from "./summary";
import { planFromSpec, playtestEnabled, playtestVerdict, playtestVersion, withPlaytest, type PlaytestPlan, type TestCoverage } from "../playtest";
import type { ModSpec } from "../engine-core/spec";

export type GateDeps = {
  env?: Record<string, string | undefined>;
  now?: () => Date;
  /** Recent succeeded builds (newest first) with their stored cyrus meta. */
  candidates(limit: number): Promise<(GateBuild & { cyrus: unknown; finishedAt: Date | null })[]>;
  /** Where the build's jar is on this host, and its data packs / pack config written to `dir` for the flight. */
  artifacts(b: GateBuild, dir: string): Promise<GateArtifacts>;
  run(spec: TestFlightSpec): Promise<RunResult>;
  store(buildId: string, flight: StoredFlight): Promise<void>;
  /** Wiring 2: the build's stored ModSpec (the revision linked to the build), for the playtest bots. Absent/null = none. */
  spec?(b: GateBuild): Promise<{ spec: ModSpec; revisionId: string | null } | null>;
};

type Playtest = { plan: PlaytestPlan; coverage: TestCoverage[]; revisionId: string | null } | { notRun: string; revisionId: string | null } | null;

/** CYRUS_PLAYTEST: a plan from the build's stored ModSpec, flown in the SAME flight as the boot checks. null = off. */
export async function playtestFor(b: GateBuild, deps: GateDeps, env: Record<string, string | undefined>): Promise<Playtest> {
  if (!playtestEnabled(env)) return null;
  const s = deps.spec ? await deps.spec(b).catch(() => null) : null;
  if (!s) return { notRun: "not run: this build has no stored ModSpec", revisionId: null };
  if (s.spec.target.version !== b.mcVersion) return { notRun: `not run: the ModSpec targets ${s.spec.target.version}, the build is for ${b.mcVersion}`, revisionId: s.revisionId };
  const pv = playtestVersion(b.mcVersion);
  if (!pv.ok) return { notRun: pv.reason, revisionId: s.revisionId };
  const gen = planFromSpec(s.spec);
  if (!gen.plan) return { notRun: "not run: no acceptance test could be scripted", revisionId: s.revisionId };
  return { plan: gen.plan, coverage: gen.coverage, revisionId: s.revisionId };
}

let inFlight = false;

export async function testFlightGateSweep(deps: GateDeps, opts: { maxFlights?: number; lookback?: number } = {}): Promise<{ ran: number; queued: number; notRun: number; skipped: string | null }> {
  const env = deps.env ?? process.env;
  if (env[GATE_FLAG] !== "1") return { ran: 0, queued: 0, notRun: 0, skipped: "switched off" };
  if (inFlight) return { ran: 0, queued: 0, notRun: 0, skipped: "a flight is already running in this worker" };
  inFlight = true;
  const now = deps.now ?? (() => new Date());
  let ran = 0, queued = 0, notRun = 0;
  try {
    const rows = await deps.candidates(opts.lookback ?? 50);
    for (const b of rows) {
      if (ran >= (opts.maxFlights ?? 1)) break;
      const prev = readStoredFlight((b.cyrus as { testFlight?: unknown } | null)?.testFlight);
      if (!dueForFlight(prev, now())) continue;
      const r = await flyOne(b, prev, deps, now);
      if (r === "ran") ran++; else if (r === "queued") queued++; else notRun++;
    }
  } finally { inFlight = false; }
  return { ran, queued, notRun, skipped: null };
}

const base = (b: GateBuild, prev: StoredFlight | null, now: Date): StoredFlight => ({ schema: 1, gate: GATE_VERSION, state: "queued", version: b.mcVersion, verdict: "not_run", label: null, checks: [], flights: prev?.flights ?? 0, busyRetries: prev?.busyRetries ?? 0, at: now.toISOString() });

export async function flyOne(b: GateBuild, prev: StoredFlight | null, deps: GateDeps, now: () => Date): Promise<"ran" | "queued" | "not_run"> {
  const cur = base(b, prev, now());
  if (cur.flights >= MAX_FLIGHTS_PER_BUILD) { await deps.store(b.id, { ...prev!, state: "gave_up", reason: `not run: the per-build limit of ${MAX_FLIGHTS_PER_BUILD} flights was reached`, at: now().toISOString() }); return "not_run"; }
  const dir = mkdtempSync(path.join(tmpdir(), "cyrus-tfgate-"));
  try {
    let art: GateArtifacts;
    try { art = await deps.artifacts(b, dir); }
    catch (e) { const reason = `not run: ${(e as Error).message}`.slice(0, 300); await deps.store(b.id, { ...cur, state: "not_run", reason, checks: gateChecks(b, null, null, { commands: [], datapacks: 0, reason }) }); return "not_run"; }
    const plan = planGateFlight(b, art);
    if (!plan.ok) { await deps.store(b.id, { ...cur, state: "not_run", reason: plan.reason, checks: gateChecks(b, null, null, { commands: [], datapacks: art.datapacks.length, reason: plan.reason }) }); return "not_run"; }
    const pt = await playtestFor(b, deps, deps.env ?? process.env);
    const flown = pt && "plan" in pt ? withPlaytest(plan.spec, pt.plan) : plan.spec;
    await deps.store(b.id, { ...cur, state: "running" });
    let res: RunResult;
    try { res = await deps.run(flown); }
    catch (e) {
      const flights = cur.flights + 1;
      const giveUp = flights >= MAX_FLIGHTS_PER_BUILD;
      await deps.store(b.id, { ...cur, flights, state: giveUp ? "gave_up" : "queued", lastError: (e as Error).message.slice(0, 300), nextAt: new Date(now().getTime() + backoffMs(cur.busyRetries)).toISOString(), reason: giveUp ? "not run: the test server could not be reached" : undefined, checks: gateChecks(b, null, null, { commands: plan.commands, datapacks: art.datapacks.length, reason: "not run: the test server could not be reached" }) });
      return giveUp ? "not_run" : "queued";
    }
    if (res.report.status === "busy") {
      const busyRetries = cur.busyRetries + 1;
      const giveUp = busyRetries > MAX_BUSY_RETRIES;
      await deps.store(b.id, { ...cur, busyRetries, state: giveUp ? "gave_up" : "queued", nextAt: new Date(now().getTime() + backoffMs(busyRetries)).toISOString(), reason: giveUp ? "not run: the test server stayed busy" : undefined, checks: gateChecks(b, res.report, null, { commands: plan.commands, datapacks: art.datapacks.length }) });
      return giveUp ? "not_run" : "queued";
    }
    // the boot verdict is judged on the boot spec alone: a playtest flown alongside never changes it
    const bootSummary = flown === plan.spec ? res.summary : summarize(plan.spec, res.report);
    const checks = gateChecks(b, res.report, bootSummary, { commands: plan.commands, datapacks: art.datapacks.length });
    const v = gateVerdict(bootSummary, checks);
    let playtest: StoredFlight["playtest"] = undefined;
    if (pt && "plan" in pt) {
      const pv = playtestVerdict(pt.plan, res.report, pt.coverage);
      playtest = { verdict: pv.verdict, label: pv.label.slice(0, 300), counts: pv.counts, scenarios: pv.scenarios.slice(0, 16).map((x) => ({ id: x.id, status: x.status, reason: x.reason ? x.reason.slice(0, 240) : null })), specRevisionId: pt.revisionId };
    } else if (pt) playtest = { verdict: "not_run", label: pt.notRun, specRevisionId: pt.revisionId };
    const eng = res.report.engine;
    await deps.store(b.id, {
      ...cur, state: "done", flights: cur.flights + 1, verdict: v.verdict, label: v.label, checks, runId: res.report.runId, bootMs: res.report.bootMs, peakRssKb: res.report.peakRssKb,
      engine: eng ? { runner: `${eng.runner}@${eng.runnerSha256.slice(0, 12)}`, paperBuild: eng.paper.build, jdk: eng.jdk.version } : null,
      notes: [...(art.packLoader ? [] : ["the pack config was not part of this flight (no Pack Loader jar on this host)"]), ...bootSummary.reasons.slice(0, 4), ...((n) => (n ? [n] : []))(vanillaNote(vanillaOf(b.result)))],
      ...(playtest !== undefined ? { playtest } : {}),
      ...(vanillaOf(b.result) ? { vanilla: vanillaOf(b.result) } : {}),
    });
    return "ran";
  } finally { rmSync(dir, { recursive: true, force: true }); }
}

/** Default wiring for the Nxeon worker (lazy imports keep this module free of Nxeon internals at load time). */
export async function defaultGateDeps(env: Record<string, string | undefined> = process.env): Promise<GateDeps> {
  const { cyrusDb: db } = await import("../db");
  const { jarPathFor } = await import("../builder/paths");
  const { getHost } = await import("../host");
  const host = getHost();
  const mergeCyrusKey = host.builds.mergeCyrusKey;
  const { runTestFlight } = await import("./client");
  const { readBuildAssets } = await import("../assets/sync");
  const { rebuildForDelivery } = await import("../datapack/deliver");
  const { loadCatalog, pinFor } = await import("../managed/catalog");
  const { readManagedArtifact } = await import("../managed/installer");
  const { applyPackChange, serializeLoaderConfig } = await import("../packhost/loader-config");
  const { createHash } = await import("node:crypto");
  const onBuildSettled = host.mods.onBuildSettled;
  return {
    env,
    async candidates(limit) {
      const since = new Date(Date.now() - 7 * 24 * 3600_000);
      const rows = await db.modBuild.findMany({ where: { status: "succeeded", finishedAt: { gte: since }, jarPath: { not: null } }, orderBy: { finishedAt: "desc" }, take: limit, select: { id: true, mcVersion: true, pluginName: true, jarSha256: true, result: true, cyrus: true, finishedAt: true } });
      return rows;
    },
    async artifacts(b, dir) {
      const a = readBuildAssets(b.result);
      const datapacks: GateArtifacts["datapacks"] = [];
      if (a?.datapacks?.length && a.revisionId) {
        const rows = await db.cyrusProjectAsset.findMany({ where: { revisionId: a.revisionId, kind: "datapack" }, select: { assetKey: true, provenance: true } });
        for (const row of rows) {
          const rb = rebuildForDelivery((row.provenance ?? {}) as Record<string, unknown>, a.namespace);
          if (!rb.ok) continue;
          const name = `nxeon-${a.namespace}-${rb.name}`.toLowerCase().replace(/[^a-z0-9_.-]/g, "-").slice(0, 64);
          const p = path.join(dir, `${name}.zip`); writeFileSync(p, rb.zip);
          datapacks.push({ name, localPath: p });
        }
      }
      let packLoader: GateArtifacts["packLoader"] = null;
      if (a?.status === "ready" && a.loader) {
        try {
          const pin = pinFor(loadCatalog(), "nxeon-pack-loader", b.mcVersion);
          if (pin.ok) {
            const bytes = await readManagedArtifact(pin.entry);
            const jp = path.join(dir, "NxeonPackLoader.jar"); writeFileSync(jp, bytes);
            const ch = applyPackChange(null, { op: "upsert", namespace: a.namespace, role: "main", sha1: a.loader.sha1, prompt: a.loader.prompt, required: a.loader.required }, { urlFor: () => a.loader!.url });
            if (ch.ok) packLoader = { localPath: jp, sha256: createHash("sha256").update(bytes).digest("hex"), config: serializeLoaderConfig(ch.config) };
          }
        } catch { packLoader = null; }
      }
      return { jarPath: jarPathFor(b.id), datapacks, packLoader };
    },
    run: (spec) => runTestFlight(spec),
    async spec(b) {
      const { validateModSpec } = await import("../engine-core/spec");
      const rows = await db.cyrusRevision.findMany({ where: { modBuildId: b.id }, orderBy: { seq: "desc" }, take: 5, select: { id: true, spec: true } });
      for (const r of rows) {
        if (r.spec == null) continue;
        const v = validateModSpec(r.spec);
        if (v.ok) return { spec: v.spec, revisionId: r.id };
      }
      return null;
    },
    async store(id, flight) {
      await mergeCyrusKey(id, "testFlight", flight);
      // the NxLabs page shows the boot test: regenerate it once the result is final (never fails the flight)
      if (flight.state !== "queued" && flight.state !== "running") {
        const row = await db.modBuild.findUnique({ where: { id } }).catch(() => null);
        if (row) await onBuildSettled(row).catch(() => {});
      }
    },
  };
}
// Pure Test Flight verdicts. Rules (never relaxed):
// - a check counts as passed only if its status is "pass" AND it carries evidence (a pass with no evidence = not run);
// - required stages come from the spec we sent (requiredStages), not from the runner's own flags;
// - any required stage failed -> "failed"; any required stage missing / not_run -> "incomplete"; neither is success;
// - a busy or errored runner is never success, whatever its checks say.
import type { CheckId, CheckResult, MatrixSummary, Overall, TestFlightReport, TestFlightSpec, TestFlightSummary } from "./types";
import { CHECK_IDS } from "./types";
import { requiredStages } from "./spec";

const STATUSES = new Set(["pass", "fail", "not_run"]);

/** Normalise one check: unknown status or a pass without evidence becomes not_run. */
function effective(c: CheckResult | undefined): "pass" | "fail" | "not_run" {
  if (!c || !STATUSES.has(c.status)) return "not_run";
  if (c.status === "pass" && !(Array.isArray(c.evidence) && c.evidence.some((e) => String(e).trim()))) return "not_run";
  return c.status;
}

export function summarize(spec: TestFlightSpec, report: TestFlightReport): TestFlightSummary {
  const req = requiredStages(spec);
  const byId = new Map<CheckId, CheckResult>();
  for (const c of report.checks ?? []) if ((CHECK_IDS as readonly string[]).includes(c.id) && !byId.has(c.id)) byId.set(c.id, c);
  const passed: CheckId[] = [], failed: CheckId[] = [], skippedRequired: CheckId[] = [], notRunOptional: CheckId[] = [];
  const reasons: string[] = [];
  for (const id of CHECK_IDS) {
    const c = byId.get(id);
    const st = effective(c);
    if (st === "pass") passed.push(id);
    else if (st === "fail") { failed.push(id); if (req.has(id)) reasons.push(`${id} failed${c?.evidence?.[0] ? `: ${c.evidence[0]}` : ""}`); }
    else if (req.has(id)) {
      skippedRequired.push(id);
      reasons.push(!c ? `${id} missing from the report` : c.status === "pass" ? `${id} claimed pass without evidence` : `${id} did not run`);
    } else notRunOptional.push(id);
  }
  if (report.version && spec.version && report.version !== spec.version) reasons.push(`report is for ${report.version}, spec asked for ${spec.version}`);
  let overall: Overall;
  if (report.status === "busy") { overall = "busy"; reasons.unshift("another Test Flight was running; nothing ran"); }
  else if (report.status !== "completed") { overall = "error"; reasons.unshift(`runner did not complete: ${report.notes?.slice(-1)[0] ?? "no detail"}`); }
  else if (report.version !== spec.version) overall = "error";
  else if (failed.some((id) => req.has(id))) overall = "failed";
  else if (skippedRequired.length) overall = "incomplete";
  else overall = "passed";
  return {
    version: spec.version, overall, success: overall === "passed", passed, failed, skippedRequired, notRunOptional, reasons,
    bootMs: report.bootMs ?? null, peakRssKb: report.peakRssKb ?? null, runId: report.runId ?? null,
  };
}

/** One verdict over several versions: success only if every version passed. Worst status wins. */
export function mergeSummaries(list: TestFlightSummary[]): MatrixSummary {
  const rank: Overall[] = ["error", "failed", "busy", "incomplete", "passed"];
  const overall = list.length ? rank.find((r) => list.some((s) => s.overall === r))! : "incomplete";
  return { overall, success: overall === "passed", versions: list };
}

/** Short human line per version, e.g. for a build log or a badge tooltip. Never says "passed" unless it did. */
export function describe(s: TestFlightSummary): string {
  const t = s.bootMs != null ? `, boot ${(s.bootMs / 1000).toFixed(1)}s` : "";
  const r = s.peakRssKb != null ? `, peak RSS ${Math.round(s.peakRssKb / 1024)} MB` : "";
  if (s.success) return `Test Flight passed on Paper ${s.version} (${s.passed.length} checks${t}${r})`;
  return `Test Flight ${s.overall} on Paper ${s.version}: ${s.reasons.slice(0, 3).join("; ") || "no detail"}`;
}
// Thin Test Flight invoker: push the runner + artifacts to node-2, run ONE flight, parse the report, summarise.
// Not wired into the live build path. All I/O goes through the injectable `Remote`, so tests use a fake.
// Server-only (node:child_process / node:fs).
import { spawn } from "node:child_process";
import { createHash, randomBytes } from "node:crypto";
import { readFileSync, readdirSync, statSync } from "node:fs";
import path from "node:path";
import type { TestFlightReport, TestFlightSpec, TestFlightSummary, ResolvedSpec } from "./types";
import { resolveSpec, validateSpec, TF_DEFAULT_ROOT } from "./spec";
import { summarize } from "./summary";
import { cyrusConfig } from "../config";

export type ExecResult = { code: number | null; stdout: string; stderr: string };
/** Runs a shell command line on the build host. `input` is piped to stdin. */
export type Remote = { exec: (command: string, opts?: { input?: Buffer; timeoutMs?: number }) => Promise<ExecResult> };

export const NODE2 = cyrusConfig().buildHost;
export const BUSY_EXIT = 75;

/** POSIX single-quote a word for a remote shell. */
export const shq = (s: string) => `'${String(s).replace(/'/g, `'\\''`)}'`;

/** Real transport: ssh with BatchMode (no prompts), hard local timeout (SIGKILL of the ssh child we spawned). */
export function sshRemote(host = NODE2): Remote {
  return {
    exec: (command, opts = {}) => new Promise((resolve) => {
      const child = spawn("ssh", ["-o", "BatchMode=yes", "-o", "ConnectTimeout=15", host, command], { stdio: ["pipe", "pipe", "pipe"] });
      let stdout = "", stderr = "";
      child.stdout.on("data", (d) => (stdout += d));
      child.stderr.on("data", (d) => (stderr += d));
      const t = setTimeout(() => child.kill("SIGKILL"), opts.timeoutMs ?? 120000);
      child.on("close", (code) => { clearTimeout(t); resolve({ code, stdout, stderr }); });
      child.stdin.on("error", () => {});
      child.stdin.end(opts.input ?? undefined);
    }),
  };
}

