"use strict";
// Cyrus playtest bots (R3): pure helpers shared by the Test Flight runner (runner.js), the bot process (bot.js) and
// the repo tests. No I/O, no network. Plain CommonJS so it runs as-is on node-2.
//
// A playtest is a list of SCENARIOS (one per acceptance test of the ModSpec, e.g. "T-2"), each a list of typed STEPS.
// The bot is a scripted Mineflayer client that joins the disposable Test Flight server (private netns, offline mode),
// performs the actions and checks the outcomes. There is no free-form code: only the step kinds below exist.
// Every step is pass / fail / not_run with evidence; a scenario passes only if every step ran and passed.

const crypto = require("crypto");

const PLAYTEST_SCHEMA = 1;
const STEP_KINDS = ["join", "command", "chat", "server", "wait", "hold", "use_item",
  "expect_chat", "expect_no_chat", "expect_inventory", "expect_no_item", "expect_effect", "expect_title", "expect_moved"];
const ACTION_KINDS = new Set(["command", "chat", "server", "hold", "use_item"]);
/** Commands neither the bot nor a `server` step may send: they belong to the runner (or would end the test). */
const RESERVED_RE = /^\/?(stop|restart|reload|op|deop|kick|ban|ban-ip|pardon|pardon-ip|whitelist|save-off|save-all|minecraft:(stop|reload|op|deop|kick|ban))\b/i;
const USERNAME_RE = /^[A-Za-z0-9_]{3,16}$/;
const ID_RE = /^[a-z0-9_:./-]{1,64}$/;
const SCENARIO_ID_RE = /^T-[1-9][0-9]{0,3}$/;
const REQ_RE = /^REQ-[1-9][0-9]{0,3}$/;
const LIMITS = { scenarios: 16, steps: 24, text: 200, contains: 6, withinMsMax: 15000, waitMsMax: 10000, totalSecMax: 180, joinSecMax: 60 };
/**
 * Minecraft versions the pinned bot (bot/package-lock.json: mineflayer 4.39.0) has been RUN against on node-2.
 * Mineflayer itself lists more (up to 26.1); a version is added here only after a real flight proved the bot joins.
 */
const BOT_VERSIONS = ["1.21.11"];
const DEFAULTS = { username: "NxPlaytest", withinMs: 3000, forMs: 1500, totalSec: 90, joinSec: 30 };

const isStr = (s, max = LIMITS.text) => typeof s === "string" && s.trim().length > 0 && s.length <= max && !/[\r\n\u0000]/.test(s);
const intIn = (v, lo, hi) => Number.isInteger(v) && v >= lo && v <= hi;

function stepErrors(st, key) {
  const e = [];
  if (!st || typeof st !== "object" || !STEP_KINDS.includes(st.kind)) return [`${key}.kind must be one of ${STEP_KINDS.join(", ")}`];
  const strList = (v, k) => {
    if (!Array.isArray(v) || !v.length || v.length > LIMITS.contains || !v.every((s) => isStr(s))) e.push(`${key}.${k} must be 1-${LIMITS.contains} strings of 1-${LIMITS.text} chars`);
  };
  const within = (k) => { if (st[k] != null && !intIn(st[k], 100, LIMITS.withinMsMax)) e.push(`${key}.${k} must be 100-${LIMITS.withinMsMax} ms`); };
  switch (st.kind) {
    case "command":
      if (!isStr(st.text) || !st.text.startsWith("/")) e.push(`${key}.text must be one line starting with /`);
      else if (RESERVED_RE.test(st.text.trim())) e.push(`${key}: '${st.text}' is reserved (never sent by a playtest)`);
      break;
    case "chat":
      if (!isStr(st.text) || st.text.startsWith("/")) e.push(`${key}.text must be one line of chat (commands use kind "command")`);
      break;
    case "server":
      if (!isStr(st.command)) e.push(`${key}.command must be one line of 1-${LIMITS.text} chars`);
      else if (RESERVED_RE.test(st.command.trim())) e.push(`${key}: '${st.command}' is reserved (never sent by a playtest)`);
      if (st.expect != null) strList(st.expect, "expect");
      break;
    case "wait":
      if (!intIn(st.ms, 1, LIMITS.waitMsMax)) e.push(`${key}.ms must be 1-${LIMITS.waitMsMax}`);
      break;
    case "hold":
      if (!isStr(st.item, 64) || !ID_RE.test(st.item)) e.push(`${key}.item must be an item id (e.g. diamond or minecraft:diamond)`);
      break;
    case "expect_chat":
      strList(st.contains, "contains"); within("withinMs");
      break;
    case "expect_no_chat":
      strList(st.contains, "contains"); within("forMs");
      break;
    case "expect_inventory":
      if (!isStr(st.item, 64) || !ID_RE.test(st.item)) e.push(`${key}.item must be an item id`);
      if (st.count != null && !intIn(st.count, 1, 6400)) e.push(`${key}.count must be 1-6400`);
      if (st.name != null && !isStr(st.name, 100)) e.push(`${key}.name must be 1-100 chars`);
      within("withinMs");
      break;
    case "expect_no_item":
      if (!isStr(st.item, 64) || !ID_RE.test(st.item)) e.push(`${key}.item must be an item id`);
      within("forMs");
      break;
    case "expect_effect":
      if (!isStr(st.effect, 64) || !ID_RE.test(st.effect)) e.push(`${key}.effect must be an effect id (e.g. speed)`);
      within("withinMs");
      break;
    case "expect_title":
      strList(st.contains, "contains"); within("withinMs");

#!/usr/bin/env node
"use strict";
// Cyrus playtest bot (R3): ONE scripted Mineflayer player that joins a Test Flight server and runs a typed playtest
// plan (playtest-lib.js). Started by runner.js inside the flight's private network namespace, as uid 65534, with a
// heap cap and a hard timeout; it only ever talks to 127.0.0.1 (the server + its RCON). No free-form code is run:
// each step is one of the fixed kinds. Output: JSON lines prefixed "@@PT " on stdout (scenario start/end events,
// then one final result). Usage: node bot.js <script.json> <run marker>
//
// The marker argument is not used here; it puts the flight's -Dnxeon.testflight.run=<id> marker on this process's
// cmdline so the runner's leak scan and exact-PID kills cover the bot too.

const fs = require("fs");
const path = require("path");
const net = require("net");
const L = require("./lib.js");
const P = require("./playtest-lib.js");

const now = () => Date.now();
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const clip = (s, n = 240) => String(s).replace(/\s+/g, " ").slice(0, n);
const emit = (o) => process.stdout.write("@@PT " + JSON.stringify(o) + "\n");

function rconConnect(port, password, timeoutMs) {
  return new Promise((resolve, reject) => {
    const sock = net.connect({ host: "127.0.0.1", port });
    let buf = Buffer.alloc(0), nextId = 500;
    const waiters = [];
    const timer = setTimeout(() => { sock.destroy(); reject(new Error("rcon connect timeout")); }, timeoutMs);
    sock.on("data", (d) => {
      buf = Buffer.concat([buf, d]);
      const { packets, rest } = L.rconParse(buf);
      buf = rest;
      for (const p of packets) for (const w of [...waiters]) w(p);
    });
    sock.on("error", (e) => { clearTimeout(timer); reject(e); });
    const request = (type, body, maxMs = timeoutMs) => new Promise((res, rej) => {
      const id = nextId++;
      let text = "", got = false, q = null;
      const done = () => { waiters.splice(waiters.indexOf(w), 1); clearTimeout(hard); clearTimeout(q); res(text); };
      const w = (p) => {
        if (p.id === -1 && type === 3) { waiters.splice(waiters.indexOf(w), 1); clearTimeout(hard); rej(new Error("rcon auth refused")); return; }
        if (p.id !== id) return;
        got = true; text += p.body;
        clearTimeout(q); q = setTimeout(done, type === 3 ? 0 : 250);
      };
      const hard = setTimeout(() => { waiters.splice(waiters.indexOf(w), 1); clearTimeout(q); got ? res(text) : rej(new Error(`rcon timeout after ${maxMs} ms`)); }, maxMs);
      waiters.push(w);
      sock.write(L.rconPacket(id, type, body));
    });
    sock.on("connect", async () => {
      clearTimeout(timer);
      try { await request(3, password); resolve({ command: (c, ms) => request(2, c, ms), close: () => sock.destroy() }); } catch (e) { sock.destroy(); reject(e); }
    });
  });
}

async function main() {
  const script = JSON.parse(fs.readFileSync(process.argv[2], "utf8"));
  const plan = script.plan;
  const username = plan.username || P.DEFAULTS.username;
  const totalMs = (plan.totalSec || P.DEFAULTS.totalSec) * 1000;
  const joinMs = (plan.joinSec || P.DEFAULTS.joinSec) * 1000;
  const result = {
    schema: 1, username, version: script.version, joined: false, joinFailed: false, joinMs: null, op: !!plan.op,
    bot: { mineflayer: null, minecraftProtocol: null, lockSha256: script.lockSha256 || null }, scenarios: [], notes: [], disconnect: null,
  };
  const t0 = now();
  // Hard guard: whatever happens, print what we have and exit before the runner's own kill.
  const guard = setTimeout(() => { result.notes.push(`bot hard timeout after ${totalMs + joinMs + 5000} ms`); finish(); }, totalMs + joinMs + 5000);
  let finished = false;
  function finish() {
    if (finished) return;
    finished = true;
    clearTimeout(guard);
    emit({ ev: "result", result });
    setTimeout(() => process.exit(0), 200);
  }

  let mineflayer;
  try {
 * Run the playtest bot as uid 65534 inside this netns (heap cap, nice, hard timeout, exact-PID kill) and fold its result
 * into the `playtest` check. Server log lines written while a scenario ran are matched with the startup matchers: an
 * error logged during a scenario (e.g. an exception in a command handler) fails that scenario even if the bot saw the
 * expected outcome.
 */
async function stagePlaytest({ ctx, spec, C, out, lines, up, port, rconPort, rconPassword, matchers, ignores, notes }) {
  const chk = C.playtest;
  const plan = spec.playtest;
  if (!up) { chk.evidence.push("server not up; the playtest bot did not run"); return; }
  if (ctx.botError) { chk.evidence.push(`playtest bot unavailable: ${ctx.botError}`); return; }
  if (!PT.BOT_VERSIONS.includes(spec.version)) { chk.evidence.push(`no verified playtest bot for Minecraft ${spec.version} (verified: ${PT.BOT_VERSIONS.join(", ")})`); return; }
  const scriptPath = path.join(ctx.runDir, "tmp", "playtest.json");
  fs.writeFileSync(scriptPath, JSON.stringify({ port, rconPort, rconPassword, version: spec.version, plan, modulesDir: ctx.bot.modulesDir, lockSha256: ctx.bot.lockSha }), { mode: 0o600 });
  spawnSync("chown", [`${RUN_UID}:${RUN_UID}`, scriptPath]);
  const limitMs = ((plan.totalSec || PT.DEFAULTS.totalSec) + (plan.joinSec || PT.DEFAULTS.joinSec) + 20) * 1000;
  const fromLine = lines.length;
  const spans = {};
  let result = null, partial = "", stderr = "";
  const child = spawn("nice", ["-n", "10", "setpriv", `--reuid=${RUN_UID}`, `--regid=${RUN_UID}`, "--clear-groups", "--no-new-privs", "--",
    process.execPath, "--max-old-space-size=256", path.join(__dirname, "bot.js"), scriptPath, ctx.marker],
    { cwd: path.join(ctx.runDir, "tmp"), stdio: ["ignore", "pipe", "pipe"], env: { PATH: "/usr/bin:/bin", HOME: path.join(ctx.runDir, "tmp"), LANG: "C.UTF-8" } });
  const pid = child.pid;
  child.stdout.on("data", (d) => {
    const parts = (partial + d.toString("utf8")).split("\n");
    partial = parts.pop();
    for (const p of parts) {
      if (!p.startsWith("@@PT ")) continue;
      let ev; try { ev = JSON.parse(p.slice(5)); } catch { continue; }
      if (ev.ev === "scenario" && ev.phase === "start") spans[ev.id] = { from: lines.length, to: null };
      if (ev.ev === "scenario" && ev.phase === "end" && spans[ev.id]) spans[ev.id].to = lines.length;
      if (ev.ev === "result") result = ev.result;
    }
  });
  child.stderr.on("data", (d) => { if (stderr.length < 4000) stderr += d.toString("utf8"); });
  const exitP = new Promise((r) => child.on("exit", (code, sig) => r({ code, sig })));
  const ex = await Promise.race([exitP, sleep(limitMs).then(() => null)]);
  if (!ex) {
    if (killExact(pid, ctx.marker)) chk.evidence.push(`bot pid ${pid} over its ${limitMs} ms limit -> SIGKILL`);
    await Promise.race([exitP, sleep(3000)]);
  }
  await sleep(500); // let the server log the disconnect
  if (!result) { chk.evidence.push(`the bot produced no result (exit ${ex ? ex.code : "killed"})${stderr ? ": " + clip(stderr, 300) : ""}`); return; }
  // Server-side errors while each scenario ran.
  const { hits } = L.matchLogDetailed(lines, matchers, ignores, fromLine, lines.length);
  for (const sc of result.scenarios || []) {
    const sp = spans[sc.id];
    if (!sp) continue;
    const mine = hits.filter((h) => h.line - 1 >= sp.from && h.line - 1 < (sp.to == null ? lines.length : sp.to));
    if (mine.length) {
      sc.logHits = mine.slice(0, 6).map((h) => `L${h.line} [${h.matcher}] ${clip(h.text, 200)}`);
      if (sc.status === "pass") { sc.status = "fail"; sc.failedBy = "server_log"; }
    }
  }
  const outside = hits.filter((h) => !Object.values(spans).some((sp) => h.line - 1 >= sp.from && h.line - 1 < (sp.to == null ? lines.length : sp.to)));
  chk.status = PT.playtestCheckStatus(result);
  if (outside.length && chk.status === "pass") chk.status = "fail";
  const b = result.bot || {};
  chk.evidence.push(result.joined
    ? `bot ${result.username} joined Paper ${spec.version} in ${result.joinMs} ms (mineflayer ${b.mineflayer}, minecraft-protocol ${b.minecraftProtocol}, op ${result.op})`
    : `bot did not join: ${(result.notes || []).slice(-1)[0] || "no detail"}`);
  for (const sc of result.scenarios || []) {
    const bad = (sc.steps || []).find((s) => s.status !== "pass");
    chk.evidence.push(`${sc.id} ${sc.status.toUpperCase()} (${(sc.steps || []).filter((s) => s.status === "pass").length}/${(sc.steps || []).length} steps, ${sc.ms} ms)${bad ? ` at step ${bad.i + 1} ${bad.kind}: ${clip(bad.evidence.join("; "), 220)}` : ""}${sc.logHits ? ` server log: ${sc.logHits[0]}` : ""}`);
  }
  if (outside.length) chk.evidence.push(...outside.slice(0, 4).map((h) => `server log during the playtest (no scenario): L${h.line} [${h.matcher}] ${clip(h.text, 200)}`));
  for (const n of (result.notes || []).slice(0, 6)) notes.push(`playtest: ${clip(n, 300)}`);
  // Bound the stored result: evidence lines are already clipped by the bot; cap counts.
  for (const sc of result.scenarios || []) for (const st of sc.steps || []) st.evidence = (st.evidence || []).slice(0, 4);
  out.playtest = result;
}

// ------------------------------------------------------------------ main ----
(async () => {
  const [cmd, arg] = process.argv.slice(2);
  try {
    if (cmd === "run" && arg) process.exitCode = stageRun(arg);
    else if (cmd === "locked" && arg) process.exitCode = await stageLocked(arg);
    // Exit explicitly: a pending race timer (stop timeout) must not keep the inner stage alive.
    else if (cmd === "inner" && arg) process.exit(await stageInner(arg));
    else if (cmd === "setup" && arg) { const j = await ensureJdk(Number(arg)); process.stdout.write(JSON.stringify({ home: j.home, release: j.release, sha256: j.sha256, fetched: j.fetched, version: jdkVersion(j.home) }) + "\n"); }
    else { process.stderr.write("usage: runner.js run <spec.json> | setup <21|25>\n"); process.exitCode = 2; }
  } catch (e) {
    log(`fatal: ${e.stack || e.message}`);
    process.exitCode = 1;
  }
})();

async function stageInner(ctxPath) {
  const ctx = JSON.parse(fs.readFileSync(ctxPath, "utf8"));
  const { spec, plugins, runDir, marker } = ctx;
  const T = Object.assign({ bootSec: 180, rconSec: 10, stopSec: 45, totalSec: 420 }, spec.timeouts || {});
  const xmx = (spec.memory && spec.memory.xmxMb) || 1024;
  const rssCapKb = ((spec.memory && spec.memory.rssCapMb) || 1800) * 1024;
  const matchers = spec.logMatchers || L.DEFAULT_LOG_MATCHERS;
  const ignores = [...L.DEFAULT_LOG_IGNORES, ...(spec.logIgnore || [])];
  const checks = emptyChecks(requiredFor(spec));
  const C = Object.fromEntries(checks.map((c) => [c.id, c]));
  const notes = [];
  const timings = {};
  const out = { checks, notes, timings, bootMs: null, doneReportedSec: null, peakRssKb: null };
  const save = () => fs.writeFileSync(ctx.out, JSON.stringify(out));

  const { port, rconPort } = L.pickPorts();
  const rconPassword = crypto.randomBytes(18).toString("base64url");
  fs.writeFileSync(path.join(runDir, "eula.txt"), "eula=true\n");
  fs.writeFileSync(path.join(runDir, "server.properties"), L.serverProperties({ port, rconPort, rconPassword, resourcePack: spec.resourcePack, world: spec.world }));
  spawnSync("chown", [`${RUN_UID}:${RUN_UID}`, path.join(runDir, "eula.txt"), path.join(runDir, "server.properties")]);
  notes.push(`ports: server ${port}, rcon ${rconPort} (private netns, 127.0.0.1)`);

  const java = path.join(ctx.javaHome, "bin/java");
  const args = ["-n", "10", "setpriv", `--reuid=${RUN_UID}`, `--regid=${RUN_UID}`, "--clear-groups", "--no-new-privs", "--",
    java, marker, `-Xmx${xmx}m`, "-Xms128m", "-XX:+UseSerialGC", "-XX:ActiveProcessorCount=2", "-XX:MaxMetaspaceSize=256m",
    "-XX:ReservedCodeCacheSize=96m", "-XX:+ExitOnOutOfMemoryError", `-Djava.io.tmpdir=${runDir}/tmp`, `-Duser.home=${runDir}`,
    `-DbundlerRepoDir=${ctx.paperDir}`, "-Dpaper.disableChannelLimit=true", "-jar", ctx.paperJar, "--nogui"];
  const consoleLog = path.join(runDir, "console.log");
  const lines = [];
  let partial = "";
  const t0 = now();
  const child = spawn("nice", args, { cwd: runDir, stdio: ["pipe", "pipe", "pipe"], env: { PATH: "/usr/bin:/bin", HOME: runDir, LANG: "C.UTF-8" } });
  const pid = child.pid;
  let exited = null;
  const exitP = new Promise((r) => child.on("exit", (code, sig) => { exited = { code, sig, at: now() }; r(exited); }));
  const onData = (d) => {
    fs.appendFileSync(consoleLog, d);
    const s = partial + d.toString("utf8");
    const parts = s.split(/\r?\n/);
    partial = parts.pop();
    for (const p of parts) lines.push(p.replace(/\x1b\[[0-9;]*m/g, ""));
  };
  child.stdout.on("data", onData);
  child.stderr.on("data", onData);
  child.stdin.on("error", () => {});

  // Watchdog: peak RSS (VmHWM) sampling, RSS cap, hard total timeout. Kills only `pid`, and only if it is our java.
  let peak = 0, killedFor = null;
  const isOurs = () => { try { return fs.readFileSync(`/proc/${pid}/cmdline`, "utf8").split("\0").includes(marker); } catch { return false; } };
  const hardKill = (why) => { if (!exited && isOurs()) { killedFor = killedFor || why; try { process.kill(pid, "SIGKILL"); } catch { /* gone */ } } };
  const sample = () => {
    try {
      const st = fs.readFileSync(`/proc/${pid}/status`, "utf8");
      const hwm = Number((/VmHWM:\s+(\d+)/.exec(st) || [])[1] || 0), rss = Number((/VmRSS:\s+(\d+)/.exec(st) || [])[1] || 0);
      peak = Math.max(peak, hwm, rss);
      if (rss > rssCapKb) hardKill(`RSS ${rss} kB over the cap ${rssCapKb} kB`);
    } catch { /* not started or gone */ }
  };
  const sampler = setInterval(sample, 500);
  const hard = setTimeout(() => hardKill(`hard timeout ${T.totalSec}s`), T.totalSec * 1000);
  const verifyChild = setTimeout(() => { if (!exited && !isOurs()) notes.push(`warning: pid ${pid} cmdline lacks the marker`); }, 3000);

  // (a) boot_done
  let doneIdx = -1;
  const ta = now();
