export async function cyrusLifecycleSweep(opts: { force?: boolean; mailer?: Mailer; log?: (s: string) => void } = {}): Promise<{ signals: number; autoDisabled: number; autoUpdated: number }> {
  const out = { signals: 0, autoDisabled: 0, autoUpdated: 0 };
  if (lifecycleRunning) return out;
  if (!opts.force && !(await getSettingBool("cyrus_lifecycle_enabled", false))) return out;
  lifecycleRunning = true;
  const log = opts.log ?? ((s: string) => console.log(`[cyrus-lifecycle] ${s}`));
  const mail = opts.mailer ?? (await defaultMailer());
  try {
    out.signals = await signalsFromHealth(mail, log);
    out.autoDisabled = await crashLoops(mail, log);
    out.autoUpdated = await autoUpdates(log);
  } finally {
    lifecycleRunning = false;
  }
  return out;
}

type HealthCyrus = { modId: string; buildId: string | null; status: string; apiMismatch: boolean; evidence: string[] };

/** Health runs of the last hour that read Cyrus mods -> BROKEN / RECOVERED signals. */
async function signalsFromHealth(mail: Mailer, log: (s: string) => void): Promise<number> {
  const runs = await db.modUpdateRun.findMany({ where: { trigger: "health", startedAt: { gt: new Date(Date.now() - 3600_000) } }, orderBy: { startedAt: "asc" }, take: 200 });
  let n = 0;
  for (const run of runs) {
    const plan = (run.plan ?? {}) as { cyrus?: HealthCyrus[]; gameVersion?: string | null };
    for (const v of plan.cyrus ?? []) {
      const open = await cyrusDb.cyrusModSignal.findFirst({ where: { serverId: run.serverId, modId: v.modId, kind: "BROKEN", clearedAt: null } });
      if (v.status === "broken") {
        if (open && open.buildId === v.buildId) continue;
        if (open) await cyrusDb.cyrusModSignal.update({ where: { id: open.id }, data: { clearedAt: new Date() } });
        const gm = await db.gameMod.findUnique({ where: { id: v.modId }, select: { name: true, sourceId: true } });
        if (!gm?.sourceId) continue;
        // Flapping guard: at most one owner email per mod per server per day (in-app every time).
        const recent = await cyrusDb.cyrusModSignal.count({ where: { serverId: run.serverId, modId: v.modId, kind: "BROKEN", createdAt: { gt: new Date(Date.now() - 86_400_000) } } });
        await cyrusDb.cyrusModSignal.create({ data: { serverId: run.serverId, modId: v.modId, rootBuildId: gm.sourceId, buildId: v.buildId, kind: "BROKEN", evidence: v.evidence.join("\n").slice(0, 2000) || null, gameVersion: plan.gameVersion ?? null } });
        n++;
        await tellOwner(run.serverId, `${gm.name} is reporting errors`, `${v.apiMismatch ? "The game log shows it calling something this game version doesn't have, so it's out of date for this version." : "The game log shows errors naming it."} Open the Mods tab to update, roll back or switch it off.`, mail, recent === 0);
        log(`BROKEN ${gm.name} on ${run.serverId}`);
      } else if (v.status === "loaded" && open && run.startedAt > open.createdAt) {
        await cyrusDb.cyrusModSignal.update({ where: { id: open.id }, data: { clearedAt: new Date() } });
        await cyrusDb.cyrusModSignal.create({ data: { serverId: run.serverId, modId: v.modId, rootBuildId: open.rootBuildId, buildId: v.buildId, kind: "RECOVERED", gameVersion: plan.gameVersion ?? null, clearedAt: new Date() } });
        n++;
      }
    }
  }
  return n;
}

