    await tx.serverMod.upsert({
      where: { serverId_modId: { serverId, modId } },
      create: { serverId, modId, status: TO_STATUS[op], error: null, targetVersionId: target },
      update: { status: TO_STATUS[op], error: null, targetVersionId: target },
    });
    const job = await tx.job.create({ data: { type: "GAME_MOD_SYNC", serverId, payload: { op, modId, ...(target ? { targetVersionId: target } : {}) } }, select: { id: true } });
