// Cyrus PERF-RISK CLASSIFIER (pure, deterministic, no model, no I/O; client-safe). Born from the 2026-10-11 ChunkMirror
// incident: a prompt that asked for unbounded, multiplicative work ("copy every block placed/broken and every mob spawn
// into every other chunk, remembered for chunks that load later", chunks-per-tick 500) was built exactly as asked and
// took a 2-core server to 1 TPS. This module reads a prompt (and optional config values) BEFORE any credits are held
// and says, in plain words, which parts imply unbounded work, how bad that is, and the SAFE bounded alternative.
//
// Contract for the planner (lib/cyrus/planner, another branch): call classifyPerfRisk({ text, config? }) next to the
// capability decision; when `mustConfirm` is true show `findings` (title + reason + safe) with two choices:
//   "safe"      (DEFAULT) build the bounded version: append `applyPerfChoice(...).prompt` constraints to the request;
//   "as_asked"  "Build anyway": the request is sent unchanged, the build still gets the watchdog + stress test.
// perfPreBuildCheck() is the server-side twin of the plan gate: it refuses a build whose risk needs a choice and has none.
// Rules are data (RULES below); every rule names a benign look-alike it must not fire on (golden tests:
// test/cyrus-perf-risk.test.ts). Version bump = PERF_RISK_VERSION.

export const PERF_RISK_VERSION = "perfrisk-2026-10-11.1";
export const PERF_RISK_FLAG = "CYRUS_PERF_SAFETY";

export type PerfSeverity = "low" | "medium" | "high" | "critical";
export type PerfLevel = "none" | PerfSeverity;
export type PerfChoice = "safe" | "as_asked";

export type PerfFinding = {
  id: string;
  severity: PerfSeverity;
  /** Short label for the plan screen, e.g. "Copies every change into every chunk". */
  title: string;
  /** Why it is a problem, in plain words (no jargon). */
  reason: string;
  /** The safe bounded alternative Cyrus builds by default. */
  safe: string;
  /** Hard limits added to the request when the owner keeps the safe version. */
  bounds: string[];
  /** The words that triggered it (for the UI highlight and the tests). */
  match: string;
};

export type PerfRisk = {
  schema: "cyrus.perfrisk.v1";
  version: string;
  level: PerfLevel;
  findings: PerfFinding[];
  /** true = show the findings and ask "safe (default) / build anyway" before any credits are held. */
  mustConfirm: boolean;
  defaultChoice: PerfChoice;
  /** One plain sentence for the plan screen, or null when nothing was found. */
  summary: string | null;
};

const RANK: Record<PerfLevel, number> = { none: 0, low: 1, medium: 2, high: 3, critical: 4 };
export const worse = (a: PerfLevel, b: PerfLevel): PerfLevel => (RANK[a] >= RANK[b] ? a : b);
/** Levels that need an explicit choice before a hold. */
export const CONFIRM_AT: PerfSeverity = "high";

// ------------------------------------------------------------------ text helpers ----
/** Lowercase, words and digits only, single spaces. Hyphens/underscores become spaces ("chunks-per-tick" = "chunks per tick"). */
export function normalize(s: string): string {
  return String(s ?? "").toLowerCase().replace(/['’]/g, "").replace(/[^a-z0-9.!?;\n]+/g, " ").replace(/[ \t]+/g, " ").trim();
}
/** Sentences / clauses (fan-out is judged inside one clause so two unrelated sentences never combine). */
function clauses(t: string): string[] {
  return t.split(/[.!?;\n]+/).map((x) => x.trim()).filter(Boolean);
}
const num = (s: string | undefined): number => {
  if (!s) return NaN;
  const w: Record<string, number> = { a: 1, one: 1, two: 2, three: 3, four: 4, five: 5, ten: 10, hundred: 100, thousand: 1000, million: 1_000_000 };
  if (s in w) return w[s];
  return Number(s.replace(/[^0-9.]/g, ""));
};

// Shared vocabularies (regex sources over normalized text).
const ALL = "(?:every|all|each|all the|every single|any)";
const WORLD_TARGET = `(?:other |loaded |single |)(?:chunks?|worlds?|dimensions?|regions?)|whole (?:world|map|server)|entire (?:world|map|server)|the world|the map|everywhere`;
const COPY_VERB = "(?:copy|copies|copied|copying|mirror|mirrors|mirrored|mirroring|replicate|replicates|replicated|replicating|duplicate|duplicates|duplicated|duplicating|clone|clones|cloned|cloning|sync|syncs|synced|syncing|synchronize|propagate|propagates|propagated|reproduce|reproduces|repeat|repeats|repeated|broadcast|apply|applies|applied|paste|pastes|pasted)";
const EVENT_SRC = "(?:block|blocks|mob|mobs|entity|entities|spawn|spawns|change|changes|explosion|explosions|placement|break|breaks)";
/** "in the chunk you stand in", "nearby chunks", "within 3 chunks", "a 5 block radius": clearly bounded phrasing. */
const BOUNDED = /\b(?:(?:the|your|their|his|her|this|that|current|same|own) chunk(?: (?:you|i|they|he|she|the player|a player|players)(?: are| is| re)?(?: standing| stand| stands| in| at)*)?|nearby chunks?|surrounding chunks?|adjacent chunks?|neighbou?ring chunks?|within (?:\d+|a few|one|two|three|four|five) chunks?|(?:\d+|one|two|three|four|five) chunks? (?:around|radius|away|of)|chunk radius|radius of (?:\d|one|two|three|four|five)\b)/;
const CAPPED = /\b(?:up to|at most|max(?:imum)?(?: of)?|no more than|limit(?:ed)? (?:to|of)|cap(?:ped)? (?:at|to)|capped|limit)\s*(?:\d+|one|two|three|four|five|ten)\b/;

type Ctx = { t: string; cl: string[]; config: Record<string, unknown> };
type Rule = {
  id: string;
  severity: PerfSeverity | ((m: RegExpMatchArray, c: Ctx) => PerfSeverity | null);
  /** Returns the matched words, or null. */
  find: (c: Ctx) => { match: string; m?: RegExpMatchArray } | null;
  title: string;
  reason: string;
  safe: string;
  bounds: string[];
};

const firstClause = (c: Ctx, re: RegExp, guard?: (cl: string, m: RegExpMatchArray) => boolean) => {
  for (const cl of c.cl) {
    const m = cl.match(re);
    if (m && !(guard && guard(cl, m))) return { match: m[0], m };
  }
  return null;
};

// ------------------------------------------------------------------ rules ----
export const RULES: Rule[] = [
  {
    // ChunkMirror: every event (block/mob/change) copied into every chunk/world: events x targets.
    id: "fanout-mirror",
    severity: "critical",
    find: (c) => firstClause(c, new RegExp(`\\b${COPY_VERB}\\b.{0,80}?\\b(?:into|to|in|across|over|onto|throughout)\\s+${ALL}\\s+(?:${WORLD_TARGET})`), (cl) => BOUNDED.test(cl))
      ?? firstClause(c, new RegExp(`\\b${COPY_VERB}\\b.{0,60}\\b(?:everywhere|across the (?:whole |entire )?(?:world|map|server))`), (cl) => BOUNDED.test(cl)),
    title: "Copies changes into every chunk",
    reason: "Every block change or mob spawn would be repeated once per chunk. A world has thousands of chunks, so one placed block becomes thousands of block changes, and one mob becomes thousands of mobs. This is what drops a server to 1 TPS.",
    safe: "Mirror only into chunks near the change (default: 2 chunks around it), through a queue that applies at most 64 block changes per tick, and keep mob mirroring off unless an operator turns it on.",
    bounds: [
      "Mirror only into loaded chunks within a radius of 2 chunks of the change (config mirror.radius-chunks, hard maximum 4).",
      "Apply mirrored block changes through one queue: at most 64 block changes per tick (config perf.max-work-per-tick), at most 2000 queued changes; drop the oldest when full and log it once.",
      "Mob mirroring is OFF by default (config mirror.mobs: false); when on, at most 1 mirrored mob per chunk per second and never more than 20 of the mod's mobs in one chunk.",
      "Never mirror a change that the mod itself made (no feedback loop through its own events).",
      "An operator command turns mirroring on and off (default off after a restart until enabled in config).",
    ],
  },
  {
    id: "chunk-replay-log",
    severity: "high",
    find: (c) => firstClause(c, /\b(?:remember(?:ed|s)?|stor(?:e|ed|es)|sav(?:e|ed|es)|keep|kept|record(?:ed|s)?|log(?:ged|s)?|queue(?:d|s)?)\b.{0,80}\b(?:chunks? (?:that|which|when|as they|as it|once they)?\s*(?:load|loads|loaded|generate|generates|generated)|later loaded chunks?|chunks? loading later|new chunks?|future chunks?)/, (cl) => BOUNDED.test(cl) && !/every|all/.test(cl)),
    title: "Replays a growing history on every chunk load",
    reason: "A list of every change ever made only grows, and replaying it each time a chunk loads gets slower every minute the server runs. It also eats memory until the server stops.",
    safe: "Keep at most a fixed number of remembered changes (default 2000, oldest dropped), store them per chunk, and replay only that chunk's own entries, a few per tick.",
    bounds: [
      "Remember at most 2000 changes in total (config mirror.max-remembered), dropping the oldest; store them per chunk key so a chunk load only reads its own entries.",
      "Replay remembered changes for a loading chunk through the same per-tick queue (never all at once inside ChunkLoadEvent).",
    ],
  },
  {
    id: "per-tick-world-scan",
    severity: "high",
    find: (c) => firstClause(c, new RegExp(`\\b(?:every|each|per) (?:game )?tick\\b.{0,80}\\b${ALL} (?:entit(?:y|ies)|mobs?|blocks?|chunks?|items?|loaded chunks?)|\\b${ALL} (?:entit(?:y|ies)|mobs?|blocks?|chunks?|items?)\\b.{0,60}\\b(?:every|each|per) (?:game )?tick\\b`), (cl) => /\b(?:you|player)s? (?:hold|holds|are holding|wear|wears)\b/.test(cl) && !/world|server|loaded/.test(cl)),
    title: "Looks at everything in the world every tick",
    reason: "Doing work for every entity, block or chunk 20 times a second grows with the size of the world and the number of players, so a busy server falls behind.",
    safe: "Check only things near players (a small radius), spread the work over several ticks, and run it a few times a second instead of every tick.",
    bounds: [
      "Never iterate all entities, blocks or loaded chunks of a world in one tick: limit each pass to entities within 16 blocks of online players (config perf.scan-radius, hard maximum 48).",
      "Run the repeating task at most every 10 ticks and process at most 64 entities or blocks per run (config perf.max-work-per-tick); continue where it stopped on the next run.",
    ],
  },
  {
    id: "world-wide-iteration",
    severity: (m, c) => (c.cl.some((cl) => /\b(?:every|each|per) (?:game )?(?:tick|second)\b/.test(cl)) ? "high" : "medium"),
    find: (c) => firstClause(c, new RegExp(`\\b(?:every|all|each) (?:single )?(?:block|blocks|entity|entities|mob|mobs|item|items) (?:in|on|of|across|throughout) (?:the |a |every |all )?(?:whole |entire |)(?:world|map|server|loaded chunks?|dimension)`)),
    title: "Touches every block or entity in the world",
    reason: "A Minecraft world holds billions of blocks and thousands of entities. Touching all of them at once freezes the server for seconds or minutes.",
    safe: "Work in a bounded area around players or a selected region, a fixed number of blocks per tick, started by an operator command.",
    bounds: ["Limit the operation to a selected region or a radius of at most 64 blocks around the player, applied at most 256 blocks per tick through a queue, started by an operator command with a progress message."],
  },
  {
    id: "whole-chunk-blocks",
    severity: "medium",
    find: (c) => firstClause(c, /\b(?:every|all|each) (?:single )?blocks? (?:in|of) (?:the |a |this |that |every |each |your )?chunks?\b/),
    title: "Changes every block of a chunk at once",
    reason: "A chunk is about 98,000 blocks. Changing all of them in one go stalls the server for a moment each time.",
    safe: "Spread the chunk's blocks over several ticks (at most 256 per tick) and only for chunks a player is in.",
    bounds: ["Process a chunk's blocks through a queue, at most 256 block changes per tick, only for the chunk a player is standing in."],
  },
  {
    id: "recursive-spawn",
    severity: (_m, c) => (c.cl.some((cl) => CAPPED.test(cl)) ? "medium" : "critical"),
    find: (c) => firstClause(c, /\b(?:(?:spawns?|summons?|splits? into|turns? into|creates?|drops?) (?:\d+|two|three|four|five|ten|more|another|extra|copies|clones|new) (?:(?:more|new|extra|smaller|baby|tiny) )?(?:mobs?|zombies?|creepers?|slimes?|entities|copies|clones|tnt|primed tnt|chickens?|pigs?|skeletons?|spiders?|endermen|bees?|silverfish|of (?:itself|themselves))\b[^.]{0,80}\b(?:when (?:it|they|killed|hit|damaged|dies|die|exploded?)|on death|each time|every time|whenever)|\b(?:multipl(?:y|ies|ying)|self.?replicat\w*|exponential\w*|recursive\w*|chain reactions?|keep(?:s)? (?:spawning|multiplying|duplicating))\b)/, (cl) => /\b(?:slime|magma cube)s? split\b/.test(cl) && !/more|extra|forever|infinite/.test(cl)),
    title: "Spawns that make more spawns",
    reason: "When each mob or explosion creates more of itself, the count doubles again and again: 10 steps of doubling is over 1,000 entities.",
    safe: "Cap the chain: at most 3 generations, at most 50 of the mod's mobs per world and 10 per chunk; extra spawns are skipped.",
    bounds: ["Track generations: a spawned copy never spawns more after 3 generations; at most 50 of the mod's mobs per world and 10 per chunk (config perf.max-entities, perf.max-entities-per-chunk); skip spawns above the cap."],
  },
  {
    id: "cascading-explosions",
    severity: (_m, c) => (c.cl.some((cl) => CAPPED.test(cl)) ? "medium" : "high"),
    find: (c) => firstClause(c, /\b(?:explosions? (?:that )?(?:trigger|triggers|cause|causes|set off|sets off|spawn|spawns|make|makes) (?:more|another|other|new|chain|bigger)|chain (?:explosions?|tnt)|tnt (?:that|which) (?:spawns|explodes into|creates) (?:more|another)|(?:infinite|endless|unlimited|never.?ending) (?:tnt|explosions?|nukes?)|nuke|cascading explosions?|explosions? every tick)\b/),
    title: "Explosions that set off more explosions",
    reason: "Every explosion recalculates blocks and entities around it. A chain multiplies that work until the server freezes, and it can destroy a large part of the world.",
    safe: "At most 1 follow-up explosion per explosion, at most 5 explosions per second per world, power capped at 4 (TNT is 4), and block damage off by default.",
    bounds: ["At most 1 follow-up explosion per explosion and 3 chain steps, at most 5 explosions per second per world (rate limiter), explosion power capped at 4, block damage off by default (config)."],
  },
  {
    id: "mass-spawn",
    severity: (m) => (num(m[1]) >= 1000 || /thousands|millions?/.test(m[0]) ? "critical" : num(m[1]) >= 200 || /hordes?|army|armies|swarms?|hundreds/.test(m[0]) ? "high" : "medium"),
    find: (c) => {
      for (const cl of c.cl) {
        const m = cl.match(/\b(?:spawns?|summons?|creates?|drops?|releases?)\b[^.]{0,30}?\b(\d[\d,]*|hundreds of|thousands of|millions? of|a million|hordes? of|an army of|armies of|swarms? of)\s*(?:\w+ )?(?:mobs?|zombies?|creepers?|skeletons?|entities|chickens?|cows?|pigs?|villagers?|bats?|bees?|items?|tnt|arrows?|fireworks?|minions?|monsters?|enemies|spiders?|wolves|slimes?|endermen|withers?)\b/);
        if (m && (Number.isNaN(num(m[1])) || num(m[1]) >= 100)) return { match: m[0], m };
      }
      return null;
    },
    title: "Spawns a very large number of entities",
    reason: "Each mob costs work every tick (movement, AI, collisions). Hundreds at once in one place slow the server for everyone, and thousands stop it.",
    safe: "Spawn in waves: at most 5 per second, at most 50 alive from this mod per world and 10 per chunk, removed when the event ends.",
    bounds: ["Spawn at most 5 entities per second (rate limiter), at most 50 alive from this mod per world and 10 per chunk (config perf.max-entities, perf.max-entities-per-chunk); clean up the mod's own entities when the event ends and in onDisable."],
  },
  {
    id: "unbounded-infinite",
    severity: "high",
    find: (c) => firstClause(c, /\b(?:infinite(?:ly)?|endless(?:ly)?|unlimited|forever|never.?ending|without (?:a |any )?(?:limit|cap|end)|no (?:limit|cap|maximum))\b[^.]{0,30}\b(?:spawn\w*|mobs?|entities|copies|clones|loops?|recursion|growth|grows?|spread\w*|chunks?|blocks?|particles?|waves?)\b|\b(?:spawn\w*|spread\w*|grows?|copies|duplicat\w*|loops?|repeat\w*)\b[^.]{0,30}\b(?:infinite(?:ly)?|endless(?:ly)?|forever|without (?:a |any )?(?:limit|cap|end)|with no (?:limit|cap|end))\b/, (cl) => /\b(?:infinite|unlimited) (?:durability|food|hunger|water|lava|ammo|arrows?|flight|fly|uses?|range|health|saturation|xp|money|storage|backpack)\b/.test(cl) && !/spawn|mobs|entit|copies|clone|spread|grow/.test(cl)),
    title: "No upper limit",
    reason: "Anything that grows without a limit (spawns, spreading blocks, copies, loops) eventually uses all of the server's time or memory.",
    safe: "Give it a hard cap and a rate: a configurable maximum count and a per-second limit, and stop cleanly when reached.",
    bounds: ["Every growing or repeating effect has a hard maximum (configurable, sensible default) and a per-second rate limit; it stops cleanly and logs once when the maximum is reached."],
  },
  {
    id: "spreading-blocks",
    severity: (_m, c) => (c.cl.some((cl) => CAPPED.test(cl) || BOUNDED.test(cl)) ? "medium" : "high"),
    find: (c) => firstClause(c, /\b(?:spreads?|spreading|infects?|infecting|takes? over|consumes?|eats?|grows? across)\b[^.]{0,40}\b(?:the )?(?:whole |entire )?(?:world|map|blocks?|chunks?|everything|terrain)\b/, (cl) => /\b(?:fire|grass|moss|vines?|sculk) spreads? (?:normally|like vanilla)\b/.test(cl)),
    title: "Blocks that spread on their own",
    reason: "A spreading block that converts its neighbours keeps creating more work every tick and can cover the world.",
    safe: "Spread a fixed number of blocks per tick (default 16) inside a radius around where it started (default 32 blocks), with an operator command to stop it.",
    bounds: ["Spread at most 16 blocks per tick per world (config perf.max-work-per-tick) and never further than 32 blocks from its origin (config spread.radius, hard maximum 64); an operator command stops and clears it."],
  },
  {
    id: "huge-radius",
