    severity: "high",
    find: (c) => firstClause(c, /\b(?:infinite(?:ly)?|endless(?:ly)?|unlimited|forever|never.?ending|without (?:a |any )?(?:limit|cap|end)|no (?:limit|cap|maximum))\b[^.]{0,30}\b(?:spawn\w*|mobs?|entities|copies|clones|loops?|recursion|growth|grows?|spread\w*|chunks?|blocks?|particles?|waves?)\b|\b(?:spawn\w*|spread\w*|grows?|copies|duplicat\w*|loops?|repeat\w*)\b[^.]{0,30}\b(?:infinite(?:ly)?|endless(?:ly)?|forever|without (?:a |any )?(?:limit|cap|end)|with no (?:limit|cap|end))\b/, (cl) => /\b(?:infinite|unlimited) (?:durability|food|hunger|water|lava|ammo|arrows?|flight|fly|uses?|range|health|saturation|xp|money|storage|backpack)\b/.test(cl) && !/spawn|mobs|entit|copies|clone|spread|grow/.test(cl)),
    title: "No upper limit",
    reason: "Anything that grows without a limit (spawns, spreading blocks, copies, loops) eventually uses all of the server's time or memory.",
    safe: "Give it a hard cap and a rate: a configurable maximum count and a per-second limit, and stop cleanly when reached.",
    bounds: ["Every growing or repeating effect has a hard maximum (configurable, sensible default) and a per-second rate limit; it stops cleanly and logs once when the maximum is reached."],
  },
  {
    id: "spreading-blocks",
    severity: (_m, c) => (c.cl.some((cl) => CAPPED.test(cl) || BOUNDED.test(cl)) ? "medium" : "high"),
    find: (c) => firstClause(c, /\b(?:spreads?|spreading|infects?|infecting|takes? over|consumes?|eats?|grows? across)\b[^.]{0,40}\b(?:the )?(?:whole |entire )?(?:world|map|blocks?|chunks?|everything|terrain)\b/, (cl) => /\b(?:fire|grass|moss|vines?|sculk) spreads? (?:normally|like vanilla)\b/.test(cl)),
    title: "Blocks that spread on their own",
    reason: "A spreading block that converts its neighbours keeps creating more work every tick and can cover the world.",
    safe: "Spread a fixed number of blocks per tick (default 16) inside a radius around where it started (default 32 blocks), with an operator command to stop it.",
    bounds: ["Spread at most 16 blocks per tick per world (config perf.max-work-per-tick) and never further than 32 blocks from its origin (config spread.radius, hard maximum 64); an operator command stops and clears it."],
  },
  {
    id: "huge-radius",
    severity: (m) => (num(m[1]) >= 256 ? "high" : "medium"),
    find: (c) => {
      for (const cl of c.cl) {
        const m = cl.match(/\b(?:radius (?:of )?|within |range (?:of )?|in a |around |up to )(\d[\d,]*)\s*(?:blocks?|block radius|meters?|m)\b|\b(\d[\d,]*)\s*(?:blocks?|block) (?:radius|range|around)\b/);
        if (!m) continue;
        const n = num(m[1] ?? m[2]);
        // only work that is repeated over the area (scan, damage, effect, spawn, change, particles), not a one-off teleport
        if (n >= 64 && /\b(?:every|each|all|scan\w*|check\w*|affects?|damag\w*|effects?|gives?|apply|applies|spawn\w*|change\w*|replace\w*|break\w*|destroy\w*|particles?|push\w*|pull\w*|heal\w*|kill\w*|freez\w*|ignit\w*|burn\w*)\b/.test(cl) && !/\bteleport\w*\b|\brandom (?:location|spot|place)\b|\brtp\b|\bwild\b/.test(cl)) return { match: m[0], m: [m[0], String(n)] as unknown as RegExpMatchArray };
      }
      return null;
    },
    title: "Works over a very large radius",
    reason: "The work over an area grows with the square (or cube) of the radius: 64 blocks is 16 times the work of 16 blocks, 256 blocks is 256 times.",
    safe: "Cap the radius (default 16 blocks, hard maximum 48) and only affect what is actually loaded near players.",
    bounds: ["Cap every area effect radius at 48 blocks (config, default 16) and only touch loaded chunks; for entities use getNearbyEntities with that radius, never the whole world's entity list."],
  },
  {
    id: "per-tick-all-players-heavy",
    severity: "medium",
    find: (c) => firstClause(c, /\b(?:every|each|per) (?:game )?tick\b.{0,60}\b(?:every|all|each) (?:online )?players?\b.{0,60}\b(?:scan\w*|search\w*|check\w* (?:every|all|each|the area|blocks|entities)|spawn\w*|particles? (?:everywhere|in a (?:big|huge|large))|load\w* chunks?|sav\w*|writ\w* (?:to )?(?:a )?(?:file|disk))\b/),
    title: "Heavy work for every player 20 times a second",
    reason: "Per-player work every tick multiplies with the player count; disk writes or area scans there make busy servers stutter.",
    safe: "Run it every 10-20 ticks, with a small per-run budget, and save to disk on a timer instead of every tick.",
    bounds: ["Per-player repeating work runs at most every 10 ticks with a small budget per run; disk writes happen on a timer (at most every 60 seconds) and in onDisable, never per tick."],
  },
  {
    id: "lag-intent",
    severity: "critical",
    find: (c) => firstClause(c, /\b(?:lag machine|lag the server|crash the server|make the server lag|maximum lag|as laggy as|stress test the server|tps killer|server killer)\b/),
    title: "Built to slow the server down",
    reason: "A mod whose purpose is lag hurts every player on the server and can corrupt the world when the server is forced to stop.",
    safe: "Not built as a lag tool. If this is a stress test, use a bounded benchmark command an operator starts, with a fixed duration and limits.",
    bounds: ["Any load-generating feature is an operator-only command with a fixed duration (at most 60 seconds), a per-tick budget and an automatic stop when TPS falls below 15."],
  },
];

// Config values from the request (e.g. a settings form) that imply unbounded work.
type ConfigRule = { id: string; key: RegExp; test: (v: unknown) => PerfSeverity | null; title: string; reason: string; safe: string; bounds: string[] };
const asNum = (v: unknown) => (typeof v === "number" ? v : typeof v === "string" && /^\s*-?\d+(\.\d+)?\s*$/.test(v) ? Number(v) : NaN);
export const CONFIG_RULES: ConfigRule[] = [
  {
    id: "config-per-tick",
    key: /(?:per[-_ .]?tick|per[-_ .]?cycle|batch[-_ .]?size|work[-_ .]?per|blocks[-_ .]?per|chunks[-_ .]?per|entities[-_ .]?per|operations[-_ .]?per)/i,
    test: (v) => { const n = asNum(v); return n > 256 ? "high" : n > 64 ? "medium" : null; },
    title: "A per-tick amount set very high",
    reason: "A setting that does this much work every tick (20 times a second) leaves no time for the rest of the server.",
    safe: "Keep per-tick work at 64 or less (the safe default); it can be raised by the owner later, up to 256.",
    bounds: ["Every per-tick amount in config defaults to 64 at most and is clamped to a hard maximum of 256 when read."],
  },
  {
    id: "config-radius",
    key: /(?:radius|range|distance)/i,
    test: (v) => { const n = asNum(v); return n >= 256 ? "high" : n >= 96 ? "medium" : null; },
    title: "A radius set very large",
    reason: "Work over an area grows with the square of the radius.",
    safe: "Default radius 16 blocks, clamped to at most 48 when read.",
    bounds: ["Every radius in config defaults to 16 blocks or less and is clamped to at most 48 when read."],
  },
  {
    id: "config-mirror-mobs",
    key: /(?:mirror|copy|clone|duplicate|replicate)[-_ .]?(?:mobs?|entit(?:y|ies)|spawns?)/i,
    test: (v) => (v === true || v === "true" ? "high" : null),
    title: "Mob copying switched on",
    reason: "Copying every mob spawn multiplies the number of mobs on the server.",
    safe: "Ship with mob copying off; when an operator turns it on, at most 1 copy per chunk per second and 20 per chunk.",
    bounds: ["Mob copying defaults to false; when enabled, at most 1 copied mob per chunk per second and at most 20 of the mod's mobs per chunk."],
  },
  {
    id: "config-max-unbounded",
    key: /(?:^|[-_ .])(?:max|limit|cap)(?:[-_ .]|$)/i,
    test: (v) => { const n = asNum(v); return n === -1 || n === 0 && false ? "medium" : n >= 100000 ? "medium" : null; },
    title: "A limit switched off or set enormous",
    reason: "A maximum of -1 (no limit) or a huge number removes the safety cap.",
    safe: "Keep a real maximum (the mod's safe default).",
    bounds: ["No configurable maximum may be -1 or unlimited: clamp it to the mod's hard maximum when read."],
  },
];

function flatConfig(cfg: unknown, prefix = "", out: [string, unknown][] = [], depth = 0): [string, unknown][] {
  if (!cfg || typeof cfg !== "object" || depth > 4) return out;
  for (const [k, v] of Object.entries(cfg as Record<string, unknown>).slice(0, 200)) {
    const key = prefix ? `${prefix}.${k}` : k;
    if (v && typeof v === "object" && !Array.isArray(v)) flatConfig(v, key, out, depth + 1);
    else out.push([key, v]);
  }
  return out;
}

/** Inline config written in the prompt text, e.g. "chunks-per-tick = 500, mirror-mobs = true". */
function inlineConfig(raw: string): Record<string, unknown> {
  const out: Record<string, unknown> = {};
  for (const m of String(raw ?? "").matchAll(/\b([a-z][a-z0-9]*(?:[-_.][a-z0-9]+)+)\s*(?:=|:|is|to)\s*(true|false|-?\d+(?:\.\d+)?)\b/gi)) {
    out[m[1].toLowerCase()] = m[2] === "true" ? true : m[2] === "false" ? false : Number(m[2]);
  }
  return out;
}

// ------------------------------------------------------------------ main ----
export function classifyPerfRisk(input: { text: string; config?: Record<string, unknown> | null }): PerfRisk {
  const raw = String(input?.text ?? "").slice(0, 20_000);
  const t = normalize(raw);
  const c: Ctx = { t, cl: clauses(t), config: { ...inlineConfig(raw), ...(input?.config ?? {}) } };
  const findings: PerfFinding[] = [];
  for (const r of RULES) {
    const hit = r.find(c);
    if (!hit) continue;
    const sev = typeof r.severity === "function" ? r.severity(hit.m ?? ([hit.match] as unknown as RegExpMatchArray), c) : r.severity;
    if (!sev) continue;
    findings.push({ id: r.id, severity: sev, title: r.title, reason: r.reason, safe: r.safe, bounds: r.bounds, match: hit.match.slice(0, 160) });
  }
  for (const [k, v] of flatConfig(c.config)) {
    for (const r of CONFIG_RULES) {
      if (!r.key.test(k)) continue;
      const sev = r.test(v);
      if (!sev || findings.some((f) => f.id === r.id)) continue;
      findings.push({ id: r.id, severity: sev, title: r.title, reason: r.reason, safe: r.safe, bounds: r.bounds, match: `${k} = ${String(v)}`.slice(0, 160) });
    }
  }
  // Mirroring + remembered chunk replay is the ChunkMirror shape: the replay finding inherits the fan-out's severity.
  const fan = findings.find((f) => f.id === "fanout-mirror");
  if (fan) for (const f of findings) if (f.id === "chunk-replay-log" || f.id === "config-mirror-mobs") f.severity = worse(f.severity, "high") as PerfSeverity;
  findings.sort((a, b) => RANK[b.severity] - RANK[a.severity] || a.id.localeCompare(b.id));
  const level = findings.reduce<PerfLevel>((acc, f) => worse(acc, f.severity), "none");
  const mustConfirm = RANK[level] >= RANK[CONFIRM_AT];
  const summary = !findings.length ? null
    : mustConfirm ? `This request implies unbounded work (${findings.filter((f) => RANK[f.severity] >= RANK[CONFIRM_AT]).map((f) => f.title.toLowerCase()).join("; ")}). Cyrus will build a bounded version unless you choose "Build anyway".`
    : `Cyrus will add limits so this stays light on the server (${findings.map((f) => f.title.toLowerCase()).join("; ")}).`;
  return { schema: "cyrus.perfrisk.v1", version: PERF_RISK_VERSION, level, findings, mustConfirm, defaultChoice: "safe", summary };
}

/**
 * The request to build for a choice. "safe" (default, also for an unknown choice) appends the findings' bounds as a
 * PERFORMANCE LIMITS block (deduped, stable order); "as_asked" returns the text unchanged. Medium/low findings always
 * get their bounds in safe mode (cheap insurance); nothing is appended when there are no findings.
 */
export function applyPerfChoice(text: string, risk: PerfRisk, choice: unknown = risk.defaultChoice): { text: string; choice: PerfChoice; bounds: string[] } {
  const ch: PerfChoice = choice === "as_asked" ? "as_asked" : "safe";
  if (ch === "as_asked" || !risk.findings.length) return { text, choice: ch, bounds: [] };
  const bounds = [...new Set(risk.findings.flatMap((f) => f.bounds))];
  return { text: `${text.trimEnd()}\n\nPERFORMANCE LIMITS (the server owner chose the safe version; these override any number above):\n${bounds.map((b) => `- ${b}`).join("\n")}`, choice: ch, bounds };
}

/** Server-side twin of the plan gate: a high/critical risk needs an explicit choice ("safe" or "as_asked") in the request. */
export function perfPreBuildCheck(risk: PerfRisk, choice: unknown): { ok: true; choice: PerfChoice } | { ok: false; status: 409; json: { error: string; code: "perf_confirm"; risk: PerfRisk } } {
  if (choice === "safe" || choice === "as_asked") return { ok: true, choice };
  if (!risk.mustConfirm) return { ok: true, choice: "safe" };
  return { ok: false, status: 409, json: { error: risk.summary ?? "This request needs a performance choice.", code: "perf_confirm", risk } };
}

/** CYRUS_PERF_SAFETY: default ON; "0" / "false" / "off" turns the whole perf-safety bundle off (kill switch). */
export function perfSafetyEnabled(env: Record<string, string | undefined> = process.env): boolean {
  const v = String(env[PERF_RISK_FLAG] ?? "").trim().toLowerCase();
  return !(v === "0" || v === "false" || v === "off");
}

