// Cyrus perf-risk classifier golden set (lib/cyrus/safety/perf-risk.ts): ~40 prompts incl. the real ChunkMirror prompt
// (2026-10-11 incident) and benign look-alikes that must NOT raise an alarm.
import { describe, it } from "node:test";
import assert from "node:assert/strict";
import { applyPerfChoice, classifyPerfRisk, perfPreBuildCheck, perfSafetyEnabled, type PerfLevel } from "../lib/cyrus/safety/perf-risk";

const CHUNKMIRROR = "Make a plugin called ChunkMirror: copy every block placed/broken and every mob spawn into every other chunk, remembered for chunks that load later. Config: chunks-per-tick = 500, mirror-mobs = true.";

type G = { p: string; level: PerfLevel | "atLeastHigh"; ids?: string[]; not?: string[] };
const GOLDEN: G[] = [
  // ---- dangerous
  { p: CHUNKMIRROR, level: "critical", ids: ["fanout-mirror", "chunk-replay-log", "config-per-tick", "config-mirror-mobs"] },
  { p: "Mirror every block change into all loaded chunks so the world looks the same everywhere", level: "critical", ids: ["fanout-mirror"] },
  { p: "duplicate every mob that spawns into every chunk of the world", level: "critical", ids: ["fanout-mirror"] },
  { p: "sync every block I place across the whole world", level: "critical", ids: ["fanout-mirror"] },
  { p: "Every tick, check every entity in the world and give it glowing", level: "atLeastHigh", ids: ["per-tick-world-scan"] },
  { p: "each tick loop over all loaded chunks and count the blocks", level: "atLeastHigh", ids: ["per-tick-world-scan"] },
  { p: "replace every block in the world with gold", level: "medium", ids: ["world-wide-iteration"] },
  { p: "every second remove all items on the whole map", level: "atLeastHigh", ids: ["world-wide-iteration"] },
  { p: "a zombie that spawns 2 more zombies when it dies", level: "critical", ids: ["recursive-spawn"] },
  { p: "chickens that multiply every few seconds", level: "critical", ids: ["recursive-spawn"] },
  { p: "creepers whose explosions trigger more explosions, chain reaction style", level: "critical", ids: ["cascading-explosions", "recursive-spawn"] },
  { p: "infinite tnt rain over the spawn", level: "atLeastHigh", ids: ["cascading-explosions"] },
  { p: "a command that spawns 5000 zombies around you", level: "critical", ids: ["mass-spawn"] },
  { p: "summon an army of skeletons at the castle", level: "high", ids: ["mass-spawn"] },
  { p: "spawn 300 pigs in a field", level: "high", ids: ["mass-spawn"] },
  { p: "a wand that spawns 120 bats", level: "medium", ids: ["mass-spawn"] },
  { p: "mobs keep spawning forever at the arena", level: "atLeastHigh", ids: ["unbounded-infinite"] },
  { p: "a virus block that spreads across the whole world", level: "high", ids: ["spreading-blocks"] },
  { p: "freeze every mob within 500 blocks every second", level: "atLeastHigh", ids: ["huge-radius"] },
  { p: "a staff that damages all entities in a 100 block radius", level: "medium", ids: ["huge-radius"] },
  { p: "build me a lag machine to stress test the server", level: "critical", ids: ["lag-intent"] },
  { p: "every tick, for all online players, scan the blocks around them and save to a file", level: "atLeastHigh", ids: ["per-tick-all-players-heavy"] },
  { p: "remember every block change and replay it in new chunks as they load", level: "high", ids: ["chunk-replay-log"] },
  { p: "set every block of the chunk to glass when you click", level: "medium", ids: ["whole-chunk-blocks"] },
  // ---- benign look-alikes (no false alarms)
  { p: "give players speed in the chunk you stand in", level: "none" },
  { p: "every block you mine has a 5% chance to drop a diamond", level: "none" },
  { p: "an infinite water bucket and a sword with infinite durability", level: "none" },
  { p: "unlimited flight for VIP players", level: "none" },
  { p: "send every player a welcome message when they join", level: "none" },
  { p: "spawn a zombie when you right-click the totem", level: "none" },
  { p: "copy the block you are looking at into your inventory", level: "none" },
  { p: "a /rtp command that teleports you to a random location within 5000 blocks", level: "none" },
  { p: "show flame particles around the player every tick while they hold the staff", level: "none" },
  { p: "mirror the build in the chunk you are standing in to the other half of that chunk", level: "none", not: ["fanout-mirror"] },
  { p: "magma cubes and slimes split like vanilla", level: "none" },
  { p: "fire spreads normally, but add a fire resistance potion recipe", level: "none" },
  { p: "a minigame with up to 10 waves of zombies", level: "none" },
  { p: "sync player inventories between the lobby and survival worlds", level: "none" },
  { p: "every mob that spawns at night has a 10% chance to wear a pumpkin", level: "none" },
  { p: "log every chat message to a file", level: "none" },
  { p: "a mob that spawns 3 minions when hit, up to 6 minions at a time", level: "medium", ids: ["recursive-spawn"] },
];

const RANK = { none: 0, low: 1, medium: 2, high: 3, critical: 4 } as const;

describe("perf-risk classifier: golden prompts", () => {
  assert.ok(GOLDEN.length >= 40, "golden set has ~40 prompts");
  for (const g of GOLDEN) {
    it(`${g.level}: ${g.p.slice(0, 70)}`, () => {
      const r = classifyPerfRisk({ text: g.p });
      const ids = r.findings.map((f) => f.id);
      if (g.level === "atLeastHigh") assert.ok(RANK[r.level] >= RANK.high, `level ${r.level} (${ids.join(",")})`);
      else assert.equal(r.level, g.level, `findings: ${JSON.stringify(r.findings.map((f) => [f.id, f.severity, f.match]))}`);
      for (const id of g.ids ?? []) assert.ok(ids.includes(id), `expected ${id} in ${ids.join(",")}`);
      for (const id of g.not ?? []) assert.ok(!ids.includes(id), `did not expect ${id}`);
      assert.equal(r.mustConfirm, RANK[r.level] >= RANK.high);
      for (const f of r.findings) { assert.ok(f.reason.length > 20 && f.safe.length > 20 && f.bounds.length > 0, `plain reason + safe alternative for ${f.id}`); }
    });
  }
});

describe("perf-risk classifier: contract", () => {
  it("is deterministic", () => {
    assert.deepEqual(classifyPerfRisk({ text: CHUNKMIRROR }), classifyPerfRisk({ text: CHUNKMIRROR }));
  });
  it("ChunkMirror: safe alternative mentions a radius, a per-tick queue and mobs off", () => {
    const r = classifyPerfRisk({ text: CHUNKMIRROR });
    assert.equal(r.defaultChoice, "safe");
    const a = applyPerfChoice(CHUNKMIRROR, r);
    assert.equal(a.choice, "safe");
    assert.match(a.text, /PERFORMANCE LIMITS/);
    assert.match(a.text, /radius of 2 chunks/);
    assert.match(a.text, /at most 64 block changes per tick/);
    assert.match(a.text, /Mob mirroring is OFF by default/);
    assert.ok(a.text.startsWith(CHUNKMIRROR));
    assert.equal(new Set(a.bounds).size, a.bounds.length);
  });
  it("build anyway keeps the request unchanged", () => {
    const r = classifyPerfRisk({ text: CHUNKMIRROR });
    assert.deepEqual(applyPerfChoice(CHUNKMIRROR, r, "as_asked"), { text: CHUNKMIRROR, choice: "as_asked", bounds: [] });
    assert.equal(applyPerfChoice("x", r, "bogus").choice, "safe");
  });
  it("structured config values are judged too", () => {
    const r = classifyPerfRisk({ text: "a block mirror mod", config: { mirror: { "chunks-per-tick": 500, "mirror-mobs": true, radius: 1000 } } });
    const ids = r.findings.map((f) => f.id);
    assert.deepEqual(["config-mirror-mobs", "config-per-tick", "config-radius"].filter((i) => ids.includes(i)).length, 3);
    assert.equal(classifyPerfRisk({ text: "x", config: { "blocks-per-tick": 32, radius: 8 } }).level, "none");
  });
  it("pre-build check: high risk needs a choice, none passes", () => {
    const r = classifyPerfRisk({ text: CHUNKMIRROR });
    const no = perfPreBuildCheck(r, undefined);
    assert.equal(no.ok, false);
    if (!no.ok) { assert.equal(no.status, 409); assert.equal(no.json.code, "perf_confirm"); }
    assert.deepEqual(perfPreBuildCheck(r, "as_asked"), { ok: true, choice: "as_asked" });
    assert.deepEqual(perfPreBuildCheck(classifyPerfRisk({ text: "a gem item" }), undefined), { ok: true, choice: "safe" });
  });
  it("empty / huge input never throws", () => {
    assert.equal(classifyPerfRisk({ text: "" }).level, "none");
    assert.equal(classifyPerfRisk({ text: null as unknown as string }).level, "none");
    classifyPerfRisk({ text: "every chunk ".repeat(5000) });
  });
  it("flag defaults ON, kill switch off", () => {
    assert.equal(perfSafetyEnabled({}), true);
    assert.equal(perfSafetyEnabled({ CYRUS_PERF_SAFETY: "1" }), true);
    assert.equal(perfSafetyEnabled({ CYRUS_PERF_SAFETY: "0" }), false);
    assert.equal(perfSafetyEnabled({ CYRUS_PERF_SAFETY: "off" }), false);
  });
});

