  { p: "creepers whose explosions trigger more explosions, chain reaction style", level: "critical", ids: ["cascading-explosions", "recursive-spawn"] },
  { p: "infinite tnt rain over the spawn", level: "atLeastHigh", ids: ["cascading-explosions"] },
  { p: "a command that spawns 5000 zombies around you", level: "critical", ids: ["mass-spawn"] },
  { p: "summon an army of skeletons at the castle", level: "high", ids: ["mass-spawn"] },
  { p: "spawn 300 pigs in a field", level: "high", ids: ["mass-spawn"] },
  { p: "a wand that spawns 120 bats", level: "medium", ids: ["mass-spawn"] },
  { p: "mobs keep spawning forever at the arena", level: "atLeastHigh", ids: ["unbounded-infinite"] },
  { p: "a virus block that spreads across the whole world", level: "high", ids: ["spreading-blocks"] },
  { p: "freeze every mob within 500 blocks every second", level: "atLeastHigh", ids: ["huge-radius"] },
  { p: "a staff that damages all entities in a 100 block radius", level: "medium", ids: ["huge-radius"] },
  { p: "build me a lag machine to stress test the server", level: "critical", ids: ["lag-intent"] },
  { p: "every tick, for all online players, scan the blocks around them and save to a file", level: "atLeastHigh", ids: ["per-tick-all-players-heavy"] },
  { p: "remember every block change and replay it in new chunks as they load", level: "high", ids: ["chunk-replay-log"] },
  { p: "set every block of the chunk to glass when you click", level: "medium", ids: ["whole-chunk-blocks"] },
  // ---- benign look-alikes (no false alarms)
  { p: "give players speed in the chunk you stand in", level: "none" },
  { p: "every block you mine has a 5% chance to drop a diamond", level: "none" },
  { p: "an infinite water bucket and a sword with infinite durability", level: "none" },
  { p: "unlimited flight for VIP players", level: "none" },
  { p: "send every player a welcome message when they join", level: "none" },
  { p: "spawn a zombie when you right-click the totem", level: "none" },
  { p: "copy the block you are looking at into your inventory", level: "none" },
  { p: "a /rtp command that teleports you to a random location within 5000 blocks", level: "none" },
  { p: "show flame particles around the player every tick while they hold the staff", level: "none" },
  { p: "mirror the build in the chunk you are standing in to the other half of that chunk", level: "none", not: ["fanout-mirror"] },
  { p: "magma cubes and slimes split like vanilla", level: "none" },
  { p: "fire spreads normally, but add a fire resistance potion recipe", level: "none" },
  { p: "a minigame with up to 10 waves of zombies", level: "none" },
