  { p: "a mob that spawns 3 minions when hit, up to 6 minions at a time", level: "medium", ids: ["recursive-spawn"] },
];

const RANK = { none: 0, low: 1, medium: 2, high: 3, critical: 4 } as const;

describe("perf-risk classifier: golden prompts", () => {
  assert.ok(GOLDEN.length >= 40, "golden set has ~40 prompts");
  for (const g of GOLDEN) {
    it(`${g.level}: ${g.p.slice(0, 70)}`, () => {
      const r = classifyPerfRisk({ text: g.p });
      const ids = r.findings.map((f) => f.id);
      if (g.level === "atLeastHigh") assert.ok(RANK[r.level] >= RANK.high, `level ${r.level} (${ids.join(",")})`);
      else assert.equal(r.level, g.level, `findings: ${JSON.stringify(r.findings.map((f) => [f.id, f.severity, f.match]))}`);
      for (const id of g.ids ?? []) assert.ok(ids.includes(id), `expected ${id} in ${ids.join(",")}`);
      for (const id of g.not ?? []) assert.ok(!ids.includes(id), `did not expect ${id}`);
      assert.equal(r.mustConfirm, RANK[r.level] >= RANK.high);
      for (const f of r.findings) { assert.ok(f.reason.length > 20 && f.safe.length > 20 && f.bounds.length > 0, `plain reason + safe alternative for ${f.id}`); }
    });
  }
});

describe("perf-risk classifier: contract", () => {
  it("is deterministic", () => {
    assert.deepEqual(classifyPerfRisk({ text: CHUNKMIRROR }), classifyPerfRisk({ text: CHUNKMIRROR }));
  });
  it("ChunkMirror: safe alternative mentions a radius, a per-tick queue and mobs off", () => {
    const r = classifyPerfRisk({ text: CHUNKMIRROR });
    assert.equal(r.defaultChoice, "safe");
    const a = applyPerfChoice(CHUNKMIRROR, r);
    assert.equal(a.choice, "safe");
    assert.match(a.text, /PERFORMANCE LIMITS/);
    assert.match(a.text, /radius of 2 chunks/);
    assert.match(a.text, /at most 64 block changes per tick/);
    assert.match(a.text, /Mob mirroring is OFF by default/);
    assert.ok(a.text.startsWith(CHUNKMIRROR));
    assert.equal(new Set(a.bounds).size, a.bounds.length);
  });
  it("build anyway keeps the request unchanged", () => {
    const r = classifyPerfRisk({ text: CHUNKMIRROR });
    assert.deepEqual(applyPerfChoice(CHUNKMIRROR, r, "as_asked"), { text: CHUNKMIRROR, choice: "as_asked", bounds: [] });
    assert.equal(applyPerfChoice("x", r, "bogus").choice, "safe");
  });
  it("structured config values are judged too", () => {
    const r = classifyPerfRisk({ text: "a block mirror mod", config: { mirror: { "chunks-per-tick": 500, "mirror-mobs": true, radius: 1000 } } });
    const ids = r.findings.map((f) => f.id);
    assert.deepEqual(["config-mirror-mobs", "config-per-tick", "config-radius"].filter((i) => ids.includes(i)).length, 3);
    assert.equal(classifyPerfRisk({ text: "x", config: { "blocks-per-tick": 32, radius: 8 } }).level, "none");
  });
  it("pre-build check: high risk needs a choice, none passes", () => {
    const r = classifyPerfRisk({ text: CHUNKMIRROR });
    const no = perfPreBuildCheck(r, undefined);
    assert.equal(no.ok, false);
    if (!no.ok) { assert.equal(no.status, 409); assert.equal(no.json.code, "perf_confirm"); }
    assert.deepEqual(perfPreBuildCheck(r, "as_asked"), { ok: true, choice: "as_asked" });
    assert.deepEqual(perfPreBuildCheck(classifyPerfRisk({ text: "a gem item" }), undefined), { ok: true, choice: "safe" });
  });
  it("empty / huge input never throws", () => {
    assert.equal(classifyPerfRisk({ text: "" }).level, "none");
    assert.equal(classifyPerfRisk({ text: null as unknown as string }).level, "none");
    classifyPerfRisk({ text: "every chunk ".repeat(5000) });
  });
  it("flag defaults ON, kill switch off", () => {
    assert.equal(perfSafetyEnabled({}), true);
    assert.equal(perfSafetyEnabled({ CYRUS_PERF_SAFETY: "1" }), true);
    assert.equal(perfSafetyEnabled({ CYRUS_PERF_SAFETY: "0" }), false);
    assert.equal(perfSafetyEnabled({ CYRUS_PERF_SAFETY: "off" }), false);
  });
});

