package @PKG@;

/**
 * Nxeon performance watchdog, pure half (no Bukkit types, unit-tested on its own by perf/test/NxPerfCoreTest.java).
 * Injected by the Nxeon build service into every generated plugin as {@code <plugin package>.nxperf}; do not edit:
 * the build service overwrites this file on every build. Holds the per-tick work budgets, the per-second rate limits
 * and the lag judge that decides when the plugin's heavy features must pause.
 */
public final class NxPerfCore {
  public static final String VERSION = "nxperf-1";

  private NxPerfCore() {}

  public static double clamp(double v, double lo, double hi) {
    if (Double.isNaN(v)) return lo;
    return Math.max(lo, Math.min(hi, v));
  }

  public static int clampInt(long v, int lo, int hi) {
    return (int) Math.max(lo, Math.min(hi, v));
  }

  /** The perf.* config section, clamped to safe ranges (a config can tighten the limits, never remove them). */
  public static final class Settings {
    public boolean autoDisable = true;
    public double tpsFloor = 15.0;
    public int windowSeconds = 10;
    public int maxWorkPerTick = 64;
    public double maxMsPerTick = 25.0;
    public double share = 0.25;
    public double freezeMs = 2000.0;
    public int maxEntitiesPerSecond = 5;
    public int maxEntitiesPerChunk = 20;
    public int maxQueue = 2000;
    public int maxRadius = 48;
    public int statusLogSeconds = 300;

    public Settings clampAll() {
      tpsFloor = clamp(tpsFloor, 5.0, 19.5);
      windowSeconds = clampInt(windowSeconds, 3, 120);
      maxWorkPerTick = clampInt(maxWorkPerTick, 1, 256);
      maxMsPerTick = clamp(maxMsPerTick, 2.0, 45.0);
      share = clamp(share, 0.05, 0.9);
      freezeMs = clamp(freezeMs, 250.0, 10000.0);
      maxEntitiesPerSecond = clampInt(maxEntitiesPerSecond, 1, 50);
      maxEntitiesPerChunk = clampInt(maxEntitiesPerChunk, 1, 100);
      maxQueue = clampInt(maxQueue, 10, 20000);
      maxRadius = clampInt(maxRadius, 1, 64);
      statusLogSeconds = clampInt(statusLogSeconds, 30, 3600);
      return this;
    }
  }

  /** Work units per server tick; resets when the tick number changes. */
  public static final class Budget {
    public final String name;
    private int perTick;
    private long tick = Long.MIN_VALUE;
    private int used;
    private long denied;
    private long total;

    public Budget(String name, int perTick) {
      this.name = name;
      this.perTick = Math.max(1, perTick);
    }

    public synchronized boolean take(long nowTick, int n) {
      if (nowTick != tick) {
        tick = nowTick;
        used = 0;
      }
      if (n <= 0) return true;
      if ((long) used + n > perTick) {
        denied++;
        return false;
      }
      used += n;
      total += n;
      return true;
    }

    public synchronized int remaining(long nowTick) {
      return nowTick != tick ? perTick : Math.max(0, perTick - used);
    }

    public synchronized void setPerTick(int v) { perTick = Math.max(1, v); }
    public synchronized int perTick() { return perTick; }
    public synchronized long denied() { return denied; }
    public synchronized long total() { return total; }
  }

  /** Token bucket: at most perSecond events per second (burst = one second's worth). */
  public static final class Rate {
    private double perSecond;
    private double tokens;
    private long last = Long.MIN_VALUE;
    private long denied;

    public Rate(double perSecond) {
      this.perSecond = Math.max(0.01, perSecond);
      this.tokens = this.perSecond;
    }

    public synchronized boolean take(long nowNanos) {
      if (last != Long.MIN_VALUE) tokens = Math.min(perSecond, tokens + (nowNanos - last) / 1e9 * perSecond);
      last = nowNanos;
      if (tokens >= 1.0) {
        tokens -= 1.0;
        return true;
      }
      denied++;
      return false;
    }

    public synchronized void setPerSecond(double v) { perSecond = Math.max(0.01, v); tokens = Math.min(tokens, perSecond); }
    public synchronized long denied() { return denied; }
  }

  /** Verdicts of the lag judge. */
  public static final int NONE = 0, TPS = 1, BUDGET = 2;

  /**
   * One sample per wall-clock second: the server's measured TPS and this plugin's own main-thread milliseconds per tick.
   * TPS verdict: for the whole window TPS stayed under the floor AND this plugin used at least `share` of each tick.
   * BUDGET verdict: for the whole window this plugin used more than maxMsPerTick per tick (even if TPS held up).
   * Low TPS with a small share is somebody else's lag: never a pause (lowWithoutUs reports it).
   */
  public static final class Judge {
    private final double[] tps;
    private final double[] own;
    private int next;
    private int count;

    public Judge(int capacity) {
      tps = new double[Math.max(4, capacity)];
      own = new double[tps.length];
    }

    public void reset() { next = 0; count = 0; }

    /** A tick takes 1000/tps ms when the server is behind, at least 50 ms otherwise. */
    public static double tickMs(double tpsSample) {
      return Math.max(50.0, 1000.0 / Math.max(0.05, tpsSample));
    }

    public int add(double tpsSample, double ownMsPerTick, Settings s) {
      tps[next] = tpsSample;
      own[next] = Math.max(0, ownMsPerTick);
      next = (next + 1) % tps.length;
      if (count < tps.length) count++;
      int w = Math.min(s.windowSeconds, tps.length);
      if (count < w) return NONE;
      boolean low = true, hog = true;
      for (int i = 1; i <= w; i++) {
        int k = (next - i + tps.length) % tps.length;
        double share = own[k] / tickMs(tps[k]);
        if (!(tps[k] < s.tpsFloor && share >= s.share)) low = false;
        if (!(own[k] > s.maxMsPerTick)) hog = false;
      }
      return low ? TPS : hog ? BUDGET : NONE;
    }

    /** TPS under the floor for the whole window while this plugin's share stayed small. */
    public boolean lowWithoutUs(Settings s) {
      int w = Math.min(s.windowSeconds, tps.length);
      if (count < w) return false;
      for (int i = 1; i <= w; i++) {
        int k = (next - i + tps.length) % tps.length;
        if (!(tps[k] < s.tpsFloor && own[k] / tickMs(tps[k]) < s.share)) return false;
      }
      return true;
    }

    public int samples() { return count; }
  }

  /** "12.34" with a dot whatever the server locale (log lines are parsed by Nxeon's post-install watch). */
  public static String fmt(double v) {
    long r = Math.round(v * 100.0);
    String sign = r < 0 ? "-" : "";
    r = Math.abs(r);
    long cents = r % 100;
    return sign + (r / 100) + "." + (cents < 10 ? "0" : "") + cents;
  }
}

