package @PKG@;

import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.function.Consumer;
import net.kyori.adventure.text.Component;
import net.kyori.adventure.text.format.NamedTextColor;
import org.bukkit.Bukkit;
import org.bukkit.Chunk;
import org.bukkit.command.Command;
import org.bukkit.command.CommandExecutor;
import org.bukkit.command.CommandSender;
import org.bukkit.command.ConsoleCommandSender;
import org.bukkit.command.PluginCommand;
import org.bukkit.configuration.file.FileConfiguration;
import org.bukkit.entity.Entity;
import org.bukkit.entity.LivingEntity;
import org.bukkit.entity.Player;
import org.bukkit.event.Event;
import org.bukkit.event.EventException;
import org.bukkit.event.HandlerList;
import org.bukkit.plugin.Plugin;
import org.bukkit.plugin.RegisteredListener;
import org.bukkit.scheduler.BukkitTask;

/**
 * Nxeon performance watchdog (Bukkit half). Injected by the Nxeon build service into every generated plugin as
 * {@code <plugin package>.nxperf.NxPerf} and started from onEnable; do not edit (overwritten on every build).
 *
 * What it does without any help from the plugin:
 *  - samples the server's real tick rate every second (and Paper's TPS / MSPT for the status);
 *  - measures the main-thread time of this plugin's own event listeners (each one is wrapped once, after onEnable);
 *  - when TPS stays under perf.tps-floor for perf.window-seconds while this plugin uses at least perf.share of each
 *    tick, or the plugin alone uses more than perf.max-ms-per-tick for the whole window, or one tick of its listeners
 *    takes longer than perf.freeze-ms: PAUSES the plugin's heavy features (its costliest listeners, its NxPerf timers
 *    and queues), never the server and never another plugin, logs "[NxPerf] PAUSED ..." and tells online operators;
 *  - "/<command> perf status|pause|resume" (or /<plugin>perf when the plugin has no command), operators/console only.
 * What the plugin uses on purpose (required by the build rules): take()/spawnAllowed()/queue()/timer()/enter()/radius().
 */
public final class NxPerf {
  private NxPerf() {}

  private static Plugin plugin;
  private static final NxPerfCore.Settings S = new NxPerfCore.Settings();
  private static final NxPerfCore.Judge JUDGE = new NxPerfCore.Judge(120);
  private static final Map<String, NxPerfCore.Budget> BUDGETS = new LinkedHashMap<>();
  private static final Map<String, NxPerfCore.Rate> RATES = new HashMap<>();
  private static final Map<String, Integer> DEPTH = new HashMap<>();
  private static final List<Timed> TIMED = new ArrayList<>();
  private static final List<Timed> PAUSED_LISTENERS = new ArrayList<>();
  private static final List<Timer> TIMERS = new ArrayList<>();
  private static final List<Queue<?>> QUEUES = new ArrayList<>();
  private static final List<Runnable> ON_PAUSE = new ArrayList<>();
  private static final List<Runnable> ON_RESUME = new ArrayList<>();
  private static volatile boolean paused;
  private static String pauseReason;
  private static long ownNanosTick, ownNanosSecond, secondStart;
  private static int ticksSecond, secondsSinceStatus, seconds;
  private static long enabledAtMs;
  private static double lastTps = 20.0, lastOwnMs;
  private static boolean lowNoted;
  private static String commandLabel;

  // ------------------------------------------------------------------ lifecycle ----

  /** Called first thing in onEnable (inserted by the build service). Safe to call again after a reload. */
  public static void init(Plugin p) {
    plugin = p;
    BUDGETS.clear(); RATES.clear(); DEPTH.clear(); TIMED.clear(); PAUSED_LISTENERS.clear(); TIMERS.clear(); QUEUES.clear();
    ON_PAUSE.clear(); ON_RESUME.clear();
    paused = false; pauseReason = null; ownNanosTick = 0; ownNanosSecond = 0; secondStart = 0; ticksSecond = 0;
    secondsSinceStatus = 0; seconds = 0; lowNoted = false; commandLabel = null; JUDGE.reset();
    enabledAtMs = System.currentTimeMillis();
    readSettings();
    Bukkit.getScheduler().runTaskTimer(p, NxPerf::tick, 1L, 1L);
    Bukkit.getScheduler().runTaskLater(p, () -> { wrapListeners(); hookCommand(); }, 1L);
    p.getLogger().info("[NxPerf] watchdog " + NxPerfCore.VERSION + " on: pauses heavy features below " + NxPerfCore.fmt(S.tpsFloor)
        + " TPS for " + S.windowSeconds + " s (perf.auto-disable=" + S.autoDisable + ")");
  }

  private static void readSettings() {
    try {
      FileConfiguration c = plugin.getConfig();
      S.autoDisable = c.getBoolean("perf.auto-disable", true);
      S.tpsFloor = c.getDouble("perf.tps-floor", 15.0);
      S.windowSeconds = c.getInt("perf.window-seconds", 10);
      S.maxWorkPerTick = c.getInt("perf.max-work-per-tick", 64);
      S.maxMsPerTick = c.getDouble("perf.max-ms-per-tick", 25.0);
      S.share = c.getDouble("perf.share", 0.25);
      S.maxEntitiesPerSecond = c.getInt("perf.max-entities-per-second", 5);
      S.maxEntitiesPerChunk = c.getInt("perf.max-entities-per-chunk", 20);
      S.maxQueue = c.getInt("perf.max-queue", 2000);
      S.maxRadius = c.getInt("perf.max-radius", 48);
      S.statusLogSeconds = c.getInt("perf.status-log-seconds", 300);
    } catch (RuntimeException e) {
      // keep the defaults: a broken config never switches the watchdog off
    }
    S.clampAll();
    for (NxPerfCore.Budget b : BUDGETS.values()) b.setPerTick(S.maxWorkPerTick);
  }

  private static void tick() {
    long now = System.nanoTime();
    if (secondStart == 0) secondStart = now;
    if (!paused && S.autoDisable && ownNanosTick / 1e6 > S.freezeMs) pause("freeze", "one tick of this plugin's listeners took " + NxPerfCore.fmt(ownNanosTick / 1e6) + " ms");
    ownNanosTick = 0;
    for (Queue<?> q : QUEUES) q.drain();
    ticksSecond++;
    if (now - secondStart < 1_000_000_000L) return;
    double secs = (now - secondStart) / 1e9;
    lastTps = Math.min(20.0, ticksSecond / secs);
    lastOwnMs = ticksSecond > 0 ? ownNanosSecond / 1e6 / ticksSecond : 0;
    ownNanosSecond = 0; ticksSecond = 0; secondStart = now; seconds++;
    for (Timed t : TIMED) t.roll();
    int v = JUDGE.add(lastTps, lastOwnMs, S);
    if (!paused && S.autoDisable && v != NxPerfCore.NONE) {
      pause(v == NxPerfCore.TPS ? "tps" : "budget", "TPS " + NxPerfCore.fmt(lastTps) + " for " + S.windowSeconds + " s, this plugin " + NxPerfCore.fmt(lastOwnMs) + " ms per tick");
    } else if (!paused && JUDGE.lowWithoutUs(S)) {
      if (!lowNoted) plugin.getLogger().info("[NxPerf] LAG plugin=" + plugin.getName() + " tps=" + NxPerfCore.fmt(lastTps) + " own_ms=" + NxPerfCore.fmt(lastOwnMs) + " (not caused by this plugin)");
      lowNoted = true;
    } else if (lastTps >= S.tpsFloor) {
      lowNoted = false;
    }
    if (seconds % 5 == 0) wrapListeners();
    if (seconds % 30 == 0) readSettings();
    int every = System.currentTimeMillis() - enabledAtMs < 15 * 60_000L ? 30 : S.statusLogSeconds;
    if (++secondsSinceStatus >= every) {
      secondsSinceStatus = 0;
      plugin.getLogger().info("[NxPerf] status v=" + NxPerfCore.VERSION + " plugin=" + plugin.getName() + " tps=" + NxPerfCore.fmt(lastTps)
          + " paper_tps=" + NxPerfCore.fmt(paperTps()) + " mspt=" + NxPerfCore.fmt(paperMspt()) + " own_ms=" + NxPerfCore.fmt(lastOwnMs) + " paused=" + paused);
    }
  }

  private static double paperTps() {
    try { return Math.min(20.0, Bukkit.getTPS()[0]); } catch (RuntimeException e) { return lastTps; }
  }

  private static double paperMspt() {
    try { return Bukkit.getAverageTickTime(); } catch (RuntimeException e) { return -1; }
  }

  // ------------------------------------------------------------------ listener timing ----

  /** A listener of this plugin with its main-thread time measured; the original keeps doing the work. */
  private static final class Timed extends RegisteredListener {
    final RegisteredListener inner;
    final HandlerList list;
    String event = "?";
    long nanosSecond, calls;
    double recentMs;

    Timed(RegisteredListener in, HandlerList list) {
      super(in.getListener(), (l, e) -> { }, in.getPriority(), in.getPlugin(), in.isIgnoringCancelled());
      this.inner = in;
      this.list = list;
    }

    @Override
    public void callEvent(Event e) throws EventException {
      if (!Bukkit.isPrimaryThread()) {
        inner.callEvent(e);
        return;
      }
      long t = System.nanoTime();
      try {
        inner.callEvent(e);
      } finally {
        long d = System.nanoTime() - t;
        nanosSecond += d;
        calls++;
        ownNanosTick += d;
        ownNanosSecond += d;
        if (event.equals("?")) event = e.getEventName();
      }
    }

    void roll() {
      recentMs = recentMs * 0.8 + nanosSecond / 1e6;
      nanosSecond = 0;
    }

    String label() { return inner.getListener().getClass().getSimpleName() + "/" + event; }
  }

  private static void wrapListeners() {
    if (plugin == null) return;
    for (HandlerList hl : new ArrayList<>(HandlerList.getHandlerLists())) {
      for (RegisteredListener rl : hl.getRegisteredListeners()) {
        if (rl.getPlugin() != plugin || rl instanceof Timed) continue;
        Timed t = new Timed(rl, hl);
        hl.unregister(rl);
        hl.register(t);
        TIMED.add(t);
      }
    }
  }

  // ------------------------------------------------------------------ pause / resume ----

  /** Pause the plugin's heavy features (never the server, never another plugin). */
  public static synchronized void pause(String reason, String detail) {
    if (paused || plugin == null) return;
    paused = true;
    pauseReason = reason;
    List<Timed> byCost = new ArrayList<>(TIMED);
    byCost.sort(Comparator.comparingDouble((Timed t) -> -t.recentMs));
    double total = 0;
    for (Timed t : byCost) total += t.recentMs;
    double acc = 0;
    List<String> names = new ArrayList<>();
    for (Timed t : byCost) {
      if (total <= 0 || t.recentMs <= 0) break;
      t.list.unregister(t);
      PAUSED_LISTENERS.add(t);
      names.add(t.label());
      acc += t.recentMs;
      if (acc >= total * 0.9) break;
    }
    for (Timer t : TIMERS) t.stop();
    for (Queue<?> q : QUEUES) q.clear();
    for (Runnable r : ON_PAUSE) {
      try { r.run(); } catch (RuntimeException e) { plugin.getLogger().warning("[NxPerf] a pause hook failed: " + e); }
    }
    String line = "[NxPerf] PAUSED plugin=" + plugin.getName() + " reason=" + reason + " tps=" + NxPerfCore.fmt(lastTps) + " own_ms=" + NxPerfCore.fmt(lastOwnMs)
        + " listeners=" + (names.isEmpty() ? "none" : String.join(",", names)) + " timers=" + TIMERS.size() + " detail=" + detail;
    plugin.getLogger().warning(line);
    tellOps("Performance safety paused this mod's heavy features (" + detail + "). The server keeps running. Check with /" + label() + " perf status, resume with /" + label() + " perf resume.");
  }

  public static synchronized void resume(String by) {
    if (!paused || plugin == null) return;
    for (Timed t : PAUSED_LISTENERS) t.list.register(t);
    PAUSED_LISTENERS.clear();
    for (Timer t : TIMERS) t.start();
    for (Runnable r : ON_RESUME) {
      try { r.run(); } catch (RuntimeException e) { plugin.getLogger().warning("[NxPerf] a resume hook failed: " + e); }
    }
    paused = false;
    pauseReason = null;
    JUDGE.reset();
    plugin.getLogger().warning("[NxPerf] RESUMED plugin=" + plugin.getName() + " by=" + by);
  }

  private static void tellOps(String text) {
    Component m = Component.text("[" + plugin.getName() + "] " + text, NamedTextColor.GOLD);
    String perm = plugin.getName().toLowerCase(Locale.ROOT) + ".perf";
    for (Player p : Bukkit.getOnlinePlayers()) if (p.isOp() || p.hasPermission(perm)) p.sendMessage(m);
  }

  // ------------------------------------------------------------------ API for the plugin ----

  /** false while the heavy features are paused: check it before starting heavy work. */
  public static boolean active() { return !paused; }

  public static boolean paused() { return paused; }

  /** Take n work units from this tick's budget `name` (perf.max-work-per-tick). false = stop for this tick. */
  public static boolean take(String name, int n) {
    if (paused) return false;
    NxPerfCore.Budget b = BUDGETS.computeIfAbsent(name, k -> new NxPerfCore.Budget(k, S.maxWorkPerTick));
    return b.take(Bukkit.getCurrentTick(), n);
  }

  public static boolean take(String name) { return take(name, 1); }

  /** Work units left this tick for budget `name`. */
  public static int remaining(String name) {
    NxPerfCore.Budget b = BUDGETS.computeIfAbsent(name, k -> new NxPerfCore.Budget(k, S.maxWorkPerTick));
    return paused ? 0 : b.remaining(Bukkit.getCurrentTick());
  }

  /** May the plugin spawn one more entity for `name` now? perf.max-entities-per-second and perf.max-entities-per-chunk. */
  public static boolean spawnAllowed(String name, Chunk chunk) {
    if (paused) return false;
    if (chunk != null) {
      int living = 0;
      for (Entity e : chunk.getEntities()) if (e instanceof LivingEntity && !(e instanceof Player)) living++;
      if (living >= S.maxEntitiesPerChunk) return false;
    }
    NxPerfCore.Rate r = RATES.computeIfAbsent("spawn:" + name, k -> new NxPerfCore.Rate(S.maxEntitiesPerSecond));
    return r.take(System.nanoTime());
  }

  /** A per-second rate limit (e.g. explosions, effects). */
  public static boolean rate(String name, double perSecond) {
    if (paused) return false;
    return RATES.computeIfAbsent("rate:" + name, k -> new NxPerfCore.Rate(perSecond)).take(System.nanoTime());
  }

  /** Recursion guard: false when `key` is already running on this call stack (e.g. a change made by this plugin's own handler). */
  public static boolean enter(String key) {
    int d = DEPTH.getOrDefault(key, 0);
    if (d > 0) return false;
    DEPTH.put(key, d + 1);
    return true;
  }

  public static void exit(String key) {
    int d = DEPTH.getOrDefault(key, 0);
    if (d <= 1) DEPTH.remove(key); else DEPTH.put(key, d - 1);
  }

  /** A radius clamped to 1..perf.max-radius blocks. */
  public static int radius(int wanted) { return NxPerfCore.clampInt(wanted, 1, S.maxRadius); }

  /** perf.max-work-per-tick. */
  public static int perTick() { return S.maxWorkPerTick; }

  /** perf.max-queue. */
  public static int maxQueue() { return S.maxQueue; }

  public static void onPause(Runnable r) { ON_PAUSE.add(r); }

  public static void onResume(Runnable r) { ON_RESUME.add(r); }

  /** A bounded work queue drained every tick within the budget `name`. offer() is false when full or paused. */
  public static <T> Queue<T> queue(String name, Consumer<T> worker) {
    Queue<T> q = new Queue<>(name, worker);
    QUEUES.add(q);
    return q;
  }

  public static final class Queue<T> {
    private final String name;
    private final Consumer<T> worker;
    private final ArrayDeque<T> items = new ArrayDeque<>();
    private long dropped;
    private boolean warned;

    Queue(String name, Consumer<T> worker) {
      this.name = name;
      this.worker = worker;
    }

    public boolean offer(T item) {
      if (paused || items.size() >= S.maxQueue) {
        dropped++;
        if (!warned && !paused) {
          warned = true;
          plugin.getLogger().warning("[NxPerf] queue " + name + " is full (" + S.maxQueue + "); extra work is dropped");
        }
        return false;
      }
      items.add(item);
      return true;
    }

    public int size() { return items.size(); }

    public long dropped() { return dropped; }

    void clear() { dropped += items.size(); items.clear(); }

    void drain() {
      if (paused || items.isEmpty()) return;
      long t = System.nanoTime();
      while (!items.isEmpty() && take(name, 1)) {
        T x = items.poll();
        try {
          worker.accept(x);
        } catch (RuntimeException e) {
          plugin.getLogger().warning("[NxPerf] queue " + name + " task failed: " + e);
        }
      }
      long d = System.nanoTime() - t;
      ownNanosTick += d;
      ownNanosSecond += d;
    }
  }

  /** A repeating task that is measured and paused with the heavy features. period is clamped to at least 1 tick. */
  public static Timer timer(String name, long delayTicks, long periodTicks, Runnable work) {
    Timer t = new Timer(name, Math.max(0, delayTicks), Math.max(1, periodTicks), work);
    TIMERS.add(t);
    if (!paused) t.start();
    return t;
  }

  public static final class Timer {
    private final String name;
    private final long delay, period;
    private final Runnable work;
    private BukkitTask task;

    Timer(String name, long delay, long period, Runnable work) {
      this.name = name;
      this.delay = delay;
      this.period = period;
      this.work = work;
    }

    void start() {
      if (task != null || plugin == null) return;
      task = Bukkit.getScheduler().runTaskTimer(plugin, () -> {
        if (paused) return;
        long t = System.nanoTime();
        try {
          work.run();
        } finally {
          long d = System.nanoTime() - t;
          ownNanosTick += d;
          ownNanosSecond += d;
        }
      }, delay, period);
    }

    void stop() {
      if (task != null) task.cancel();
      task = null;
    }

    public void cancel() {
      stop();
      TIMERS.remove(this);
    }

    public String name() { return name; }
  }

  // ------------------------------------------------------------------ command ----

  private static String label() {
    return commandLabel != null ? commandLabel : plugin.getName().toLowerCase(Locale.ROOT) + "perf";
  }

  private static void hookCommand() {
    if (plugin == null) return;
    PluginCommand own = null;
    String want = plugin.getName().toLowerCase(Locale.ROOT);
    for (Map.Entry<String, Command> e : Bukkit.getCommandMap().getKnownCommands().entrySet()) {
      if (!(e.getValue() instanceof PluginCommand pc) || pc.getPlugin() != plugin || e.getKey().contains(":")) continue;
      if (own == null || pc.getName().equals(want) || (!own.getName().equals(want) && pc.getName().compareTo(own.getName()) < 0)) own = pc;
    }
    if (own != null) {
      final CommandExecutor inner = own.getExecutor();
      own.setExecutor((sender, cmd, lbl, args) -> {
        if (args.length > 0 && args[0].equalsIgnoreCase("perf")) return perfCommand(sender, args);
        return inner.onCommand(sender, cmd, lbl, args);
      });
      commandLabel = own.getName();
      return;
    }
    String name = want + "perf";
    Bukkit.getCommandMap().register(want, new Command(name, "Performance safety status for " + plugin.getName(), "/" + name + " [status|pause|resume]", new ArrayList<>()) {
      @Override
      public boolean execute(CommandSender sender, String lbl, String[] args) {
        String[] a = new String[args.length + 1];
        a[0] = "perf";
        System.arraycopy(args, 0, a, 1, args.length);
        return perfCommand(sender, a);
      }
    });
    commandLabel = name;
  }

  private static boolean perfCommand(CommandSender sender, String[] args) {
    String perm = plugin.getName().toLowerCase(Locale.ROOT) + ".perf";
    if (!(sender instanceof ConsoleCommandSender) && !sender.isOp() && !sender.hasPermission(perm)) {
      sender.sendMessage(Component.text("You need " + perm + " (or operator) for this.", NamedTextColor.RED));
      return true;
    }
    String sub = args.length > 1 ? args[1].toLowerCase(Locale.ROOT) : "status";
    switch (sub) {
      case "pause", "off" -> {
        pause("manual", "paused by " + sender.getName());
        sender.sendMessage(Component.text("Heavy features paused.", NamedTextColor.YELLOW));
      }
      case "resume", "on" -> {
        resume(sender.getName());
        sender.sendMessage(Component.text("Heavy features resumed.", NamedTextColor.GREEN));
      }
      default -> {
        sender.sendMessage(Component.text("NxPerf " + plugin.getName() + ": TPS " + NxPerfCore.fmt(lastTps) + " (Paper " + NxPerfCore.fmt(paperTps()) + "), MSPT "
            + NxPerfCore.fmt(paperMspt()) + ", this plugin " + NxPerfCore.fmt(lastOwnMs) + " ms/tick, " + (paused ? "PAUSED (" + pauseReason + ")" : "running"), NamedTextColor.AQUA));
        List<Timed> byCost = new ArrayList<>(TIMED);
        byCost.sort(Comparator.comparingDouble((Timed t) -> -t.recentMs));
        for (int i = 0; i < Math.min(3, byCost.size()); i++) {
          Timed t = byCost.get(i);
          sender.sendMessage(Component.text("  " + t.label() + ": " + NxPerfCore.fmt(t.recentMs / 5.0) + " ms/s, " + t.calls + " calls", NamedTextColor.GRAY));
        }
        for (NxPerfCore.Budget b : BUDGETS.values()) sender.sendMessage(Component.text("  budget " + b.name + ": " + b.perTick() + "/tick, denied " + b.denied(), NamedTextColor.GRAY));
        sender.sendMessage(Component.text("  floor " + NxPerfCore.fmt(S.tpsFloor) + " TPS for " + S.windowSeconds + " s, auto-disable " + S.autoDisable
            + ", max work/tick " + S.maxWorkPerTick + ". /" + label() + " perf pause|resume", NamedTextColor.GRAY));
      }
    }
    return true;
  }
}

