// Cyrus perf safety (2): watchdog injection, PERF pre-check and prompt rules of the build service (services/modbuilder/perf.js).
// Real javac on all four buildable versions + the NxPerfCore unit test + the strict scan run in test/cyrus-perf-real.ts (node-2).
import { describe, it } from "node:test";
import assert from "node:assert/strict";
import { mkdtempSync, mkdirSync, readFileSync, writeFileSync, existsSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import path from "node:path";

// eslint-disable-next-line @typescript-eslint/no-require-imports
const PERF = require("../services/modbuilder/perf.js");
const MB = path.join(__dirname, "..", "services", "modbuilder");

function ws(main: string, extra: Record<string, string> = {}): string {
  const d = mkdtempSync(path.join(tmpdir(), "perf-ws-"));
  const put = (rel: string, s: string) => { mkdirSync(path.dirname(path.join(d, rel)), { recursive: true }); writeFileSync(path.join(d, rel), s); };
  put("src/main/resources/plugin.yml", "name: Demo\nversion: 1.0.0\nmain: dev.nxeon.plugins.demo.Demo\napi-version: '1.21.11'\n");
  put("src/main/java/dev/nxeon/plugins/demo/Demo.java", main);
  for (const [k, v] of Object.entries(extra)) put(k, v);
  return d;
}
const MAIN = "package dev.nxeon.plugins.demo;\nimport org.bukkit.plugin.java.JavaPlugin;\npublic class Demo extends JavaPlugin {\n  @Override\n  public void onEnable() {\n    saveDefaultConfig();\n  }\n}\n";

describe("watchdog injection", () => {
  it("places the audited sources in <main package>.nxperf, patches onEnable once, appends perf: to config.yml", () => {
    const d = ws(MAIN, { "src/main/resources/config.yml": "mirror:\n  radius-chunks: 2\n", "src/main/java/dev/nxeon/plugins/demo/Use.java": "package dev.nxeon.plugins.demo;\nimport dev.nxeon.cyrus.perf.NxPerf;\nclass Use {}\n" });
    try {
      const rec: Record<string, unknown> = {};
      const r = PERF.inject(d, rec, {});
      assert.deepEqual(r, { injected: true, version: "nxperf-1", pkg: "dev.nxeon.plugins.demo.nxperf", mainPatched: true, configSection: true });
      assert.deepEqual(rec.perf, r);
      const dir = path.join(d, "src/main/java/dev/nxeon/plugins/demo/nxperf");
      for (const f of ["NxPerf.java", "NxPerfCore.java"]) {
        const s = readFileSync(path.join(dir, f), "utf8");
        assert.match(s, /^package dev\.nxeon\.plugins\.demo\.nxperf;/);
        assert.ok(!s.includes("@PKG@"));
      }
      const main = readFileSync(path.join(d, "src/main/java/dev/nxeon/plugins/demo/Demo.java"), "utf8");
      assert.match(main, /public void onEnable\(\) \{\n {4}dev\.nxeon\.plugins\.demo\.nxperf\.NxPerf\.init\(this\);/);
      assert.match(readFileSync(path.join(d, "src/main/java/dev/nxeon/plugins/demo/Use.java"), "utf8"), /import dev\.nxeon\.plugins\.demo\.nxperf\.NxPerf;/);
      const cfg = readFileSync(path.join(d, "src/main/resources/config.yml"), "utf8");
      assert.match(cfg, /^perf:\n {2}auto-disable: true\n {2}tps-floor: 15\.0/m);
      // idempotent: a second round (repair) changes nothing but re-writes the watchdog
      writeFileSync(path.join(dir, "NxPerf.java"), "tampered by the model");
      const r2 = PERF.inject(d, {}, {});
      assert.equal(r2.mainPatched, false);
      assert.equal(r2.configSection, false);
      assert.equal(readFileSync(path.join(d, "src/main/java/dev/nxeon/plugins/demo/Demo.java"), "utf8").match(/NxPerf\.init/g)!.length, 1);
      assert.match(readFileSync(path.join(dir, "NxPerf.java"), "utf8"), /^package /, "a tampered watchdog is overwritten");
      assert.equal(readFileSync(path.join(d, "src/main/resources/config.yml"), "utf8").match(/^perf:/gm)!.length, 1);
    } finally { rmSync(d, { recursive: true, force: true }); }
  });
  it("adds an onEnable when the main class has none", () => {
    const d = ws("package dev.nxeon.plugins.demo;\nimport org.bukkit.plugin.java.JavaPlugin;\npublic class Demo extends JavaPlugin {\n}\n");
    try {
      assert.equal(PERF.inject(d, {}, {}).mainPatched, true);
      assert.match(readFileSync(path.join(d, "src/main/java/dev/nxeon/plugins/demo/Demo.java"), "utf8"), /@Override\n {2}public void onEnable\(\) \{\n {4}dev\.nxeon\.plugins\.demo\.nxperf\.NxPerf\.init\(this\);/);
    } finally { rmSync(d, { recursive: true, force: true }); }
  });
  it("leaves imported plugins alone, obeys MB_PERF_SAFETY=0, survives a broken workspace", () => {
    const d = ws(MAIN);
    try {
      assert.equal(PERF.inject(d, { imported: true }, {}).injected, false);
      assert.equal(PERF.inject(d, {}, { MB_PERF_SAFETY: "0" }).injected, false);
      assert.equal(existsSync(path.join(d, "src/main/java/dev/nxeon/plugins/demo/nxperf")), false);
      rmSync(path.join(d, "src/main/resources/plugin.yml"));
      assert.equal(PERF.inject(d, {}, {}).injected, false);
    } finally { rmSync(d, { recursive: true, force: true }); }
  });
  it("the watchdog source uses nothing the strict scan blocks or warns about", () => {
    const src = ["NxPerf.java", "NxPerfCore.java"].map((f) => readFileSync(path.join(MB, "perf", "src", f), "utf8")).join("\n");
    for (const bad of [/java\.lang\.reflect|getDeclared|Class\.forName|MethodHandle/, /new Thread|Executors|ForkJoin|addShutdownHook/, /disablePlugin|enablePlugin|loadPlugin/, /dispatchCommand|setOp\(|addAttachment/, /System\.exit|Runtime\.getRuntime|ProcessBuilder/, /java\.net|java\.io\.File|java\.nio/, /net\.minecraft|craftbukkit/, /Base64|getenv/])
      assert.ok(!bad.test(src), `watchdog source matches ${bad}`);
  });
});

const UNBOUNDED = `package dev.nxeon.plugins.demo;
import org.bukkit.*; import org.bukkit.event.*; import org.bukkit.event.block.*; import org.bukkit.event.entity.*;
public class Mirror implements Listener {
  @EventHandler public void onPlace(BlockPlaceEvent e) {
    for (Chunk c : e.getBlock().getWorld().getLoadedChunks()) {
      c.getBlock(e.getBlock().getX() & 15, e.getBlock().getY(), e.getBlock().getZ() & 15).setType(e.getBlock().getType());
    }
  }
  @EventHandler public void onSpawn(CreatureSpawnEvent e) {
    for (Chunk c : e.getLocation().getWorld().getLoadedChunks()) {
      c.getWorld().spawnEntity(c.getBlock(8, 64, 8).getLocation(), e.getEntityType());
    }
  }
  void start(org.bukkit.plugin.Plugin p) { Bukkit.getScheduler().runTaskTimer(p, () -> {}, 1L, 1L); }
}`;
const BOUNDED = `package dev.nxeon.plugins.demo;
import org.bukkit.*; import org.bukkit.event.*; import org.bukkit.event.block.*;
import dev.nxeon.plugins.demo.nxperf.NxPerf;
public class Mirror implements Listener {
  private final NxPerf.Queue<Runnable> q = NxPerf.queue("mirror", Runnable::run);
  @EventHandler public void onPlace(BlockPlaceEvent e) {
    if (!NxPerf.enter("mirror")) return;
    try {
      int r = NxPerf.radius(2);
      for (int dx = -r; dx <= r; dx++) for (int dz = -r; dz <= r; dz++) {
        final int x = dx, z = dz;
        q.offer(() -> e.getBlock().getRelative(x * 16, 0, z * 16).setType(Material.STONE));
      }
    } finally { NxPerf.exit("mirror"); }
  }
  void start() { NxPerf.timer("tick", 20L, 20L, () -> {}); }
}`;

describe("PERF pre-check", () => {
  const run = (src: string) => {
    const d = mkdtempSync(path.join(tmpdir(), "perf-pc-"));
    try { writeFileSync(path.join(d, "Mirror.java"), src); return PERF.perfcheck([{ rel: "src/main/java/dev/nxeon/plugins/demo/Mirror.java", abs: path.join(d, "Mirror.java") }], {}); }
    finally { rmSync(d, { recursive: true, force: true }); }
  };
  it("flags the ChunkMirror shape (world iteration, block changes and spawns in loops, raw timer)", () => {
    const ids = run(UNBOUNDED).map((h: { rule: string }) => h.rule).sort();
    assert.deepEqual(ids, ["perf-block-loop", "perf-raw-timer", "perf-spawn-in-loop", "perf-world-iteration"]);
    for (const h of run(UNBOUNDED)) assert.match(h.where, /^src\/main\/java\/.*Mirror\.java:\d+$/);
  });
  it("the bounded version passes", () => assert.deepEqual(run(BOUNDED), []));
  it("is off with MB_PERF_SAFETY=0 and skips the watchdog's own files", () => {
    const d = mkdtempSync(path.join(tmpdir(), "perf-pc-"));
    try {
      writeFileSync(path.join(d, "M.java"), UNBOUNDED);
      assert.deepEqual(PERF.perfcheck([{ rel: "x/M.java", abs: path.join(d, "M.java") }], { MB_PERF_SAFETY: "0" }), []);
      assert.deepEqual(PERF.perfcheck([{ rel: "src/main/java/a/nxperf/NxPerf.java", abs: path.join(d, "M.java") }], {}), []);
    } finally { rmSync(d, { recursive: true, force: true }); }
  });
  it("config.yml: per-tick above 256, huge radius, mob copying on", () => {
    const d = ws(MAIN, { "src/main/resources/config.yml": "chunks-per-tick: 500\nmirror-mobs: true\nscan-radius: 300\nteleport-radius: 5000\nperf:\n  max-work-per-tick: 64\n" });
    try { assert.deepEqual(PERF.configCheck(d, {}).map((h: { rule: string }) => h.rule), ["perf-config-per-tick", "perf-config-mob-copy", "perf-config-radius"]); }
    finally { rmSync(d, { recursive: true, force: true }); }
  });
});

describe("prompt rules", () => {
  it("every generated build's system prompt carries rule 10 + the NxPerf API; imported builds and MB_PERF_SAFETY=0 do not", () => {
    // eslint-disable-next-line @typescript-eslint/no-require-imports
    const P = require("../services/modbuilder/prompts.js");
    const prev = process.env.MB_PERF_SAFETY;
    try {
      delete process.env.MB_PERF_SAFETY;
      const s = P.systemPrompt("1.21.11");
      assert.ok(s.endsWith(P.PERF_SECTION));
      assert.match(s, /10\. Every piece of work must be BOUNDED/);
      assert.match(s, /NxPerf\.queue\("<feature>"/);
      assert.match(P.knowledgeVersion(), /\+nxperf-1$/);
      assert.ok(!P.systemPrompt("1.21.11", { imported: { deps: [] } }).includes(P.PERF_SECTION));
      process.env.MB_PERF_SAFETY = "0";
      assert.ok(!P.systemPrompt("1.21.11").includes("PERFORMANCE (hard rule 10"));
    } finally { if (prev === undefined) delete process.env.MB_PERF_SAFETY; else process.env.MB_PERF_SAFETY = prev; }
  });
  it("the reviewed failure rules carry the ChunkMirror lesson", () => {
    const r = JSON.parse(readFileSync(path.join(MB, "rules", "failure-rules.json"), "utf8"));
    const rule = r.rules.find((x: { id: string }) => x.id === "perf-unbounded-fanout");
    assert.ok(rule && /every chunk/.test(rule.rule) && rule.source[0].startsWith("mb7e414f0c2f713557d266"));
  });
});

