package dev.nxeon.tf.chunkmirror;

import dev.nxeon.tf.chunkmirror.nxperf.NxPerf;
import java.util.ArrayDeque;
import java.util.HashMap;
import java.util.Map;
import org.bukkit.Chunk;
import org.bukkit.Material;
import org.bukkit.World;
import org.bukkit.command.Command;
import org.bukkit.command.CommandSender;
import org.bukkit.entity.EntityType;
import org.bukkit.event.EventHandler;
import org.bukkit.event.Listener;
import org.bukkit.event.block.BlockBreakEvent;
import org.bukkit.event.block.BlockPlaceEvent;
import org.bukkit.event.entity.CreatureSpawnEvent;
import org.bukkit.event.world.ChunkLoadEvent;
import org.bukkit.plugin.java.JavaPlugin;

/**
 * POSITIVE control: the SAFE bounded ChunkMirror (what Cyrus builds by default for that request). Mirrors only into
 * loaded chunks within radius-chunks (max 4) of the change, through an NxPerf queue (per-tick budget), remembers at
 * most max-remembered changes per world keyed by chunk, never reacts to its own changes, mob copies capped by NxPerf.
 */
public class ChunkMirror extends JavaPlugin implements Listener {
  record Change(int x, int y, int z, Material type) {}
  record Job(World world, int cx, int cz, Change change) {}

  private final Map<Long, ArrayDeque<Change>> remembered = new HashMap<>();
  private int rememberedCount;
  private NxPerf.Queue<Job> queue;
  private boolean on = true;
  private int radius, maxRemembered;
  private boolean mobs;
  private long mirroredBlocks, mirroredMobs, skippedMobs;

  @Override
  public void onEnable() {
    saveDefaultConfig();
    // chunks-per-tick from config is clamped by the NxPerf budget (perf.max-work-per-tick, at most 256)
    radius = Math.min(4, Math.max(0, getConfig().getInt("radius-chunks", 2)));
    maxRemembered = Math.min(5000, Math.max(0, getConfig().getInt("max-remembered", 2000)));
    mobs = getConfig().getBoolean("mirror-mobs", false);
    queue = NxPerf.queue("mirror", this::apply);
    NxPerf.onPause(() -> { remembered.clear(); rememberedCount = 0; });
    getServer().getPluginManager().registerEvents(this, this);
  }

  private static long key(int cx, int cz) { return ((long) cx << 32) ^ (cz & 0xffffffffL); }

  private void apply(Job j) {
    if (!j.world().isChunkLoaded(j.cx(), j.cz())) return;
    if (!NxPerf.enter("mirror")) return;
    try { j.world().getChunkAt(j.cx(), j.cz()).getBlock(j.change().x(), j.change().y(), j.change().z()).setType(j.change().type(), false); mirroredBlocks++; }
    finally { NxPerf.exit("mirror"); }
  }

  private void mirror(World w, int ox, int oz, Change ch) {
    for (int dx = -radius; dx <= radius; dx++) for (int dz = -radius; dz <= radius; dz++) {
      int cx = ox + dx, cz = oz + dz;
      if ((dx != 0 || dz != 0) && w.isChunkLoaded(cx, cz)) queue.offer(new Job(w, cx, cz, ch));
      if (rememberedCount < maxRemembered) { remembered.computeIfAbsent(key(cx, cz), k -> new ArrayDeque<>()).add(ch); rememberedCount++; }
    }
  }

  @EventHandler
  public void onPlace(BlockPlaceEvent e) {
    if (!on || !NxPerf.active() || !NxPerf.enter("mirror")) return;
    try { var b = e.getBlockPlaced(); mirror(b.getWorld(), b.getX() >> 4, b.getZ() >> 4, new Change(b.getX() & 15, b.getY(), b.getZ() & 15, b.getType())); }
    finally { NxPerf.exit("mirror"); }
  }

  @EventHandler
  public void onBreak(BlockBreakEvent e) {
    if (!on || !NxPerf.active() || !NxPerf.enter("mirror")) return;
    try { var b = e.getBlock(); mirror(b.getWorld(), b.getX() >> 4, b.getZ() >> 4, new Change(b.getX() & 15, b.getY(), b.getZ() & 15, Material.AIR)); }
    finally { NxPerf.exit("mirror"); }
  }

  @EventHandler
  public void onSpawn(CreatureSpawnEvent e) {
    if (!on || !mobs || !NxPerf.active() || !NxPerf.enter("mirror-mob")) return;
    try {
      EntityType t = e.getEntityType();
      World w = e.getLocation().getWorld();
      int ox = e.getLocation().getBlockX() >> 4, oz = e.getLocation().getBlockZ() >> 4;
      for (int dx = -radius; dx <= radius; dx++) for (int dz = -radius; dz <= radius; dz++) {
        if ((dx == 0 && dz == 0) || !w.isChunkLoaded(ox + dx, oz + dz)) continue;
        Chunk c = w.getChunkAt(ox + dx, oz + dz);
        if (!NxPerf.spawnAllowed("mirror", c)) { skippedMobs++; continue; }
        w.spawnEntity(c.getBlock(8, e.getLocation().getBlockY(), 8).getLocation().add(0.5, 0, 0.5), t);
        mirroredMobs++;
      }
    } finally { NxPerf.exit("mirror-mob"); }
  }

  @EventHandler
  public void onChunkLoad(ChunkLoadEvent e) {
    if (!on || !NxPerf.active()) return;
    ArrayDeque<Change> mine = remembered.get(key(e.getChunk().getX(), e.getChunk().getZ()));
    if (mine == null) return;
    for (Change ch : mine) if (!queue.offer(new Job(e.getWorld(), e.getChunk().getX(), e.getChunk().getZ(), ch))) break;
  }

  @Override
  public boolean onCommand(CommandSender s, Command cmd, String label, String[] args) {
    if (args.length > 0 && args[0].equalsIgnoreCase("off")) { on = false; s.sendMessage("ChunkMirror off"); return true; }
    s.sendMessage("ChunkMirror on=" + on + " remembered=" + rememberedCount + " queued=" + queue.size() + " mirroredBlocks=" + mirroredBlocks + " mirroredMobs=" + mirroredMobs + " skippedMobs=" + skippedMobs);
    return true;
  }
}
