    } finally { mirroring = false; }
  }

  @EventHandler
  public void onChunkLoad(ChunkLoadEvent e) {
    if (!on) return;
    for (Change ch : remembered) queue.add(new Job(e.getWorld(), e.getChunk().getX(), e.getChunk().getZ(), ch));
  }

  @Override
  public boolean onCommand(CommandSender s, Command cmd, String label, String[] args) {
    if (args.length > 0 && args[0].equalsIgnoreCase("off")) { on = false; queue.clear(); s.sendMessage("ChunkMirror off"); return true; }
    s.sendMessage("ChunkMirror on=" + on + " remembered=" + remembered.size() + " queued=" + queue.size() + " mirroredBlocks=" + mirroredBlocks + " mirroredMobs=" + mirroredMobs);
    return true;
  }
}
