const JDK = `${TF}/jdk/21`;
const RUN = `${T}/cyrus-perf/run-${Date.now().toString(36)}`;
const VERSIONS = ["1.21.1", "1.21.4", "1.21.8", "1.21.11"];
const FIX = path.join(ROOT, "services/modbuilder/tools/testflight/fixtures");
process.env.PATH = `${JDK}/bin:${process.env.PATH}`;
// eslint-disable-next-line @typescript-eslint/no-require-imports
const PERF = require("../services/modbuilder/perf.js");
// eslint-disable-next-line @typescript-eslint/no-require-imports
const SCAN = require("../services/modbuilder/scan.js");

const arg = (k: string) => { const i = process.argv.indexOf(k); return i > 0 ? process.argv[i + 1] : undefined; };
const sha = (b: Buffer | string) => createHash("sha256").update(b).digest("hex");
const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));
function walk(dir: string, out: string[] = []): string[] {
  for (const e of readdirSync(dir, { withFileTypes: true })) { const p = path.join(dir, e.name); if (e.isDirectory()) walk(p, out); else out.push(p); }
  return out;
}

const DEMO_MAIN = `package dev.nxeon.plugins.perfdemo;
import dev.nxeon.plugins.perfdemo.nxperf.NxPerf;
import org.bukkit.command.Command;
import org.bukkit.command.CommandSender;
import org.bukkit.entity.EntityType;
import org.bukkit.event.EventHandler;
import org.bukkit.event.Listener;
import org.bukkit.event.block.BlockPlaceEvent;
import org.bukkit.plugin.java.JavaPlugin;
public class PerfDemo extends JavaPlugin implements Listener {
  private NxPerf.Queue<Runnable> queue;
  @Override
  public void onEnable() {
    saveDefaultConfig();
    queue = NxPerf.queue("work", Runnable::run);
    NxPerf.timer("pulse", 20L, 20L, () -> { if (NxPerf.take("pulse", 4)) getLogger().fine("pulse " + NxPerf.remaining("pulse")); });
    NxPerf.onPause(() -> getLogger().info("paused"));
    NxPerf.onResume(() -> getLogger().info("resumed"));
    getServer().getPluginManager().registerEvents(this, this);
  }
  @EventHandler
  public void onPlace(BlockPlaceEvent e) {
    if (!NxPerf.active() || !NxPerf.enter("place")) return;
    try {
      int r = NxPerf.radius(getConfig().getInt("radius", 8));
      if (NxPerf.spawnAllowed("demo", e.getBlock().getChunk()) && NxPerf.rate("fx", 2)) e.getBlock().getWorld().spawnEntity(e.getBlock().getLocation().add(0.5, 1, 0.5), EntityType.CHICKEN);
      queue.offer(() -> getLogger().fine("queued " + r + " " + NxPerf.perTick() + " " + NxPerf.maxQueue()));
    } finally { NxPerf.exit("place"); }
  }
  @Override
  public boolean onCommand(CommandSender s, Command c, String l, String[] a) { s.sendMessage("perfdemo queued=" + queue.size() + " paused=" + NxPerf.paused()); return true; }
}
`;
const DEMO_YML = (api: string) => `name: PerfDemo\nversion: 1.0.0\nmain: dev.nxeon.plugins.perfdemo.PerfDemo\napi-version: '${api}'\ndescription: perf demo\nauthor: Nxeon Mod Builder\ncommands:\n  perfdemo:\n    description: demo\n    usage: /perfdemo\n    permission: perfdemo.use\npermissions:\n  perfdemo.use:\n    description: use\n    default: op\n`;

/** A build-service style workspace from a fixture dir (src/ + plugin.yml + config.yml), optionally with the watchdog injected. */
function fixtureWs(name: string, api: string, dest: string, watchdog: boolean): { ws: string; perf: unknown } {
  rmSync(dest, { recursive: true, force: true });
  const src = path.join(FIX, name);
  cpSync(path.join(src, "src"), path.join(dest, "src/main/java"), { recursive: true });
  mkdirSync(path.join(dest, "src/main/resources"), { recursive: true });
  writeFileSync(path.join(dest, "src/main/resources/plugin.yml"), readFileSync(path.join(src, "plugin.yml"), "utf8").replace("@API@", api));
  if (existsSync(path.join(src, "config.yml"))) cpSync(path.join(src, "config.yml"), path.join(dest, "src/main/resources/config.yml"));
  const perf = watchdog ? PERF.inject(dest, {}, {}) : { injected: false, reason: "negative control without the watchdog" };
  return { ws: dest, perf };
}

function compileWs(ws: string, version: string): { ok: boolean; jar?: string; sha256?: string; javacMs: number; warnings: string[]; errors?: string } {
  const classes = path.join(ws, "build/classes");
  rmSync(path.join(ws, "build"), { recursive: true, force: true });
  mkdirSync(classes, { recursive: true });
  const cp = readFileSync(`${TF}/classpath/${version}.txt`, "utf8").replace(/\n/g, "").trim();
  const sources = walk(path.join(ws, "src/main/java")).filter((f) => f.endsWith(".java")).sort();
  const t0 = Date.now();
  let out = "";
  try { out = execFileSync(`${JDK}/bin/javac`, ["-J-Xmx768m", "--release", "21", "-proc:none", "-encoding", "UTF-8", "-Xlint:deprecation,removal", "-cp", cp, "-d", classes, ...sources], { encoding: "utf8", stdio: ["ignore", "pipe", "pipe"] }); }
  catch (e) { const x = e as { stdout?: string; stderr?: string }; return { ok: false, javacMs: Date.now() - t0, warnings: [], errors: `${x.stderr ?? ""}${x.stdout ?? ""}`.split(ws + "/").join("").slice(0, 6000) }; }
  const javacMs = Date.now() - t0;
  for (const f of walk(path.join(ws, "src/main/resources"))) cpSync(f, path.join(classes, path.relative(path.join(ws, "src/main/resources"), f)));
  const entries = walk(classes).map((f) => path.relative(classes, f)).sort();
  const jar = path.join(ws, "build/plugin.jar");
  execFileSync(`${JDK}/bin/jar`, ["--create", "--file", jar, "--date", "2026-01-01T00:00:00Z", ...entries.flatMap((e) => ["-C", classes, e])]);
  return { ok: true, jar, sha256: sha(readFileSync(jar)), javacMs, warnings: (out.match(/warning: \[[^\]]+\][^\n]*/g) ?? []).slice(0, 10) };
}

function scanWs(ws: string) {
  const findings = [...SCAN.scanBytecode(path.join(ws, "build/classes")), ...SCAN.scanSource(walk(path.join(ws, "src/main/java")).filter((f) => f.endsWith(".java")).map((abs) => ({ abs, rel: path.relative(ws, abs) })))];
  return { block: findings.filter((f: { severity: string }) => f.severity === "block"), warn: findings.filter((f: { severity: string }) => f.severity === "warn") };
}

async function compileMatrix() {
  const results: Record<string, unknown>[] = [];
  for (const v of VERSIONS) {
    // 1) a generated-style plugin using the whole NxPerf API
    const ws = path.join(RUN, `demo-${v}`);
    rmSync(ws, { recursive: true, force: true });
    mkdirSync(path.join(ws, "src/main/java/dev/nxeon/plugins/perfdemo"), { recursive: true });
    mkdirSync(path.join(ws, "src/main/resources"), { recursive: true });
    writeFileSync(path.join(ws, "src/main/java/dev/nxeon/plugins/perfdemo/PerfDemo.java"), DEMO_MAIN);
    writeFileSync(path.join(ws, "src/main/resources/plugin.yml"), DEMO_YML(v));
    writeFileSync(path.join(ws, "src/main/resources/config.yml"), "radius: 8\n");
    const inj = PERF.inject(ws, {}, {});
    const c = compileWs(ws, v);
    const s = c.ok ? scanWs(ws) : null;
    const pc = PERF.perfcheck(walk(path.join(ws, "src/main/java")).filter((f) => f.endsWith(".java")).map((abs) => ({ abs, rel: path.relative(ws, abs) })), {});
    results.push({ version: v, plugin: "PerfDemo (whole NxPerf API)", injected: inj, compiled: c.ok, javacMs: c.javacMs, warnings: c.warnings, errors: c.errors, jarSha256: c.sha256, scanBlocks: s?.block ?? null, scanWarns: s?.warn ?? null, perfcheckHits: pc });
    // 2) the bounded ChunkMirror fixture with the watchdog
    const f = fixtureWs("chunkmirror-bounded", v, path.join(RUN, `cm-bounded-${v}`), true);
    const fc = compileWs(f.ws, v);
    const fs2 = fc.ok ? scanWs(f.ws) : null;
    results.push({ version: v, plugin: "ChunkMirror bounded fixture", injected: f.perf, compiled: fc.ok, javacMs: fc.javacMs, warnings: fc.warnings, errors: fc.errors, jarSha256: fc.sha256, scanBlocks: fs2?.block ?? null, scanWarns: fs2?.warn ?? null });
    console.log(`${v}: demo ${c.ok ? "compiled" : "FAILED"} (${c.javacMs} ms, ${c.warnings.length} warnings, scan ${s ? `${s.block.length} block / ${s.warn.length} warn` : "-"}), bounded fixture ${fc.ok ? "compiled" : "FAILED"}`);
    if (!c.ok) console.log(c.errors);
    if (!fc.ok) console.log(fc.errors);
  }
  // 3) the pure core's unit test on the real JVM
  const ut = path.join(RUN, "core-test");
  rmSync(ut, { recursive: true, force: true });
  mkdirSync(path.join(ut, "src"), { recursive: true });
  const pkg = "dev.nxeon.perftest";
  for (const [f, from] of [["NxPerfCore.java", "perf/src/NxPerfCore.java"], ["NxPerfCoreTest.java", "perf/test/NxPerfCoreTest.java"]]) writeFileSync(path.join(ut, "src", f), readFileSync(path.join(ROOT, "services/modbuilder", from), "utf8").replace(/@PKG@/g, pkg));
  execFileSync(`${JDK}/bin/javac`, ["--release", "21", "-d", path.join(ut, "classes"), path.join(ut, "src/NxPerfCore.java"), path.join(ut, "src/NxPerfCoreTest.java")]);
  let unit = { exit: 0, out: "" };
  try { unit.out = execFileSync(`${JDK}/bin/java`, ["-cp", path.join(ut, "classes"), `${pkg}.NxPerfCoreTest`], { encoding: "utf8" }); }
  catch (e) { const x = e as { status?: number; stdout?: string }; unit = { exit: x.status ?? 1, out: x.stdout ?? "" }; }
  console.log(unit.out.trim());
  return { at: new Date().toISOString(), host: "node-2", jdk: execFileSync(`${JDK}/bin/java`, ["-version"], { encoding: "utf8", stdio: ["ignore", "pipe", "pipe"] }).toString() || null, results, unit };
}

// ------------------------------------------------------------------ stress flights ----
const localRemote: Remote = {
  exec: (command, opts = {}) => new Promise((resolve) => {
    const child = spawn("bash", ["-c", command], { stdio: ["pipe", "pipe", "pipe"] });
    let stdout = "", stderr = "";
    child.stdout.on("data", (d) => (stdout += d)); child.stderr.on("data", (d) => (stderr += d));
    const t = setTimeout(() => child.kill("SIGKILL"), opts.timeoutMs ?? 120000);
    child.on("close", (code) => { clearTimeout(t); resolve({ code, stdout, stderr }); });
    child.stdin.on("error", () => {}); child.stdin.end(opts.input ?? undefined);
  }),
};
async function fly(spec: TestFlightSpec, label: string) {
  for (let attempt = 1, wait = 15000; attempt <= 16; attempt++, wait = Math.min(wait * 2, 120000)) {
    const r = await runTestFlight(spec, { remote: localRemote });
    if (r.report.status !== "busy") return r;
    console.log(`${label}: node-2 busy (another flight), retry ${attempt} in ${wait / 1000}s`);
    await sleep(wait);
  }
  throw new Error(`${label}: node-2 stayed busy`);
}

export const FLIGHTS = [
  { name: "unbounded-1.21.11", fixture: "chunkmirror-unbounded", version: "1.21.11", watchdog: false, expect: "fail" },
  { name: "bounded-1.21.11", fixture: "chunkmirror-bounded", version: "1.21.11", watchdog: true, expect: "pass" },
  { name: "unbounded+watchdog-1.21.11", fixture: "chunkmirror-unbounded", version: "1.21.11", watchdog: true, expect: "observe" },
  { name: "bounded-1.21.4", fixture: "chunkmirror-bounded", version: "1.21.4", watchdog: true, expect: "pass" },
] as const;

async function flights() {
  const { stressSpecFor } = await import("../lib/cyrus/testflight/stress");
  const out: Record<string, unknown>[] = [];
  for (const f of FLIGHTS) {
    if (arg("--only") && arg("--only") !== f.name) continue;
    const w = fixtureWs(f.fixture, f.version, path.join(RUN, f.name), f.watchdog);
    const c = compileWs(w.ws, f.version);
    if (!c.ok) { out.push({ name: f.name, compiled: false, errors: c.errors }); continue; }
    const stress = stressSpecFor({ version: f.version, commands: ["chunkmirror"] });
    const spec: TestFlightSpec = {
      version: f.version, plugins: [{ localPath: c.jar!, sha256: c.sha256 }],
      rcon: [{ id: "plugins", command: "plugins", expect: ["ChunkMirror"] }, { id: "status-before", command: "chunkmirror status", required: false }],
      stress, timeouts: { bootSec: 180, totalSec: 600 },
    };
    const t0 = Date.now();
    const r = await fly(spec, f.name);
    const rep = r.report as unknown as { stress?: unknown; checks: { id: string; status: string; evidence: string[] }[] };
    const st = rep.checks.find((x) => x.id === "stress");
    out.push({ name: f.name, fixture: f.fixture, version: f.version, watchdog: f.watchdog, injected: w.perf, expect: f.expect, jarSha256: c.sha256, wallMs: Date.now() - t0,
      overall: r.summary.overall, reasons: r.summary.reasons, stressCheck: st ? { status: st.status, evidence: st.evidence.slice(0, 14) } : null, stress: rep.stress ?? null, peakRssKb: r.report.peakRssKb, runId: r.report.runId, engine: r.report.engine ? { runner: r.report.engine.runner, paper: r.report.engine.paper.build } : null, notes: r.report.notes.slice(-12) });
    console.log(`${f.name}: overall ${r.summary.overall}, stress ${st?.status} -> ${(st?.evidence ?? []).slice(0, 3).join(" | ")}`);
  }
  return { at: new Date().toISOString(), host: "node-2", realClient: false, flights: out };
}

(async () => {
  mkdirSync(RUN, { recursive: true });
  const res = process.argv.includes("--flights") ? await flights() : await compileMatrix();
  const o = arg("--out");
  if (o) { mkdirSync(path.dirname(o), { recursive: true }); writeFileSync(o, JSON.stringify(res, null, 1)); console.log(`wrote ${o}`); }
  if (!process.argv.includes("--keep")) rmSync(RUN, { recursive: true, force: true });
})().catch((e) => { console.error(e); process.exit(1); });

