  return {
    seconds: s.seconds ?? STRESS_DEFAULTS.seconds,
    baselineSec: s.baselineSec ?? STRESS_DEFAULTS.baselineSec,
    sampleMs: s.sampleMs ?? STRESS_DEFAULTS.sampleMs,
    summon: s.summon === null ? null : { ...STRESS_DEFAULTS.summon, ...(s.summon || {}) },
    chunks: s.chunks === null ? null : { ...STRESS_DEFAULTS.chunks, ...(s.chunks || {}) },
    bot: s.bot ?? STRESS_DEFAULTS.bot,
