// Cyrus Test Flight STRESS phase (perf safety, 2026-10-11 ChunkMirror incident), pure half. The runner
// (services/modbuilder/tools/testflight/runner.js tf-lite-5 + stress-lib.js) loads the disposable server after boot and
// samples the real tick rate; this module builds the stress spec, re-judges the samples (twin of stress-lib.js
// judgeStress, parity-tested), works out what the load actually exercised for THIS mod and stores an honest record:
//   pass / warn / fail with measured numbers, or not_run with the reason (never "pass" for a mod the load never touched).
// A FAILED stress result blocks Install by default (gate.ts flightBlocks; CYRUS_PERF_BLOCK_ON_FAIL=0 turns that off).
import { playtestVersion } from "../playtest/plan";
import { perfSafetyEnabled } from "../safety/perf-risk";

export const STRESS_FLAG = "CYRUS_TESTFLIGHT_STRESS";
export const STRESS_BLOCK_FLAG = "CYRUS_PERF_BLOCK_ON_FAIL";
export const STRESS_VERSION = "stress-1";

export type StressThresholds = { tpsFail: number; tpsWarn: number; sustainSec: number; msptWarn: number; entityMax: number; stallSec: number; rssGrowthWarnMb: number };
export type StressSpec = {
  seconds?: number; baselineSec?: number; sampleMs?: number;
  summon?: { entity: string; perSecond: number; max: number } | null;
  chunks?: { perSecond: number; max: number } | null;
  bot?: boolean;
  commands?: string[];
  thresholds?: Partial<StressThresholds>;
};
export type StressSample = { phase: "baseline" | "load"; t: number; dtMs: number; tps: number | null; mspt: number | null; entities: number | null; rssKb: number };
export type StressVerdict = "pass" | "warn" | "fail" | "not_run";
export type StressNumbers = {
  baselineTps: number | null; tpsMin: number | null; tpsMedian: number | null; lowSec: number | null; warnSec: number | null; stallSec: number | null;
  msptMax: number | null; entitiesMax: number; rssPeakMb: number | null; rssGrowthMb: number | null; loadSamples: number;
};
/** What the runner returns as report.stress. */
export type StressResult = {
  schema: 1;
  verdict?: StressVerdict; reasons?: string[]; numbers?: StressNumbers; thresholds?: StressThresholds;
  samples: StressSample[];
  load: { summoned: number; chunks: number; commands: { command: string; reply?: string; error?: string }[]; bot: { ran: boolean; reason?: string; joined?: boolean; placed?: number; broken?: number; teleports?: number; failed?: number } | null; botRan: boolean };
  log: { cantKeepUp: number; watchdogPaused: { line: string } | null; errors: string[] };
};

export const STRESS_DEFAULTS = { seconds: 40, baselineSec: 6, sampleMs: 2000, summon: { entity: "minecraft:pig", perSecond: 2, max: 80 }, chunks: { perSecond: 4, max: 160 }, bot: true } as const;
export const THRESHOLD_DEFAULTS: StressThresholds = { tpsFail: 15, tpsWarn: 18, sustainSec: 10, msptWarn: 50, entityMax: 2500, stallSec: 10, rssGrowthWarnMb: 400 };
const PASSIVE_RE = /^(minecraft:)?(pig|cow|chicken|sheep|rabbit|cod|salmon|bat|armor_stand|villager)$/;
const COMMAND_RE = /^[a-z0-9_-]{1,32}( [a-z0-9_.:-]{1,32}){0,2}$/;
const RESERVED_RE = /^(stop|restart|reload|op|deop|kick|ban|ban-ip|pardon|whitelist|save-off|save-all|forceload|kill|execute|summon|tp|teleport|gamemode|fill|setblock|clone|time|gamerule|minecraft:)/i;
const SWITCH_OFF_RE = /\b(off|disable|stop|pause|toggle|reset|clear|remove|delete|uninstall|reload|unload|purge|wipe|perf)\b/i;

/** Is the stress phase on? (perf safety on, and CYRUS_TESTFLIGHT_STRESS not "0"). Runs only where the gate runs. */
export function stressEnabled(env: Record<string, string | undefined> = process.env): boolean {
  return perfSafetyEnabled(env) && !/^(0|false|off)$/i.test(String(env[STRESS_FLAG] ?? "").trim());
}

const num = (v: string | undefined, lo: number, hi: number): number | undefined => {
  if (v == null || v.trim() === "") return undefined;
  const n = Number(v);
  return Number.isFinite(n) && n >= lo && n <= hi ? n : undefined;
};
/** Thresholds from settings (env): CYRUS_STRESS_TPS_FAIL / _TPS_WARN / _SUSTAIN_SEC / _ENTITY_MAX / _MSPT_WARN. Bad values = defaults. */
export function stressThresholds(env: Record<string, string | undefined> = process.env): StressThresholds {
  const t = { ...THRESHOLD_DEFAULTS };
  const set = <K extends keyof StressThresholds>(k: K, v: number | undefined) => { if (v !== undefined) t[k] = v; };
  set("tpsFail", num(env.CYRUS_STRESS_TPS_FAIL, 1, 19.9));
  set("tpsWarn", num(env.CYRUS_STRESS_TPS_WARN, 1, 20));
  set("sustainSec", num(env.CYRUS_STRESS_SUSTAIN_SEC, 2, 60));
  set("entityMax", num(env.CYRUS_STRESS_ENTITY_MAX, 50, 50000));
  set("msptWarn", num(env.CYRUS_STRESS_MSPT_WARN, 10, 1000));
  if (t.tpsWarn < t.tpsFail) t.tpsWarn = t.tpsFail;
  return t;
}

/** Same rules as stress-lib.js validateStress. */
export function validateStress(s: StressSpec): string[] {
  const e: string[] = [];
  const intIn = (v: unknown, lo: number, hi: number) => Number.isInteger(v) && (v as number) >= lo && (v as number) <= hi;
  if (!s || typeof s !== "object" || Array.isArray(s)) return ["stress must be an object"];
  if (s.seconds != null && !intIn(s.seconds, 10, 120)) e.push("stress.seconds must be 10-120");
  if (s.baselineSec != null && !intIn(s.baselineSec, 2, 20)) e.push("stress.baselineSec must be 2-20");
  if (s.sampleMs != null && !intIn(s.sampleMs, 500, 5000)) e.push("stress.sampleMs must be 500-5000");
  if (s.summon != null) {
    if (!PASSIVE_RE.test(String(s.summon.entity ?? ""))) e.push("stress.summon.entity must be a passive mob");
    if (!intIn(s.summon.perSecond, 1, 10)) e.push("stress.summon.perSecond must be 1-10");
    if (!intIn(s.summon.max, 1, 300)) e.push("stress.summon.max must be 1-300");
  }
  if (s.chunks != null) {
    if (!intIn(s.chunks.perSecond, 1, 16)) e.push("stress.chunks.perSecond must be 1-16");
    if (!intIn(s.chunks.max, 1, 400)) e.push("stress.chunks.max must be 1-400");
  }
  if (s.bot != null && typeof s.bot !== "boolean") e.push("stress.bot must be a boolean");
  if (s.commands != null) {
    if (!Array.isArray(s.commands) || s.commands.length > 8) e.push("stress.commands: at most 8");
    else s.commands.forEach((c, i) => {
      if (typeof c !== "string" || !COMMAND_RE.test(c)) e.push(`stress.commands[${i}] must be a plain command label (+ up to 2 plain words)`);
      else if (RESERVED_RE.test(c) || SWITCH_OFF_RE.test(c)) e.push(`stress.commands[${i}]: '${c}' is reserved or would switch the mod off`);
    });
  }
  const t = s.thresholds ?? {};
  for (const [k, lo, hi] of [["tpsFail", 1, 19.9], ["tpsWarn", 1, 20], ["sustainSec", 2, 60], ["msptWarn", 10, 1000], ["entityMax", 50, 50000], ["stallSec", 2, 60], ["rssGrowthWarnMb", 50, 2000]] as const) {
    const v = t[k];
    if (v != null && !(typeof v === "number" && v >= lo && v <= hi)) e.push(`stress.thresholds.${k} must be ${lo}-${hi}`);
  }
  if (t.tpsFail != null && t.tpsWarn != null && t.tpsWarn < t.tpsFail) e.push("stress.thresholds.tpsWarn must be >= tpsFail");
  return e;
}

/** The stress spec the gate flies for a build: commands = the build's bare command labels that cannot switch it off. */
export function stressSpecFor(a: { version: string; commands?: string[]; env?: Record<string, string | undefined> }): StressSpec {
  const env = a.env ?? process.env;
  const commands = (a.commands ?? []).filter((c) => COMMAND_RE.test(c) && !RESERVED_RE.test(c) && !SWITCH_OFF_RE.test(c)).slice(0, 4);
  const secs = num(env.CYRUS_STRESS_SECONDS, 10, 120);
  return { ...(secs ? { seconds: Math.round(secs) } : {}), bot: playtestVersion(a.version).ok, commands, thresholds: stressThresholds(env) };
}

// ------------------------------------------------------------------ judge (twin of stress-lib.js) ----
const median = (a: number[]) => { if (!a.length) return null; const s = [...a].sort((x, y) => x - y); const k = s.length >> 1; return s.length % 2 ? s[k] : (s[k - 1] + s[k]) / 2; };
const r2 = (v: number | null) => (v == null || !Number.isFinite(v) ? null : Math.round(v * 100) / 100);
export function longestRun(samples: StressSample[], pred: (s: StressSample) => boolean): number {
  let best = 0, cur = 0;
  for (const s of samples) { if (pred(s)) { cur += s.dtMs || 0; best = Math.max(best, cur); } else cur = 0; }
  return best;
}

export function judgeStress(samples: StressSample[], thresholds?: Partial<StressThresholds>, extra: { crashed?: boolean; crashDetail?: string | null } = {}): { verdict: StressVerdict; reasons: string[]; numbers: StressNumbers; thresholds: StressThresholds } {
  const thr = { ...THRESHOLD_DEFAULTS, ...(thresholds ?? {}) };
  const base = samples.filter((s) => s.phase === "baseline" && s.tps != null).map((s) => s.tps!);
  const load = samples.filter((s) => s.phase === "load");
  const tpsL = load.filter((s) => s.tps != null).map((s) => s.tps!);
  const rss = samples.map((s) => s.rssKb).filter((x) => x > 0);
  const numbers: StressNumbers = {
    baselineTps: r2(median(base)),
    tpsMin: r2(load.length ? Math.min(...load.map((s) => (s.tps == null ? 0 : s.tps))) : null),
    tpsMedian: r2(median(tpsL)),
    lowSec: r2(longestRun(load, (s) => s.tps == null || s.tps < thr.tpsFail) / 1000),
    warnSec: r2(longestRun(load, (s) => s.tps == null || s.tps < thr.tpsWarn) / 1000),
    stallSec: r2(longestRun(load, (s) => s.tps == null) / 1000),
    msptMax: r2(Math.max(0, ...load.map((s) => s.mspt || 0))),
    entitiesMax: Math.max(0, ...samples.map((s) => s.entities || 0)),
    rssPeakMb: rss.length ? Math.round(Math.max(...rss) / 1024) : null,
    rssGrowthMb: rss.length ? Math.round((Math.max(...rss) - rss[0]) / 1024) : null,
    loadSamples: load.length,
  };
  const reasons: string[] = [];
  let verdict: StressVerdict;
  if (extra.crashed) { verdict = "fail"; reasons.push(`the server stopped during the stress test${extra.crashDetail ? `: ${extra.crashDetail}` : ""}`); }
  else if (!load.length) { verdict = "not_run"; reasons.push("no load samples were taken"); }
  else if (base.length && numbers.baselineTps! < thr.tpsFail) { verdict = "not_run"; reasons.push(`the test server was already slow before any load (${numbers.baselineTps} TPS), so no verdict`); }
  else {
    const fails: string[] = [], warns: string[] = [];
    if (numbers.lowSec! >= thr.sustainSec) fails.push(`TPS stayed under ${thr.tpsFail} for ${numbers.lowSec} s (lowest ${numbers.tpsMin})`);
    if (numbers.stallSec! >= thr.stallSec) fails.push(`the server stopped answering for ${numbers.stallSec} s`);
    if (numbers.entitiesMax > thr.entityMax) fails.push(`entities ran away: ${numbers.entitiesMax} (limit ${thr.entityMax})`);
    if (!fails.length) {
      if (numbers.warnSec! >= thr.sustainSec) warns.push(`TPS stayed under ${thr.tpsWarn} for ${numbers.warnSec} s (lowest ${numbers.tpsMin})`);
      if (longestRun(load, (s) => (s.mspt || 0) > thr.msptWarn) >= thr.sustainSec * 1000) warns.push(`MSPT stayed above ${thr.msptWarn} ms (max ${numbers.msptMax})`);
      if (numbers.rssGrowthMb != null && numbers.rssGrowthMb > thr.rssGrowthWarnMb) warns.push(`memory grew by ${numbers.rssGrowthMb} MB`);
    }
    verdict = fails.length ? "fail" : warns.length ? "warn" : "pass";
    reasons.push(...fails, ...warns);
    if (!reasons.length) reasons.push(`TPS held (median ${numbers.tpsMedian}, lowest ${numbers.tpsMin}) under load`);
  }
  return { verdict, reasons, numbers, thresholds: thr };
}

// ------------------------------------------------------------------ coverage ----
/** Bukkit/Paper events the stress load really fires, per load source. */
export const STRESS_EVENTS: Record<"summon" | "chunks" | "bot", readonly string[]> = {
  summon: ["CreatureSpawnEvent", "EntitySpawnEvent", "EntityAddToWorldEvent", "EntityRemoveFromWorldEvent", "EntityDeathEvent", "EntityDamageEvent", "EntitiesLoadEvent", "EntitiesUnloadEvent", "EntityMoveEvent"],
  chunks: ["ChunkLoadEvent", "ChunkUnloadEvent", "ChunkPopulateEvent", "EntitiesLoadEvent", "WorldLoadEvent"],
  bot: ["BlockPlaceEvent", "BlockBreakEvent", "BlockDamageEvent", "BlockCanBuildEvent", "BlockPhysicsEvent", "BlockDropItemEvent", "PlayerJoinEvent", "PlayerQuitEvent", "PlayerLoginEvent", "AsyncPlayerPreLoginEvent", "PlayerSpawnLocationEvent", "PlayerMoveEvent", "PlayerTeleportEvent", "PlayerInteractEvent", "PlayerChangedWorldEvent", "PlayerGameModeChangeEvent", "PlayerItemHeldEvent", "PlayerAnimationEvent", "PlayerChunkLoadEvent", "PlayerJumpEvent", "EntityPickupItemEvent", "ItemSpawnEvent"],
};
const simple = (e: string) => e.split(/[./$]/).pop()!;

/** Which of the mod's events the load fired (by simple class name). Unknown event list = null coverage (honest). */
export function stressCoverage(events: string[] | null, r: Pick<StressResult, "load">): { exercised: string[]; notExercised: string[]; firedSources: string[] } | null {
  if (!events) return null;
  const fired = new Set<string>();
  const sources: string[] = [];
  if (r.load.summoned > 0) { sources.push("mob spawns"); STRESS_EVENTS.summon.forEach((e) => fired.add(e)); }
  if (r.load.chunks > 0) { sources.push("chunk loads"); STRESS_EVENTS.chunks.forEach((e) => fired.add(e)); }
  if (r.load.botRan) { sources.push("a player placing/breaking blocks and moving"); STRESS_EVENTS.bot.forEach((e) => fired.add(e)); }
  const mine = [...new Set(events.map(simple))].sort();
  return { exercised: mine.filter((e) => fired.has(e)), notExercised: mine.filter((e) => !fired.has(e)), firedSources: sources };
}

export type StoredStress = {
  schema: 1;
  version: string;
  verdict: StressVerdict;
  /** One plain line for the owner/customer. */
  label: string;
  reasons: string[];
  numbers: StressNumbers | null;
  thresholds: StressThresholds | null;
  load: { summoned: number; chunks: number; commands: number; bot: string };
  coverage: { exercised: string[]; notExercised: string[]; firedSources: string[] } | null;
  watchdogPaused: string | null;
  cantKeepUp: number;
};

/**
 * The record stored on the build (StoredFlight.stress). The coverage rule: a measured FAIL is always a fail; a pass or
 * warn for a mod whose listened events were ALL outside the load (and that has no repeating task) becomes not_run.
 */
export function storedStress(raw: unknown, o: { events?: string[] | null; repeatingTasks?: number | null } = {}): StoredStress {
  const r = raw as StressResult | null;
  if (!r || typeof r !== "object" || !Array.isArray(r.samples)) {
    return { schema: 1, version: STRESS_VERSION, verdict: "not_run", label: "Stress test: not run (the test server returned no stress result).", reasons: ["no stress result"], numbers: null, thresholds: null, load: { summoned: 0, chunks: 0, commands: 0, bot: "off" }, coverage: null, watchdogPaused: null, cantKeepUp: 0 };
  }
  const j = judgeStress(r.samples, r.thresholds, {});
  // the runner's verdict wins for things only it saw (a crash); otherwise the re-judged samples
  let verdict: StressVerdict = r.verdict === "fail" || j.verdict === "fail" ? "fail" : j.verdict;
  const reasons = r.verdict === "fail" && j.verdict !== "fail" ? [...(r.reasons ?? [])] : [...j.reasons];
  const coverage = stressCoverage(o.events ?? null, r);
  if ((verdict === "pass" || verdict === "warn") && coverage && coverage.exercised.length === 0 && coverage.notExercised.length > 0 && !(o.repeatingTasks && o.repeatingTasks > 0)) {
    verdict = "not_run";
    reasons.unshift(`the stress load could not exercise this mod (it reacts to ${coverage.notExercised.slice(0, 4).join(", ")}${coverage.notExercised.length > 4 ? "..." : ""})`);
  }
  const n = j.numbers;
  const bot = r.load.bot ? (r.load.bot.ran === false ? `not run (${r.load.bot.reason ?? "unavailable"})` : `placed ${r.load.bot.placed ?? 0}, broke ${r.load.bot.broken ?? 0}, teleported ${r.load.bot.teleports ?? 0}`) : "off";
  const what = `${r.load.summoned} mobs, ${r.load.chunks} chunk loads${r.load.botRan ? ", a player building" : ""}`;
  const label = verdict === "pass" ? `Stress test passed: TPS stayed at ${n.tpsMedian} (lowest ${n.tpsMin}) under load (${what}).`
    : verdict === "warn" ? `Stress test passed with a warning: ${reasons[0]} (${what}).`
    : verdict === "fail" ? `Stress test FAILED: ${reasons[0]} (${what}).`
    : `Stress test not run: ${reasons[0]}.`;
  return {
    schema: 1, version: STRESS_VERSION, verdict, label: label.slice(0, 400), reasons: reasons.slice(0, 6), numbers: n, thresholds: j.thresholds,
    load: { summoned: r.load.summoned, chunks: r.load.chunks, commands: r.load.commands.length, bot }, coverage,
    watchdogPaused: r.log?.watchdogPaused?.line ?? null, cantKeepUp: r.log?.cantKeepUp ?? 0,
  };
}

/** Does this stored stress result block Install? Only a FAILED stress, only with perf safety on, unless CYRUS_PERF_BLOCK_ON_FAIL=0. */
export function stressBlocks(s: unknown, version: string, env: Record<string, string | undefined> = process.env): { blocked: false } | { blocked: true; reason: string } {
  const st = s as StoredStress | null;
  if (!st || st.schema !== 1 || st.verdict !== "fail") return { blocked: false };
  if (!perfSafetyEnabled(env) || /^(0|false|off)$/i.test(String(env[STRESS_BLOCK_FLAG] ?? "").trim())) return { blocked: false };
  const n = st.numbers;
  const nums = n ? ` Measured: TPS ${n.tpsMedian ?? "?"} median, ${n.tpsMin ?? "?"} lowest (baseline ${n.baselineTps ?? "?"}), under ${st.thresholds?.tpsFail ?? 15} TPS for ${n.lowSec ?? "?"} s, up to ${n.entitiesMax} entities.` : "";
  return { blocked: true, reason: `This version failed its stress test on Paper ${version}: ${st.reasons[0] ?? "the server slowed down under load"}.${nums} Ask Cyrus for a change with tighter limits (a smaller radius, fewer changes per tick) before installing it.` };
}

