// Cyrus perf safety (3): Test Flight STRESS phase, pure parts (lib/cyrus/testflight/stress.ts + runner stress-lib.js).
// Real flights (ChunkMirror unbounded vs bounded): test/cyrus-perf-real.ts --flights on node-2.
import { describe, it } from "node:test";
import assert from "node:assert/strict";
import { judgeStress, storedStress, stressBlocks, stressCoverage, stressEnabled, stressSpecFor, stressThresholds, validateStress, type StressResult, type StressSample } from "../lib/cyrus/testflight/stress";
import { flightBlocks, flightLines, type StoredFlight } from "../lib/cyrus/testflight/gate";
import { requiredStages, validateSpec } from "../lib/cyrus/testflight/spec";
import { summarize } from "../lib/cyrus/testflight/summary";
import type { TestFlightReport } from "../lib/cyrus/testflight/types";

// eslint-disable-next-line @typescript-eslint/no-require-imports
const SL = require("../services/modbuilder/tools/testflight/stress-lib.js");
// eslint-disable-next-line @typescript-eslint/no-require-imports
const LIB = require("../services/modbuilder/tools/testflight/lib.js");

const seq = (phase: "baseline" | "load", tps: (number | null)[], extra: Partial<StressSample> = {}): StressSample[] => tps.map((t, i) => ({ phase, t: i * 2000, dtMs: 2000, tps: t, mspt: t == null ? null : Math.min(1000, 1000 / Math.max(t, 0.1)), entities: 100, rssKb: 900_000 + i * 1000, ...extra }));
const HEALTHY = [...seq("baseline", [20, 20, 19.9]), ...seq("load", Array(20).fill(19.8))];
const COLLAPSE = [...seq("baseline", [20, 20, 20]), ...seq("load", [19, 12, 4, 1.2, null, null, 0.8, 1, 2, 1, 0.5, 1, 1, 1, 1, 1, 1, 1, 1, 1], { entities: 9000 })];
const WOBBLY = [...seq("baseline", [20, 20, 20]), ...seq("load", [19, 17, 16.5, 17, 16, 17.5, 16, 17, 19, 19.5])];
const SLOW_HOST = [...seq("baseline", [9, 10, 11]), ...seq("load", [10, 10, 10, 10, 10, 10])];

describe("stress judge", () => {
  it("healthy server = pass, collapse = fail with the numbers, wobbly = warn, slow host = not_run", () => {
    assert.equal(judgeStress(HEALTHY).verdict, "pass");
    const c = judgeStress(COLLAPSE);
    assert.equal(c.verdict, "fail");
    assert.match(c.reasons.join(" "), /TPS stayed under 15 for \d+ s/);
    assert.match(c.reasons.join(" "), /entities ran away: 9000/);
    assert.equal(c.numbers.tpsMin, 0);
    assert.ok(c.numbers.lowSec! >= 36);
    assert.equal(judgeStress(WOBBLY).verdict, "warn");
    assert.equal(judgeStress(SLOW_HOST).verdict, "not_run");
    assert.equal(judgeStress([]).verdict, "not_run");
    assert.equal(judgeStress(HEALTHY, undefined, { crashed: true, crashDetail: "exit 1" }).verdict, "fail");
  });
  it("a short dip is not sustained", () => {
    const dip = [...seq("baseline", [20, 20]), ...seq("load", [20, 3, 3, 3, 3, 20, 20, 20])]; // 8 s under 15
    assert.equal(judgeStress(dip).verdict, "warn");
    assert.equal(judgeStress(dip, { sustainSec: 6 }).verdict, "fail");
  });
  it("the TypeScript judge and the runner's stress-lib.js agree (parity)", () => {
    for (const s of [HEALTHY, COLLAPSE, WOBBLY, SLOW_HOST, []]) {
      assert.deepEqual(judgeStress(s), SL.judgeStress(s, undefined, {}));
      assert.deepEqual(judgeStress(s, { tpsFail: 12, sustainSec: 4 }), SL.judgeStress(s, { tpsFail: 12, sustainSec: 4 }, {}));
    }
    assert.deepEqual(LIB.CHECK_IDS, ["boot_done", "plugins_enabled", "startup_log_clean", "rcon_checks", "playtest", "stress", "clean_stop", "no_leaks"]);
  });
  it("runner output parsers", () => {
    assert.equal(SL.parseGametime("The time is 48213"), 48213);
    assert.equal(SL.parseMspt("§6Server tick times §e(§7avg§e/§7min§e/§7max§e)§6 from last 5s§7,§6 10s§7,§6 1m§e:\n§6◴ §a3.1§7/§a0.9§7/§a12.4§e, §a2.9§7/§a0.8§7/§a12.4"), 3.1);
    assert.equal(SL.parseEntityCount("Test passed, count: 1234"), 1234);
    assert.equal(SL.parseEntityCount("Test failed"), 0);
    assert.equal(SL.spiralChunks(160).length, 160);
    assert.ok(SL.spiralChunks(400).every(([x, z]: [number, number]) => Math.max(Math.abs(x), Math.abs(z)) >= 2 && Math.max(Math.abs(x), Math.abs(z)) <= 14));
  });
});

describe("stress spec", () => {
  it("validation (TS twin of the runner's)", () => {
    for (const bad of [{ seconds: 5 }, { summon: { entity: "minecraft:wither", perSecond: 2, max: 10 } }, { commands: ["chunkmirror off"] }, { commands: ["stop"] }, { thresholds: { tpsFail: 18, tpsWarn: 10 } }, { chunks: { perSecond: 99, max: 10 } }]) {
      assert.ok(validateStress(bad as never).length > 0, JSON.stringify(bad));
      assert.ok(SL.validateStress(bad).length > 0, `runner: ${JSON.stringify(bad)}`);
    }
    assert.deepEqual(validateStress({ seconds: 40, commands: ["chunkmirror", "chunkmirror status"] }), []);
    assert.deepEqual(SL.validateStress({ seconds: 40, commands: ["chunkmirror", "chunkmirror status"] }), []);
  });
  it("stressSpecFor: bot only on verified versions, commands that cannot switch the mod off, thresholds from settings", () => {
    const s = stressSpecFor({ version: "1.21.11", commands: ["chunkmirror", "toggle", "kill", "mirror off"], env: { CYRUS_STRESS_TPS_FAIL: "12", CYRUS_STRESS_SECONDS: "30" } });
    assert.equal(s.bot, true);
    assert.deepEqual(s.commands, ["chunkmirror"]);
    assert.equal(s.thresholds!.tpsFail, 12);
    assert.equal(s.seconds, 30);
    assert.equal(stressSpecFor({ version: "1.21.4", env: {} }).bot, false);
    assert.equal(stressThresholds({ CYRUS_STRESS_TPS_FAIL: "banana" }).tpsFail, 15);
    assert.deepEqual(validateStress(s), []);
  });
  it("switches: on by default with perf safety, off with CYRUS_TESTFLIGHT_STRESS=0 or CYRUS_PERF_SAFETY=0", () => {
    assert.equal(stressEnabled({}), true);
    assert.equal(stressEnabled({ CYRUS_TESTFLIGHT_STRESS: "0" }), false);
    assert.equal(stressEnabled({ CYRUS_PERF_SAFETY: "0" }), false);
  });
  it("a spec with stress makes the stage required and validates", () => {
    const spec = { version: "1.21.11", stress: { seconds: 20 } };
    assert.ok(requiredStages(spec).has("stress"));
    assert.ok(!requiredStages({ version: "1.21.11" }).has("stress"));
    assert.equal(validateSpec(spec).ok, true);
    assert.equal(validateSpec({ version: "1.21.11", stress: { seconds: 1 } }).ok, false);
  });
});

const result = (samples: StressSample[], load: Partial<StressResult["load"]> = {}, verdict?: string): StressResult => ({ schema: 1, samples, verdict: verdict as never, load: { summoned: 80, chunks: 160, commands: [], bot: { ran: true, joined: true, placed: 40, broken: 40, teleports: 4 }, botRan: true, ...load }, log: { cantKeepUp: 0, watchdogPaused: null, errors: [] } });

describe("stored stress + coverage + install block", () => {
  it("coverage: which of the mod's events the load fired", () => {
    const c = stressCoverage(["org.bukkit.event.block.BlockPlaceEvent", "org/bukkit/event/player/PlayerFishEvent"], result(HEALTHY))!;
    assert.deepEqual(c.exercised, ["BlockPlaceEvent"]);
    assert.deepEqual(c.notExercised, ["PlayerFishEvent"]);
    assert.equal(stressCoverage(null, result(HEALTHY)), null);
    assert.deepEqual(stressCoverage(["BlockPlaceEvent"], result(HEALTHY, { botRan: false }))!.exercised, []);
  });
