    const flight: StoredFlight = { schema: 1, gate: "tfgate-1", state: "done", version: "1.21.11", verdict: "passed", label: "boot-tested on Paper 1.21.11", checks: [], flights: 1, busyRetries: 0, at: new Date().toISOString(), stress: fail };
    assert.equal(flightBlocks(flight, {}).blocked, true, "blocks even without CYRUS_TESTFLIGHT_BLOCK_ON_FAIL");
    assert.equal(flightBlocks({ ...flight, stress: storedStress(result(HEALTHY), { events: ["BlockPlaceEvent"] }) }, {}).blocked, false);
    assert.equal(flightBlocks({ ...flight, stress: undefined }, {}).blocked, false, "older flights without stress never block");
    assert.match(flightLines(flight).at(-1)!, /^Stress test FAILED/);
  });
  it("summary: stress is required only when asked for, and a boot summary ignores it", () => {
    const report = { schema: 1, runId: "tf-x", status: "completed", version: "1.21.11", javaRelease: 21, startedAt: "", finishedAt: "", timings: {}, bootMs: 1, doneReportedSec: 1, peakRssKb: 1, artifacts: [], engine: null, notes: [], overall: "failed",
      checks: ["boot_done", "startup_log_clean", "clean_stop", "no_leaks"].map((id) => ({ id, status: "pass", required: true, evidence: ["ok"], durationMs: 1 })).concat([{ id: "stress", status: "fail", required: true, evidence: ["stress FAIL"], durationMs: 1 }]) } as unknown as TestFlightReport;
    assert.equal(summarize({ version: "1.21.11" }, report).overall, "passed");
    assert.equal(summarize({ version: "1.21.11", stress: {} }, report).overall, "failed");
  });
});

