// Cyrus POST-INSTALL PERF WATCH, pure half (perf safety, 2026-10-11 ChunkMirror incident). After a Cyrus mod lands on
// a customer server, the platform worker (worker/cyrus-perf-watch.ts) reads the game log since shortly before the
// change for `watchMinutes` and asks this module whether the new mod is dragging the server down:
//   - the mod's own watchdog lines ("[NxPerf] status ... tps=4.20 ... own_ms=..." every 30 s for the first 15 min,
//     "[NxPerf] PAUSED ..."): TPS under the floor in the last `sustainLines` status lines of THIS plugin = lagging
//     (a pause by the in-plugin watchdog that fixed it = recovered, no action);
//   - older mods without the watchdog: Paper's "Can't keep up! ... Running Nms or N ticks behind" lines after the
//     change, only when the new mod is the ONLY change in the window and the server did not already lag before it;
//   - a crash loop is judged by lib/cyrus/lifecycle/logs.ts judgeCrashLoop (passed in) and always counts.
// Verdicts never touch anything: the worker acts (disable by default, or roll back / notify only), fail-safe, and
// never deletes customer data. Switches: CYRUS_PERF_WATCH (default on with CYRUS_PERF_SAFETY), CYRUS_PERF_WATCH_ACTION
// (disable | rollback | notify; default disable), CYRUS_PERF_WATCH_MINUTES (default 15), CYRUS_PERF_WATCH_RESTART
// (default on: restart after the disable so the plugin is really unloaded).
import { perfSafetyEnabled } from "./perf-risk";

export const PERF_WATCH_FLAG = "CYRUS_PERF_WATCH";
export type PerfWatchAction = "disable" | "rollback" | "notify";
export type PerfWatchConfig = { enabled: boolean; action: PerfWatchAction; minutes: number; restart: boolean; tpsFloor: number; sustainLines: number; cantKeepUpMin: number; behindMsMin: number };

const off = (v: string | undefined) => /^(0|false|off|no)$/i.test(String(v ?? "").trim());
export function perfWatchConfig(env: Record<string, string | undefined> = process.env): PerfWatchConfig {
  const a = String(env.CYRUS_PERF_WATCH_ACTION ?? "").trim().toLowerCase();
  const m = Number(env.CYRUS_PERF_WATCH_MINUTES);
  const floor = Number(env.CYRUS_PERF_WATCH_TPS_FLOOR);
  return {
    enabled: perfSafetyEnabled(env) && !off(env[PERF_WATCH_FLAG]),
    action: a === "rollback" || a === "notify" ? a : "disable",
    minutes: Number.isFinite(m) && m >= 5 && m <= 120 ? Math.round(m) : 15,
    restart: !off(env.CYRUS_PERF_WATCH_RESTART),
    tpsFloor: Number.isFinite(floor) && floor >= 5 && floor <= 19.5 ? floor : 15,
    sustainLines: 3,
    cantKeepUpMin: 6,
    behindMsMin: 30_000,
  };
}

export type NxPerfLine = { kind: "status" | "paused" | "resumed" | "lag"; plugin: string; tps: number | null; ownMs: number | null; paused: boolean | null; reason: string | null; line: string; index: number };
const numOf = (s: string, k: string) => { const m = new RegExp(`\\b${k}=(-?\\d+(?:\\.\\d+)?)`).exec(s); return m ? Number(m[1]) : null; };

/** The watchdog's machine-readable lines (any plugin; the log prefix is ignored). */
export function parseNxPerfLines(log: string): NxPerfLine[] {
  const out: NxPerfLine[] = [];
  String(log ?? "").split(/\r?\n/).forEach((line, index) => {
    const m = /\[NxPerf\] (status|PAUSED|RESUMED|LAG)\b(.*)$/.exec(line);
    if (!m) return;
    const rest = m[2];
    const plugin = (/\bplugin=([A-Za-z0-9_]+)/.exec(rest) ?? [])[1] ?? "";
    out.push({ kind: m[1] === "status" ? "status" : m[1] === "PAUSED" ? "paused" : m[1] === "RESUMED" ? "resumed" : "lag", plugin, tps: numOf(rest, "tps"), ownMs: numOf(rest, "own_ms"), paused: /\bpaused=true\b/.test(rest) ? true : /\bpaused=false\b/.test(rest) ? false : null, reason: (/\breason=(\w+)/.exec(rest) ?? [])[1] ?? null, line: line.trim().slice(0, 300), index });
