export function parseCantKeepUp(log: string): { index: number; behindMs: number }[] {
  const out: { index: number; behindMs: number }[] = [];
  String(log ?? "").split(/\r?\n/).forEach((line, index) => {
    const m = /Can't keep up!.*?Running (\d+)ms/.exec(line);
