export type PerfWatchInput = {
  /** The game log from shortly BEFORE the change until now (oldest first). */
  log: string;
  /** Line index in `log` where the change happened (lines before it are the baseline). 0 = unknown. */
  changeAt: number;
  /** The mod's plugin name (plugin.yml name) and display name. */
  pluginName: string | null;
  modName: string;
  /** How many mods (any source) changed on the server in the window, this one included. */
  changedCount: number;
  /** The crash-loop judgement (lib/cyrus/lifecycle/logs.ts judgeCrashLoop) when the server keeps restarting. */
  crashLoop?: { crashLoop: boolean; suspectIsThisMod: boolean; why: string } | null;
};
export type PerfWatchVerdict = { verdict: "ok" | "lagging" | "crash_loop" | "recovered" | "unknown"; act: boolean; why: string; evidence: string[]; tps: number | null };

export function judgePerfWatch(i: PerfWatchInput, cfg: Pick<PerfWatchConfig, "tpsFloor" | "sustainLines" | "cantKeepUpMin" | "behindMsMin">): PerfWatchVerdict {
  if (i.crashLoop?.crashLoop && i.crashLoop.suspectIsThisMod) return { verdict: "crash_loop", act: true, why: i.crashLoop.why, evidence: [], tps: null };
  const lines = parseNxPerfLines(i.log).filter((l) => l.index >= i.changeAt);
  const mine = i.pluginName ? lines.filter((l) => l.plugin.toLowerCase() === i.pluginName!.toLowerCase()) : [];
  const statuses = mine.filter((l) => l.kind === "status");
  const lastPause = [...mine].reverse().find((l) => l.kind === "paused");
  if (statuses.length) {
    const tail = statuses.slice(-cfg.sustainLines);
    const lastTps = tail.at(-1)?.tps ?? null;
    const lowAll = tail.length >= cfg.sustainLines && tail.every((l) => l.tps != null && l.tps < cfg.tpsFloor);
    // our share: the watchdog's own_ms vs the tick length at that TPS (>= 25% = this mod is the cause)
    const share = (l: NxPerfLine) => (l.ownMs ?? 0) / Math.max(50, 1000 / Math.max(0.05, l.tps ?? 20));
    if (lowAll && tail.some((l) => share(l) >= 0.25 || l.paused)) {
      return { verdict: "lagging", act: true, why: `${i.modName} kept the server under ${cfg.tpsFloor} TPS after it was installed (last ${tail.map((l) => l.tps).join(", ")} TPS${lastPause ? "; its own watchdog paused it but the server did not recover" : ""})`, evidence: tail.map((l) => l.line), tps: lastTps };
    }
    if (lowAll) return { verdict: "ok", act: false, why: `the server is under ${cfg.tpsFloor} TPS but ${i.modName}'s own measurements say it is not the cause`, evidence: tail.map((l) => l.line), tps: lastTps };
    if (lastPause) return { verdict: "recovered", act: false, why: `${i.modName}'s watchdog paused its heavy features and the server recovered (${lastTps} TPS)`, evidence: [lastPause.line], tps: lastTps };
    return { verdict: "ok", act: false, why: `${statuses.length} watchdog reading(s) since the install, last ${lastTps} TPS`, evidence: tail.map((l) => l.line), tps: lastTps };
  }
  // no watchdog lines (a mod built before perf safety, or the log has not shown one yet): Paper's lag warnings
  const ck = parseCantKeepUp(i.log);
  const before = ck.filter((c) => c.index < i.changeAt).length;
  const after = ck.filter((c) => c.index >= i.changeAt);
  const behind = after.reduce((a, c) => a + c.behindMs, 0);
  if (after.length >= cfg.cantKeepUpMin && behind >= cfg.behindMsMin) {
    const ev = after.slice(-3).map((c) => `log line ${c.index + 1}: Can't keep up, ${c.behindMs} ms behind`);
    if (i.changedCount === 1 && before <= 1) return { verdict: "lagging", act: true, why: `the server fell ${Math.round(behind / 1000)} s behind (${after.length} "Can't keep up" warnings) after ${i.modName} was installed, and it was the only change`, evidence: ev, tps: null };
    return { verdict: "lagging", act: false, why: `the server is lagging (${after.length} "Can't keep up" warnings), but ${before > 1 ? "it already lagged before the change" : `${i.changedCount} mods changed`}, so it is not pinned on ${i.modName}`, evidence: ev, tps: null };
  }
  return { verdict: mine.length || after.length ? "ok" : "unknown", act: false, why: mine.length || after.length ? "no sustained lag after the install" : "no performance readings in the log yet", evidence: [], tps: null };
}

/** The owner-facing message for an action the worker took (plain words, the measured numbers, how to undo it). */
export function perfWatchMessage(v: PerfWatchVerdict, action: PerfWatchAction | "none", modName: string): { title: string; body: string } {
  const did = action === "disable" ? `we switched off ${modName}` : action === "rollback" ? `we rolled ${modName} back to its previous version` : `${modName} may be slowing your server down`;
  const how = action === "disable" ? " Its config and data are kept. Switch it on again from the Mods tab, or ask Cyrus for a lighter version (a smaller radius, fewer changes per tick)."
    : action === "rollback" ? " Its config and data are kept. The new version stays in your Cyrus project."
    : " Open the Mods tab to switch it off (\"Disable this mod now\" works even while the server is slow).";
  return { title: did, body: `${v.why}.${how}`.replace(/\.\./g, ".").slice(0, 900) };
}

