"use client";

import { useState } from "react";
import { Icon } from "@/components/nx/Icon";
import type { InstalledMod } from "@/lib/actions-mod-installs";

/**
 * Cyrus perf safety: an always-visible "Disable this mod now" strip on the server's Mods tab, one button per enabled
 * Cyrus mod. Two clicks (arm, then confirm): the worker switches the mod off (kept on disk, config kept) and restarts
 * the game so it is really unloaded. It works while the server is lagging: nothing waits for the game itself.
 */
export function CyrusDisableNow({ mods, busy, onDisable }: { mods: InstalledMod[]; busy: boolean; onDisable: (m: InstalledMod) => void }) {
  const [armed, setArmed] = useState<string | null>(null);
  if (!mods.length) return null;
  return (
    <div className="flex flex-col gap-2 rounded-[14px] border border-rim-hi bg-surface px-3 py-2.5" role="region" aria-label="Cyrus mods: disable now">
      <div className="flex items-center gap-2 text-[12px] text-tx-dim">
        <Icon name="warntriangle" size={13} tone="inherit" />
        <span>Server slow after a Cyrus mod? Switch it off right away: we restart the server for you (its config and data are kept).</span>
      </div>
      <ul className="flex flex-wrap gap-2">
        {mods.map((m) => {
          const on = armed === m.id;
          return (
            <li key={m.id} className="flex min-w-0 items-center gap-1.5">
              <button type="button" disabled={busy}
                onClick={() => { if (on) { setArmed(null); onDisable(m); } else setArmed(m.id); }}
                aria-label={on ? `Confirm: switch off ${m.name} and restart the server` : `Disable ${m.name} now`}
                className={"truncate rounded-[10px] border px-2.5 py-1 text-[12px] font-semibold transition disabled:opacity-50 " +
                  (on ? "border-red/60 bg-red/15 text-red" : "border-rim-hi bg-well text-tx hover:border-red/50 hover:text-red")}>
                {on ? `Confirm: switch off ${m.name} + restart` : `Disable ${m.name} now`}
              </button>
              {on && <button type="button" onClick={() => setArmed(null)} className="text-[11.5px] text-tx-faint hover:text-tx">Cancel</button>}
            </li>
          );
        })}
      </ul>
    </div>
  );
}

