/**
 * Cyrus POST-INSTALL PERF WATCH (perf safety, 2026-10-11 ChunkMirror incident). Platform half: the pure judge is
 * lib/cyrus/safety/perf-watch.ts. Every 2 minutes (lib/cyrus/worker/schedule.ts "cyrus-perf-watch"), for each Cyrus
 * mod installed or updated in the last CYRUS_PERF_WATCH_MINUTES (default 15) on a RUNNING server with no job queued:
 *   read the game log since 10 min before the change (docker logs --timestamps, read-only), judge it (the mod's own
 *   [NxPerf] status/PAUSED lines; Paper "Can't keep up" lines when it was the only change; crash loops via
 *   judgeCrashLoop), and when the new mod is the cause act ONCE per (server, mod, build):
 *     disable (default)  engine "disable" (jar to /root/.nxeon-mods/disabled, config kept) + restart (CYRUS_PERF_WATCH_RESTART)
 *     rollback           the previous succeeded version whose stress test did not fail, else disable
 *     notify             tell the owner only
 *   and tell the owner in-app + email with the measured numbers. Signals: PERF_LAG / PERF_DISABLED / PERF_ROLLED_BACK.
 * Inert unless CYRUS_PERF_WATCH is on (default ON with CYRUS_PERF_SAFETY) AND real game-mod changes are enabled
 * (ENABLE_REAL_GAMEMODS=1 or the sandbox) for any action; never deletes customer data; never touches a server whose
 * mod toggle policy says the disable could remove world content.
 */
import { db } from "../lib/db";
import { SANDBOX } from "../lib/sandbox";
import { familyFor } from "../lib/game-config";
import { withServerSsh, exec as sshExec } from "../lib/ssh-exec";
import { enqueueModOp } from "../lib/mods/queue";
import { toggleDecision } from "../lib/mods/toggle-policy";
import { engineInstallerFor } from "../lib/mods/installers";
import { CYRUS_SOURCE } from "../lib/mods/installers/cyrus";
import { cyrusDb } from "../lib/cyrus/db";
import { judgeCrashLoop } from "../lib/cyrus/lifecycle/logs";
import { judgePerfWatch, perfWatchConfig, perfWatchMessage, type PerfWatchAction } from "../lib/cyrus/safety/perf-watch";
import { readStoredFlight } from "../lib/cyrus/testflight/gate";
import { dockerContainerNameFrom } from "./game-variant";
import { defaultMailer, tellOwner, type Mailer } from "./cyrus-lifecycle";

const CONTAINER_RE = /^[A-Za-z0-9][A-Za-z0-9_.-]{0,62}$/;
const BASELINE_MS = 10 * 60_000;
const realChanges = () => SANDBOX || process.env.ENABLE_REAL_GAMEMODS === "1";

/** Timestamped game log since `since` (oldest first) -> { text, changeAt } where changeAt is the first line at/after `change`. */
async function readTimedLog(server: { osTemplate: { setupScript: string | null } } & Record<string, unknown>, since: Date, change: Date): Promise<{ text: string; changeAt: number }> {
  const container = dockerContainerNameFrom(server.osTemplate.setupScript ?? "");
  if (!container || !CONTAINER_RE.test(container)) throw new Error("no container name");
  const cmd = `docker logs --timestamps --since ${since.toISOString()} ${container} 2>&1 | tail -n 6000`;
  const r = await withServerSsh(server as never, (conn) => sshExec(conn, cmd, 30_000));
  return splitTimed(r.stdout, change);
}

/** Pure: strip docker's RFC3339 timestamps and find the change line. Exported for tests. */
export function splitTimed(out: string, change: Date): { text: string; changeAt: number } {
  const lines = String(out ?? "").split(/\r?\n/);
  let changeAt = -1;
  const text = lines.map((l, i) => {
    const m = /^(\d{4}-\d\d-\d\dT[\d:.]+Z)\s(.*)$/.exec(l);
    if (m && changeAt < 0 && new Date(m[1]).getTime() >= change.getTime()) changeAt = i;
    return m ? m[2] : l;
  }).join("\n");
  return { text, changeAt: changeAt < 0 ? lines.length : changeAt };
}

/** Log reader; tests swap it (never SSH in tests). */
export let perfLogReader: (server: never, since: Date, change: Date) => Promise<{ text: string; changeAt: number }> = readTimedLog as never;
export function setPerfLogReader(fn: typeof perfLogReader) { perfLogReader = fn; }

let running = false;

export async function cyrusPerfWatchSweep(opts: { env?: Record<string, string | undefined>; mailer?: Mailer; log?: (s: string) => void; now?: Date } = {}): Promise<{ watched: number; acted: number; notified: number; skipped: string | null }> {
  const cfg = perfWatchConfig(opts.env ?? process.env);
  const out = { watched: 0, acted: 0, notified: 0, skipped: null as string | null };
  if (!cfg.enabled) return { ...out, skipped: "switched off" };
  if (running) return { ...out, skipped: "already running" };
  running = true;
  const log = opts.log ?? ((s: string) => console.log(`[cyrus-perf-watch] ${s}`));
  const now = opts.now ?? new Date();
  const since = new Date(now.getTime() - cfg.minutes * 60_000);
  try {
    const rows = await db.serverMod.findMany({ where: { status: "INSTALLED", updatedAt: { gt: since }, mod: { source: CYRUS_SOURCE } }, include: { mod: true }, orderBy: { updatedAt: "asc" }, take: 50 });
    for (const row of rows) {
      if (!row.mod.sourceId) continue;
      const seen = await cyrusDb.cyrusModSignal.findFirst({ where: { serverId: row.serverId, modId: row.modId, buildId: row.versionId, kind: { in: ["PERF_DISABLED", "PERF_ROLLED_BACK", "PERF_LAG"] }, createdAt: { gt: since } } });
      if (seen) continue;
      const server = await db.server.findUnique({ where: { id: row.serverId }, include: { osTemplate: true, gamePlan: true, node: true, dedicatedIp: true, gameRuntime: true } });
      if (!server || server.status !== "RUNNING" || server.gameRuntime?.intent === "stopped") continue;
      if ((await db.job.count({ where: { serverId: row.serverId, status: { in: ["QUEUED", "RUNNING"] } } })) > 0) continue;
      out.watched++;
      const build = row.versionId ? await db.modBuild.findUnique({ where: { id: row.versionId }, select: { pluginName: true } }) : null;
      let lg: { text: string; changeAt: number };
      try { lg = await perfLogReader(server as never, new Date(row.updatedAt.getTime() - BASELINE_MS), row.updatedAt); }
      catch (e) { log(`couldn't read the log of ${server.hostname}: ${(e as Error).message}`); continue; }
      const family = familyFor(server) ?? "minecraft";
      const changed = await db.serverMod.findMany({ where: { serverId: row.serverId, updatedAt: { gt: new Date(row.updatedAt.getTime() - BASELINE_MS) } }, include: { mod: true } });
      const rt = server.gameRuntime;
      const cl = judgeCrashLoop({ family, log: lg.text.split("\n").slice(lg.changeAt).join("\n"), changed: changed.map((c) => ({ name: c.mod.name, key: c.mod.sourceId ?? c.mod.name, fileName: c.fileName })), runtimeState: rt?.state ?? null, containerState: rt?.containerState ?? null });
      const v = judgePerfWatch({ log: lg.text, changeAt: lg.changeAt, pluginName: build?.pluginName ?? null, modName: row.mod.name, changedCount: Math.max(1, changed.length),
        crashLoop: { crashLoop: cl.crashLoop, suspectIsThisMod: !!cl.suspect && cl.suspect.key === (row.mod.sourceId ?? row.mod.name), why: cl.why } }, cfg);
      if (!v.act) { if (v.verdict === "lagging") log(`${row.mod.name} on ${server.hostname}: ${v.why} (no action)`); continue; }
      // act once
      let action: PerfWatchAction | "none" = realChanges() ? cfg.action : "notify";
      const d = toggleDecision({ family, variant: server.gameVariant ?? null, mod: row.mod, engine: !!engineInstallerFor(family, row.mod.source) });
      if (action !== "notify" && (!d.allowed || d.needsAck)) action = "notify";
      let done = false;
      if (action === "rollback") {
        const prev = await previousSafeVersion(row.mod.sourceId, row.versionId);
        if (prev) {
          const q = await enqueueModOp(row.serverId, row.modId, "update", { userId: server.userId, slug: row.mod.slug }, { targetVersionId: prev, restartAfter: cfg.restart });
          done = q.ok;
        }
        if (!done) action = "disable";
      }
      if (action === "disable" && !done) {
        const q = await enqueueModOp(row.serverId, row.modId, "disable", { userId: server.userId, slug: row.mod.slug }, { restartAfter: cfg.restart });
        done = q.ok;
        if (!done) action = "notify";
      }
      const kind = action === "disable" ? "PERF_DISABLED" : action === "rollback" ? "PERF_ROLLED_BACK" : "PERF_LAG";
      await cyrusDb.cyrusModSignal.create({ data: { serverId: row.serverId, modId: row.modId, rootBuildId: row.mod.sourceId, buildId: row.versionId, kind, evidence: [v.why, ...v.evidence].join("\n").slice(0, 2000) } });
      const msg = perfWatchMessage(v, action === "notify" ? "notify" : action, row.mod.name);
      await tellOwner(row.serverId, msg.title, msg.body, opts.mailer ?? (await defaultMailer()));
      if (action === "notify") out.notified++; else out.acted++;
      log(`${kind} ${row.mod.name} on ${server.hostname}: ${v.why}`);
    }
  } finally {
    running = false;
  }
  return out;
}

/** The newest succeeded version BEFORE `current` in the chain whose stress test did not fail (null = none). */
async function previousSafeVersion(rootBuildId: string, current: string | null): Promise<string | null> {
  const chain = await db.modBuild.findMany({ where: { OR: [{ id: rootBuildId }, { rootBuildId }], status: "succeeded" }, orderBy: { createdAt: "asc" }, select: { id: true, cyrus: true } });
  const idx = current ? chain.findIndex((b) => b.id === current) : chain.length;
  for (let i = (idx < 0 ? chain.length : idx) - 1; i >= 0; i--) {
    const f = readStoredFlight((chain[i].cyrus as { testFlight?: unknown } | null)?.testFlight);
    if (f?.stress?.verdict === "fail") continue;
    return chain[i].id;
  }
  return null;
}

