type Walk = { calls: { target: string; via: string; schedule?: boolean }[]; commands: number; summons: number; forceloadAdds: number; schedules: { target: string; append: boolean }[] };

/** Check ONE command (already without a leading slash). Pushes findings; returns the walk facts. */
function checkCommand(raw: string, at: string, ctx: FnContext, f: FnFinding[], w: Walk, depth = 0): void {
  const err = (rule: string, message: string): void => { f.push({ severity: "error", rule, at, message }); };
  const warn = (rule: string, message: string): void => { f.push({ severity: "warn", rule, at, message }); };
  if (depth > FN_LIMITS.maxExecuteDepth) return err("execute_depth", `execute is nested more than ${FN_LIMITS.maxExecuteDepth} levels deep`);
  const t = tokenize(raw);
  if (!t || !t.length) return err("unreadable", "the command could not be read (unbalanced quotes or brackets)");
  const root = t[0].toLowerCase();
  if (root.includes(":")) return err("namespaced_root", `"${t[0]}" is a namespaced command; functions may only use vanilla commands (plugin commands are refused)`);
