  if (!ALLOWED_COMMANDS.includes(root)) return err("not_allowlisted", `"${root}" is not on Nxeon's allowlist of data pack commands`);
  if (ctx.versionCommands && !ctx.versionCommands.has(root)) return err("unknown_command", `"${root}" is not a command in this Minecraft version`);
