// Cyrus perf safety (2026-10-11): the LIVING AUDIT of the no-model emitters (gameplay designers, motion, data packs,
// worldgen) against the perf rules every generated plugin now follows (services/modbuilder/prompts.js rule 10):
//   R1 bounded work per tick / per activation     R2 entity spawns capped (per activation / plugin-wide)
//   R3 particles capped                            R4 explosions / projectiles capped
//   R5 no world-wide iteration, radius capped      R6 repeating work at a bounded cadence (no unbounded tick work)
//   R7 no recursion through own events / calls     R8 growing state bounded
// Each row reads the REAL constants, so a cap that is loosened (or removed) changes this table and its test
// (test/cyrus-perf-caps.test.ts) fails until someone looks. Pure data; nothing here is enforced at runtime.
import { BUDGET, CAPS, RUNTIME_CAPS } from "../designer/spec";
import { BOSS_LIMITS, BOSS_CAPS } from "../designer/boss/spec";
import { HUD_CAPS } from "../designer/hud/spec";
import { MOTION_LIMITS } from "../motion/spec";
import { FN_LIMITS } from "../datapack/functions";
import { WORLDGEN_LIMITS } from "../datapack/worldgen/spec";

export type PerfRuleId = "R1" | "R2" | "R3" | "R4" | "R5" | "R6" | "R7" | "R8";
export type CapRow = { emitter: string; rule: PerfRuleId; cap: string; value: number | string; status: "ok" | "added-2026-10-11" | "gap"; note?: string };

export const PERF_RULE_TEXT: Record<PerfRuleId, string> = {
  R1: "bounded work per tick / per activation", R2: "entity spawns capped", R3: "particles capped", R4: "explosions and projectiles capped",
  R5: "no world-wide iteration; radius capped", R6: "repeating work at a bounded cadence", R7: "no recursion through own events or calls", R8: "growing state bounded",
};

export function perfCapAudit(): CapRow[] {
  return [
    // item + ability designer (lib/cyrus/designer)
    { emitter: "item designer", rule: "R1", cap: "actions per activation", value: BUDGET.actions, status: "ok" },
    { emitter: "item designer", rule: "R2", cap: "entities per activation", value: BUDGET.entities, status: "ok" },
    { emitter: "item designer", rule: "R3", cap: "particles per activation", value: BUDGET.particles, status: "ok" },
    { emitter: "item designer", rule: "R3", cap: "particles per action", value: CAPS.particleCount[1], status: "ok" },
    { emitter: "item designer", rule: "R4", cap: "projectiles per activation", value: BUDGET.projectiles, status: "ok" },
    { emitter: "item designer", rule: "R5", cap: "nearby query radius (blocks)", value: CAPS.queryNearbyRadius[1], status: "ok" },
    { emitter: "item designer", rule: "R5", cap: "nearby query max entities", value: CAPS.queryMax[1], status: "ok" },
    { emitter: "item designer", rule: "R6", cap: "held_interval period (ticks, minimum)", value: CAPS.periodTicks[0], status: "ok" },
    { emitter: "item designer", rule: "R6", cap: "click abilities without a cooldown: minimum gap per player (ticks)", value: 2, status: "added-2026-10-11", note: "Ability.MIN_GAP_TICKS (components/java.ts): a cooldown-0 click ability could fire on every click packet" },
    { emitter: "item designer", rule: "R6", cap: "live delayed tasks plugin-wide", value: RUNTIME_CAPS.liveTasks, status: "ok" },
    { emitter: "item designer", rule: "R7", cap: "re-entrant activation guard", value: "Designer.enter/exit per player", status: "ok" },
    { emitter: "item designer", rule: "R8", cap: "marks plugin-wide", value: RUNTIME_CAPS.marksTotal, status: "ok" },
    // bosses + encounters
    { emitter: "boss designer", rule: "R2", cap: "summons per attack", value: BOSS_LIMITS.summonsPerAttack, status: "ok" },
    { emitter: "boss designer", rule: "R2", cap: "live minions plugin-wide", value: BOSS_LIMITS.liveMinions, status: "ok" },
    { emitter: "boss designer", rule: "R2", cap: "live bosses plugin-wide", value: BOSS_LIMITS.liveBosses, status: "ok" },
    { emitter: "boss designer", rule: "R2", cap: "encounter mobs plugin-wide", value: BOSS_LIMITS.encounterMobs, status: "ok" },
    { emitter: "boss designer", rule: "R5", cap: "arena radius (blocks)", value: BOSS_CAPS.arenaRadius[1], status: "ok" },
    { emitter: "boss designer", rule: "R6", cap: "one shared AI timer (ticks)", value: BOSS_LIMITS.aiPeriodTicks, status: "ok" },
    { emitter: "boss designer", rule: "R6", cap: "attack interval (ticks, minimum)", value: BOSS_CAPS.intervalTicks[0], status: "ok" },
    // HUD
    { emitter: "HUD designer", rule: "R6", cap: "update period (ticks, minimum)", value: HUD_CAPS.updateTicks[0], status: "ok" },
    // motion props
    { emitter: "motion props", rule: "R2", cap: "display entities per prop (nodes)", value: MOTION_LIMITS.nodes, status: "ok" },
    { emitter: "motion props", rule: "R3", cap: "particle emitters per prop", value: MOTION_LIMITS.emitters, status: "ok" },
    // data pack functions
    { emitter: "data pack", rule: "R1", cap: "commands every tick (whole call graph)", value: FN_LIMITS.maxTickCommands, status: "ok" },
    { emitter: "data pack", rule: "R2", cap: "unconditional summon in a tick function", value: "refused", status: "added-2026-10-11", note: "was a warning: 20 entities per second, forever" },
    { emitter: "data pack", rule: "R3", cap: "particles per command", value: FN_LIMITS.maxParticleCount, status: "added-2026-10-11" },
    { emitter: "data pack", rule: "R3", cap: "particles per command in a tick function", value: FN_LIMITS.maxTickParticleCount, status: "added-2026-10-11" },
    { emitter: "data pack", rule: "R1", cap: "fill/clone blocks per command in a tick function", value: FN_LIMITS.maxTickFillVolume, status: "added-2026-10-11" },
    { emitter: "data pack", rule: "R1", cap: "fill/clone blocks per command (warning above)", value: FN_LIMITS.warnFillVolume, status: "added-2026-10-11" },
    { emitter: "data pack", rule: "R5", cap: "execute as/at @e without a filter in a tick function", value: "warning", status: "added-2026-10-11" },
    { emitter: "data pack", rule: "R5", cap: "forceloaded chunks per pack", value: FN_LIMITS.maxForceloadAdds, status: "ok" },
    { emitter: "data pack", rule: "R7", cap: "call depth (no recursion)", value: FN_LIMITS.maxCallDepth, status: "ok" },
    { emitter: "data pack", rule: "R6", cap: "schedule commands per pack", value: FN_LIMITS.maxScheduleCommands, status: "ok" },
    // worldgen
    { emitter: "worldgen", rule: "R1", cap: "placement attempts per chunk per biome", value: WORLDGEN_LIMITS.attemptsPerBiome, status: "ok" },
    { emitter: "worldgen", rule: "R1", cap: "per-chunk cost ceiling (cost units)", value: WORLDGEN_LIMITS.maxCost, status: "ok" },
    { emitter: "worldgen", rule: "R2", cap: "spawn entries per biome", value: WORLDGEN_LIMITS.spawnsPerBiome, status: "ok" },
    { emitter: "worldgen", rule: "R1", cap: "structure template blocks", value: WORLDGEN_LIMITS.templateBlocks, status: "ok" },
  ];
}

/** Rules with no row at all for an emitter that can do that kind of work (the audit's own gap list). */
export function perfCapGaps(rows: CapRow[] = perfCapAudit()): string[] {
  return rows.filter((r) => r.status === "gap").map((r) => `${r.emitter} ${r.rule}: ${r.cap}`);
}

