  it("an unconditional summon every tick is refused; behind a condition it is a warning", () => {
    assert.ok(rules(tick(["summon minecraft:pig ~ ~ ~"])).includes("error:tick_summon_unbounded"));
    const guarded = rules(tick(["execute if score #t nx_test matches 0 run summon minecraft:pig ~ ~ ~"]));
