// REAL check ON node-2 (not part of the unit suite): does the injected NxPerf watchdog break any golden plugin?
//   scripts/devhost run --lock -- npx tsx test/cyrus-perf-golden-real.ts [--versions 1.21.11,1.21.4] [--out <json>]
// For every hand-written golden plugin (services/modbuilder/golden/plugins/<id>/) and version it supports: lay it out
// as a build-service workspace, inject the watchdog exactly like a build (perf.js inject), javac --release 21 -proc:none
// -Xlint:deprecation,removal against the version's Paper classpath, strict bytecode + source scan. A pass = it compiles
// with zero warnings and zero scan blocks/warnings WITH the watchdog (the harness's own bar). PERF pre-check hits are
// recorded (informational: golden plugins were written before the perf rules).
import { execFileSync } from "node:child_process";
import { cpSync, existsSync, mkdirSync, readFileSync, readdirSync, rmSync, writeFileSync } from "node:fs";
import path from "node:path";

const ROOT = path.resolve(__dirname, "..");
const TF = "/tank/nxeon-build/tmp/testflight";
const JDK = `${TF}/jdk/21`;
const GOLD = path.join(ROOT, "services/modbuilder/golden/plugins");
const RUN = `/tank/nxeon-build/tmp/cyrus-perf/golden-${Date.now().toString(36)}`;
process.env.PATH = `${JDK}/bin:${process.env.PATH}`;
// eslint-disable-next-line @typescript-eslint/no-require-imports
const PERF = require("../services/modbuilder/perf.js");
// eslint-disable-next-line @typescript-eslint/no-require-imports
const SCAN = require("../services/modbuilder/scan.js");
const arg = (k: string) => { const i = process.argv.indexOf(k); return i > 0 ? process.argv[i + 1] : undefined; };
const VERSIONS = (arg("--versions") ?? "1.21.11").split(",");
const vt = (v: string) => v.split(".").map(Number);
const ge = (a: string, b: string) => { const x = vt(a), y = vt(b); for (let i = 0; i < Math.max(x.length, y.length); i++) { const d = (x[i] || 0) - (y[i] || 0); if (d) return d > 0; } return true; };
function walk(dir: string, out: string[] = []): string[] {
  if (!existsSync(dir)) return out;
  for (const e of readdirSync(dir, { withFileTypes: true })) { const p = path.join(dir, e.name); if (e.isDirectory()) walk(p, out); else out.push(p); }
  return out;
}

const results: Record<string, Record<string, unknown>> = {};
let pass = 0, fail = 0, na = 0;
for (const id of readdirSync(GOLD).filter((d) => existsSync(path.join(GOLD, d, "golden.json"))).sort()) {
  const meta = JSON.parse(readFileSync(path.join(GOLD, id, "golden.json"), "utf8"));
  results[id] = {};
  for (const v of VERSIONS) {
    if (meta.minVersion && !ge(v, meta.minVersion)) { results[id][v] = { result: "n/a", reason: `needs ${meta.minVersion}+` }; na++; continue; }
    const ws = path.join(RUN, v, id);
    rmSync(ws, { recursive: true, force: true });
    cpSync(path.join(GOLD, id, "src"), path.join(ws, "src/main/java"), { recursive: true });
    mkdirSync(path.join(ws, "src/main/resources"), { recursive: true });
    if (existsSync(path.join(GOLD, id, "resources"))) cpSync(path.join(GOLD, id, "resources"), path.join(ws, "src/main/resources"), { recursive: true });
    writeFileSync(path.join(ws, "src/main/resources/plugin.yml"), readFileSync(path.join(GOLD, id, "plugin.yml"), "utf8").replace(/@API@/g, v));
    const inj = PERF.inject(ws, {}, {});
    const classes = path.join(ws, "build/classes");
    mkdirSync(classes, { recursive: true });
    const cp = readFileSync(`${TF}/classpath/${v}.txt`, "utf8").replace(/\n/g, "").trim();
    const sources = walk(path.join(ws, "src/main/java")).filter((f) => f.endsWith(".java")).sort();
    let out = "", ok = true, errors = "";
    try { out = execFileSync(`${JDK}/bin/javac`, ["-J-Xmx768m", "--release", "21", "-proc:none", "-encoding", "UTF-8", "-Xlint:deprecation,removal", "-cp", cp, "-d", classes, ...sources], { encoding: "utf8", stdio: ["ignore", "pipe", "pipe"] }); }
    catch (e) { ok = false; const x = e as { stdout?: string; stderr?: string }; errors = `${x.stderr ?? ""}${x.stdout ?? ""}`.split(ws + "/").join("").slice(0, 3000); }
    const warnings = (out.match(/warning: \[[^\]]+\][^\n]*/g) ?? []).slice(0, 10);
    const findings = ok ? [...SCAN.scanBytecode(classes), ...SCAN.scanSource(sources.map((abs) => ({ abs, rel: path.relative(ws, abs) })))] : [];
    const bad = findings.filter((f: { severity: string }) => f.severity !== "pass");
    const perfHits = PERF.perfcheck(sources.map((abs) => ({ abs, rel: path.relative(ws, abs) })), {}).map((h: { rule: string }) => h.rule);
    const good = ok && !warnings.length && !bad.length && inj.injected;
    if (good) pass++; else fail++;
    results[id][v] = { result: good ? "pass" : "fail", injected: inj.injected, mainPatched: inj.mainPatched, configSection: inj.configSection, warnings, scan: bad.map((f: { severity: string; rule: string; where: string }) => `${f.severity}:${f.rule}@${f.where}`), errors: errors || undefined, perfHits };
    if (!good) console.log(`${id} ${v}: FAIL ${errors.slice(0, 400)} ${warnings.join(" ")} ${bad.map((f: { rule: string }) => f.rule).join(",")}`);
  }
}
const summary = { at: new Date().toISOString(), host: "node-2", versions: VERSIONS, plugins: Object.keys(results).length, pass, fail, na, perfHitPlugins: Object.entries(results).filter(([, r]) => Object.values(r).some((x) => ((x as { perfHits?: string[] }).perfHits ?? []).length)).map(([k]) => k) };
console.log(JSON.stringify(summary));
const o = arg("--out");
if (o) writeFileSync(o, JSON.stringify({ ...summary, results }, null, 1));
rmSync(RUN, { recursive: true, force: true });
process.exit(fail ? 1 : 0);

