}

function buildOne(id: string, v: string, watchdog: boolean) {
    const ws = path.join(RUN, v, `${id}-${watchdog ? "wd" : "base"}`);
    rmSync(ws, { recursive: true, force: true });
    cpSync(path.join(GOLD, id, "src"), path.join(ws, "src/main/java"), { recursive: true });
    // per-version overlays like the golden harness: src@<v> (exactly) / src@<v>+ (and newer); the most specific wins
    const overlays = readdirSync(path.join(GOLD, id)).filter((d) => d.startsWith("src@")).map((d) => ({ d, spec: d.slice(4) }))
      .filter(({ spec }) => (spec.endsWith("+") ? ge(v, spec.slice(0, -1)) : spec === v))
      .sort((a, b) => (a.spec.endsWith("+") === b.spec.endsWith("+") ? (ge(a.spec.replace("+", ""), b.spec.replace("+", "")) ? 1 : -1) : a.spec.endsWith("+") ? -1 : 1));
    for (const { d } of overlays) cpSync(path.join(GOLD, id, d), path.join(ws, "src/main/java"), { recursive: true });
    mkdirSync(path.join(ws, "src/main/resources"), { recursive: true });
    if (existsSync(path.join(GOLD, id, "resources"))) cpSync(path.join(GOLD, id, "resources"), path.join(ws, "src/main/resources"), { recursive: true });
    writeFileSync(path.join(ws, "src/main/resources/plugin.yml"), readFileSync(path.join(GOLD, id, "plugin.yml"), "utf8").replace(/@API@/g, v));
    const inj = watchdog ? PERF.inject(ws, {}, {}) : { injected: false, mainPatched: false, configSection: false };
    const classes = path.join(ws, "build/classes");
    mkdirSync(classes, { recursive: true });
    const cp = readFileSync(`${TF}/classpath/${v}.txt`, "utf8").replace(/\n/g, "").trim();
    const sources = walk(path.join(ws, "src/main/java")).filter((f) => f.endsWith(".java")).sort();
    let out = "", ok = true, errors = "";
    try { out = execFileSync(`${JDK}/bin/javac`, ["-J-Xmx768m", "--release", "21", "-proc:none", "-encoding", "UTF-8", "-Xlint:deprecation,removal", "-cp", cp, "-d", classes, ...sources], { encoding: "utf8", stdio: ["ignore", "pipe", "pipe"] }); }
    catch (e) { ok = false; const x = e as { stdout?: string; stderr?: string }; errors = `${x.stderr ?? ""}${x.stdout ?? ""}`.split(ws + "/").join("").slice(0, 3000); }
    const warnings = (out.match(/warning: \[[^\]]+\][^\n]*/g) ?? []).slice(0, 10);
    const findings = ok ? [...SCAN.scanBytecode(classes), ...SCAN.scanSource(sources.map((abs) => ({ abs, rel: path.relative(ws, abs) })))] : [];
    const bad = findings.filter((f: { severity: string }) => f.severity !== "pass");
    const perfHits = PERF.perfcheck(sources.map((abs) => ({ abs, rel: path.relative(ws, abs) })), {}).map((h: { rule: string }) => h.rule);
    const good = ok && !warnings.length && !bad.length;
    return { result: good ? "pass" : "fail", injected: inj.injected, mainPatched: inj.mainPatched, configSection: inj.configSection, warnings, scan: bad.map((f: { severity: string; rule: string; where: string }) => `${f.severity}:${f.rule}@${f.where}`), errors: errors || undefined, perfHits, good };
}

const results: Record<string, Record<string, unknown>> = {};
let pass = 0, fail = 0, na = 0;
for (const id of readdirSync(GOLD).filter((d) => existsSync(path.join(GOLD, d, "golden.json"))).sort()) {
  const meta = JSON.parse(readFileSync(path.join(GOLD, id, "golden.json"), "utf8"));
  results[id] = {};
  for (const v of VERSIONS) {
    if (meta.minVersion && !ge(v, meta.minVersion)) { results[id][v] = { result: "n/a", reason: `needs ${meta.minVersion}+` }; na++; continue; }
    const base = buildOne(id, v, false), wd = buildOne(id, v, true);
    // "broken by the watchdog" = clean without it, not clean with it; a plugin that already fails without it is baseline
    const broke = base.good && !(wd.good && wd.injected);
    if (broke) fail++; else pass++;
    results[id][v] = { result: broke ? "BROKEN by the watchdog" : wd.good ? "pass" : "baseline issue (same without the watchdog)", base: { good: base.good, scan: base.scan, errors: base.errors }, watchdog: wd };
    if (broke) console.log(`${id} ${v}: BROKEN ${String(wd.errors ?? "").slice(0, 400)} ${wd.warnings.join(" ")} ${wd.scan.join(",")}`);
  }
}
const summary = { at: new Date().toISOString(), host: "node-2", versions: VERSIONS, plugins: Object.keys(results).length, pass, fail, na, baselineIssues: Object.entries(results).flatMap(([k, r]) => Object.entries(r).filter(([, x]) => String((x as { result: string }).result).startsWith("baseline")).map(([v]) => `${k}@${v}`)), perfHitPlugins: Object.entries(results).filter(([, r]) => Object.values(r).some((x) => (((x as { watchdog?: { perfHits?: string[] } }).watchdog?.perfHits) ?? []).length)).map(([k]) => k) };
